    { en = "- Unlock the Infuse with Power slot when crafting weapons. |n|n- Unlock a sub-specialization of your choice.", ua = "- Розблокуйте комірку «Наповнення енергією» під час виготовлення зброї. |n|n- Розблокуйте підспеціалізацію на свій вибір." },
    { en = "- Unlock the Missive slot when crafting carveable equipment. |n|n- Unlock a sub-specialization of your choice.", ua = "- Розблокуйте комірку послання під час виготовлення різьблюваного спорядження. |n|n- Розблокуйте підспеціалізацію на свій вибір." },
    { en = "- Unlock the final sub-specialization.|n|n- +$ev1 $en1 when crafting Inscription recipes. |n|n- +$ev2 $en2 when crafting Inscription recipes. |n|n- +$ev3 $en3 when crafting Inscription recipes.", ua = "- Розблокуйте останню підспеціалізацію.|n|n- +$ev1 $en1 під час виготовлення рецептів Накреслення. |n|n- +$ev2 $en2 під час виготовлення рецептів Накреслення. |n|n- +$ev3 $en3 під час виготовлення рецептів Накреслення." },
    { en = "- You may study an extra Algari Treatise on Inscription per week.|n|n- +$ev1 $en1 when crafting Inscription recipes. |n|n- +$ev2 $en2 when crafting Inscription recipes. |n|n- +$ev3 $en3 when crafting Inscription recipes.", ua = "- Ви можете вивчати один додатковий алгарійський трактат з Накреслення на тиждень.|n|n- +$ev1 $en1 під час виготовлення рецептів Накреслення. |n|n- +$ev2 $en2 під час виготовлення рецептів Накреслення. |n|n- +$ev3 $en3 під час виготовлення рецептів Накреслення." },
    { en = "-(NYI) Unlock the Treatise on Inscription recipe.|n|n- Unlock a sub-specialization of your choice.", ua = "-(NYI) Розблокуйте рецепт трактату з Накреслення.|n|n- Розблокуйте підспеціалізацію на свій вибір." },
    { en = "A master of finding rare materials, you gain +$ev1 $en1 while skinning.", ua = "Майстер пошуку рідкісних матеріалів — ви отримуєте +$ev1 $en1 під час білування." },
    { en = "Accentuate your talents at making Profession Tools and Accessories, gaining +$ev1 $en1 when crafting them per point in this Specialization.", ua = "Підкресліть свій хист до виготовлення професійних інструментів та аксесуарів, отримуючи +$ev1 $en1 за їх виготовлення за кожне очко в цій Спеціалізації." },
    { en = "Acts of $@spellname430315 with Mercurial materials now yield a small amount of Ominous Transmutagen.", ua = "Застосування $@spellname430315 до ртутних матеріалів тепер дає невелику кількість Лиховісного трансмутагену." },
    { en = "Acts of $@spellname430315 with Ominous materials now yield a small amount of Volatile Transmutagen.", ua = "Застосування $@spellname430315 до лиховісних матеріалів тепер дає невелику кількість Нестабільного трансмутагену." },
    { en = "Acts of $@spellname430315 with Volatile materials now yield a small amount of Mercurial Transmutagen.", ua = "Застосування $@spellname430315 до нестабільних матеріалів тепер дає невелику кількість Ртутного трансмутагену." },
    { en = "Adaptive crafts are $ev1% faster.|n|nLearn to craft and use the $@spellname391202 Finishing Reagent to improve Skill when crafting Adaptive enchantments.", ua = "Адаптивні вироби виготовляються на $ev1% швидше.|n|nНавчіться створювати й використовувати завершальний реагент $@spellname391202, щоб покращити Уміння під час виготовлення адаптивних чарів." },
    { en = "Air-formulated phials last 30 minutes longer.", ua = "Флакони на основі повітря діють на 30 хвилин довше." },
    { en = "Allows you to attempt to perform acts of $@spellname430315.", ua = "Дозволяє намагатися застосовувати $@spellname430315." },
    { en = "Allows you to use Artisan's Authenticity finishing reagents when crafting bracers.", ua = "Дозволяє використовувати завершальні реагенти «Автентичність ремісника» під час виготовлення наручів." },
    { en = "Allows you to use Artisan's Authenticity finishing reagents when crafting goggles.", ua = "Дозволяє використовувати завершальні реагенти «Автентичність ремісника» під час виготовлення окулярів." },
    { en = "Allows you to use Artisan's Authenticity finishing reagents when crafting guns.", ua = "Дозволяє використовувати завершальні реагенти «Автентичність ремісника» під час виготовлення рушниць." },
    { en = "Allows you to use Artisan's Authenticity finishing reagents when crafting neck designs.", ua = "Дозволяє використовувати завершальні реагенти «Автентичність ремісника» під час виготовлення намист." },
    { en = "Allows you to use Artisan's Authenticity finishing reagents when crafting profession equipment.", ua = "Дозволяє використовувати завершальні реагенти «Автентичність ремісника» під час виготовлення професійного спорядження." },
    { en = "Allows you to use Artisan's Authenticity finishing reagents when crafting reagents.", ua = "Дозволяє використовувати завершальні реагенти «Автентичність ремісника» під час виготовлення реагентів." },
    { en = "Allows you to use Artisan's Authenticity finishing reagents when crafting rings.", ua = "Дозволяє використовувати завершальні реагенти «Автентичність ремісника» під час виготовлення перснів." },
    { en = "Allows you to use Finishing Reagents when cutting gems.", ua = "Дозволяє використовувати завершальні реагенти під час огранювання самоцвітів." },
    { en = "Allows you to use Radiant Finishing Reagents when crafting Jewelry designs.", ua = "Дозволяє використовувати променисті завершальні реагенти під час виготовлення ювелірних виробів." },
    { en = "Allows you to use Spare Parts finishing reagents when crafting goggles and profession equipment.", ua = "Дозволяє використовувати завершальні реагенти «Запчастини» під час виготовлення окулярів та професійного спорядження." },
    { en = "Allows you to use Spare Parts finishing reagents when crafting guns and bracers.", ua = "Дозволяє використовувати завершальні реагенти «Запчастини» під час виготовлення рушниць та наручів." },
    { en = "Allows you to use finishing reagents of all sorts when crafting Parts.", ua = "Дозволяє використовувати будь-які завершальні реагенти під час виготовлення Деталей." },
    { en = "Amount of cloth found from Humanoids in the Dragon Isles increased by 10%.", ua = "Кількість тканини, здобутої з гуманоїдів на Драконових Островах, збільшена на 10%." },
    { en = "Amount of cloth found from Humanoids in the Dragon Isles increased by 20%.", ua = "Кількість тканини, здобутої з гуманоїдів на Драконових Островах, збільшена на 20%." },
    { en = "An invention is only as good as the quality of its parts. Gain +$ev1 $en1 when creating Parts to further improve your ability to make your aspirations real.", ua = "Винахід настільки хороший, наскільки якісні його деталі. Отримуйте +$ev1 $en1 під час створення Деталей, щоб і далі покращувати свою здатність втілювати мрії в життя." },
    { en = "Any damage done by Cariel will heal you for a small amount.", ua = "Будь-яка шкода, завдана Каріель, трохи зцілює вас." },
    { en = "Armor Crafting is $ev1% faster.|n|n+$ev2 $en2 and +$ev3 $en3 when crafting leather armor.", ua = "Виготовлення броні на $ev1% швидше.|n|n+$ev2 $en2 та +$ev3 $en3 під час виготовлення шкіряної броні." },
    { en = "Armor Crafting is $ev1% faster.|n|n+$ev2 $en2 and +$ev3 $en3 when crafting mail armor.", ua = "Виготовлення броні на $ev1% швидше.|n|n+$ev2 $en2 та +$ev3 $en3 під час виготовлення кольчужної броні." },
    { en = "Armor Crafting is $ev1% faster.|n|n+$ev2 $en2 and +$ev3 $en3 when making leather armor.", ua = "Виготовлення броні на $ev1% швидше.|n|n+$ev2 $en2 та +$ev3 $en3 під час виготовлення шкіряної броні." },
    { en = "Armor Crafting is $ev1% faster.|n|n+$ev2 $en2 and +$ev3 $en3 when making mail armor.", ua = "Виготовлення броні на $ev1% швидше.|n|n+$ev2 $en2 та +$ev3 $en3 під час виготовлення кольчужної броні." },
    { en = "Artistry crafts are $ev1% faster.|n|nLearn to craft and use the $@spellname391202 Finishing Reagent to improve Skill when crafting Artistry enchantments.", ua = "Художні вироби виготовляються на $ev1% швидше.|n|nНавчіться створювати й використовувати завершальний реагент $@spellname391202, щоб покращити Уміння під час виготовлення художніх чарів." },
    { en = "As elemental chaos runs rampant across the Dragon Isles, experienced miners have discovered new techniques to tap into remnants of these magics found within these precious metals. Gain +$ev1 $en1 on all elemental deposits per point in this specialization.", ua = "Оскільки Драконовими Островами шаленіє стихійний хаос, досвідчені гірники відкрили нові прийоми, щоб черпати рештки цієї магії, приховані в цих коштовних металах. Отримуйте +$ev1 $en1 на всіх стихійних покладах за кожне очко в цій спеціалізації." },
    { en = "Ascend your Accessory skills, gaining +$ev1 $en1 when crafting them per point in this Specialization.", ua = "Піднесіть свою майстерність виготовлення аксесуарів, отримуючи +$ev1 $en1 за їх виготовлення за кожне очко в цій Спеціалізації." },
    { en = "Attune your disenchanting rituals to the magic of Uncommon Khaz Algar equipment, increasing your Skill by +$ev1 per point in this Specialization when disenchanting such items.", ua = "Налаштуйте свої ритуали знечарування на магію незвичайного спорядження Каз Алґара, підвищуючи Уміння на +$ev1 за кожне очко в цій Спеціалізації під час знечарування таких предметів." },
    { en = "Attune your enchanting matrices to Azeroth, granting your Haranir Weapon, Chest, and Ring enchantments +$ev1 $en1 per point in this Specialization.", ua = "Налаштуйте свої матриці накладання чарів на Азерот, надаючи вашим гаранірським чарам зброї, нагрудника та персня +$ev1 $en1 за кожне очко в цій Спеціалізації." },
    { en = "Attune yourself to the cloth used in the various Midnight societies, improving your ability to find cloth and increase the quality.", ua = "Налаштуйтеся на тканини, що використовуються в різних спільнотах Опівночі, покращуючи свою здатність знаходити тканину та підвищуючи її якість." },
    { en = "Attune yourself to the portals opened by overloading Titan-Touched deposits, allowing you to return to your original location after mining at your destination.", ua = "Налаштуйтеся на портали, що відкриваються при перевантаженні титаноторкнутих покладів, дозволяючи вам повертатися до початкового місця після видобутку в точці призначення." },
    { en = "Attune yourself to the portals opened by overloading Titan-Touched herbs, allowing you to return to your original location after gathering at your destination.", ua = "Налаштуйся на портали, що відкриваються від перевантаження торкнутих Титанами трав, аби повертатися на початкову позицію після збирання в місці призначення." },
    { en = "Attune yourself with the Crystallized herbs of Khaz Algar and resonate with their ancient magic, gaining +$ev1 $en1 per point in this specialization while gathering them.", ua = "Налаштуйся на кристалізовані трави Каз Алґара й резонуй з їхньою прадавньою магією, отримуючи +$ev1 $en1 за кожне очко в цій спеціалізації, коли їх збираєш." },
    { en = "Attune yourself with the Lightfused herbs of Eversong, gaining +$ev1 $en1 per point in this specialization while gathering them.", ua = "Налаштуйся на світлосплавлені трави Лісу Вічної Пісні, отримуючи +$ev1 $en1 за кожне очко в цій спеціалізації, коли їх збираєш." },
    { en = "Attune yourself with the Primal herbs of Harandar, gaining +$ev1 $en1 per point in this specialization while gathering them.", ua = "Налаштуйся на первісні трави Гарандара, отримуючи +$ev1 $en1 за кожне очко в цій спеціалізації, коли їх збираєш." },
    { en = "Attune yourself with the Voidbound herbs of the Voidstorm, gaining +$ev1 $en1 per point in this specialization while gathering them.", ua = "Налаштуйся на пов'язані Порожнечею трави Войдшторму, отримуючи +$ev1 $en1 за кожне очко в цій спеціалізації, коли їх збираєш." },
    { en = "Attune yourself with the Wild herbs of Zul'Aman, gaining +$ev1 $en1 per point in this specialization while gathering them.", ua = "Налаштуйся на дикі трави Зул'Амана, отримуючи +$ev1 $en1 за кожне очко в цій спеціалізації, коли їх збираєш." },
    { en = "Attune yourself with the lands further, granting you a return portal whenever you overload a Crystallized herb.", ua = "Ще глибше налаштуйся на ці землі, отримуючи портал повернення щоразу, коли перевантажуєш кристалізовану траву." },
    { en = "Attuning with the elements improves your senses, gaining +$ev1 $en1 while skinning per point in this Specialization.", ua = "Налаштування на стихії загострює твої чуття, даючи +$ev1 $en1 під час білування за кожне очко в цій спеціалізації." },
    { en = "Become a master of Gainful Gathering, gaining +$ev1 $en1 while skinning in the Midnight region per point in this Specialization.", ua = "Стань майстром Прибуткового збирання, отримуючи +$ev1 $en1 під час білування в регіоні Опівночі за кожне очко в цій спеціалізації." },
    { en = "Become a more discerning and resourceful Blacksmith, improving your ability to save valuable reagents. Gain +$ev1 $en1 while using Everburning Ignition per point in this sub-specialization.", ua = "Стань прискіпливішим і винахідливішим ковалем, покращуючи вміння заощаджувати цінні реагенти. Отримуй +$ev1 $en1, коли використовуєш Вічногоряче Займання, за кожне очко в цій підспеціалізації." },
    { en = "Become a more inspired Alchemist, gaining +$ev1 $en1 per point in this Specialization.", ua = "Стань натхненнішим алхіміком, отримуючи +$ev1 $en1 за кожне очко в цій спеціалізації." },
    { en = "Become a more inspired Blacksmith, gaining +$ev1 $en1 per point in this Specialization.", ua = "Стань натхненнішим ковалем, отримуючи +$ev1 $en1 за кожне очко в цій спеціалізації." },
    { en = "Become a more inspired Jewelcrafter, gaining +$ev1 $en1 per point in this Specialization.", ua = "Стань натхненнішим ювеліром, отримуючи +$ev1 $en1 за кожне очко в цій спеціалізації." },
    { en = "Become a more inspired Scribe, gaining +$ev1 $en1 per point in this Specialization.", ua = "Стань натхненнішим писарем, отримуючи +$ev1 $en1 за кожне очко в цій спеціалізації." },
    { en = "Become a more inspired and imaginative Blacksmith, potentially improving the quality of your crafts. Gain +$ev1 $en1 while using Everburning Ignition per point in this sub-specialization.", ua = "Стань натхненнішим і творчим ковалем, що може покращити якість твоїх виробів. Отримуй +$ev1 $en1, коли використовуєш Вічногоряче Займання, за кожне очко в цій підспеціалізації." },
    { en = "Become an expert at crafting Adaptive enchantments, increasing your skill when crafting enchantments for bracers and cloaks. Gain +$ev1 $en1 per point in this Specialization.", ua = "Стань знавцем створення адаптивних чарів, підвищуючи майстерність, коли створюєш чари для наручів і плащів. Отримуй +$ev1 $en1 за кожне очко в цій спеціалізації." },
    { en = "Become an expert at crafting Artistry enchantments, increasing your skill when crafting enchantments for profession tools. Gain +$ev1 $en1 per point in this Specialization.", ua = "Стань знавцем створення мистецьких чарів, підвищуючи майстерність, коли створюєш чари для професійних інструментів. Отримуй +$ev1 $en1 за кожне очко в цій спеціалізації." },
    { en = "Become an expert at crafting Draconic Treatises associated with various professions, gaining +$ev1 $en1 per point in this Specialization.", ua = "Стань знавцем створення Драконівських Трактатів, пов'язаних із різними професіями, отримуючи +$ev1 $en1 за кожне очко в цій спеціалізації." },
    { en = "Become an expert at crafting Dragon Isles Contracts and Missives, gaining +$ev1 $en1 per point in this Specialization.", ua = "Стань знавцем створення Контрактів і Послань Драконових Островів, отримуючи +$ev1 $en1 за кожне очко в цій спеціалізації." },
    { en = "Become an expert at crafting adventuring gear such as grappling hooks, gaining +$ev1 $en1 per point in this Specialization.", ua = "Стань знавцем створення спорядження для пригод, як-от гаків-кішок, отримуючи +$ev1 $en1 за кожне очко в цій спеціалізації." },
    { en = "Become an expert at crafting axes and polearms, gaining +$ev1 $en1 when crafting axes and polearms per point in this sub-specialization.", ua = "Стань знавцем виготовлення сокир і древкової зброї, отримуючи +$ev1 $en1 при виготовленні сокир і древкової зброї за кожне очко в цій підспеціалізації." },
    { en = "Become an expert at crafting enhancements made from stone for weapons and tools, gaining +$ev1 $en1 per point in this Specialization.", ua = "Стань знавцем виготовлення покращень із каменю для зброї та інструментів, отримуючи +$ev1 $en1 за кожне очко в цій спеціалізації." },
    { en = "Become an expert at crafting long bladed weapons such as swords and glaives, gaining +$ev1 $en1 when crafting long bladed weapons per point in this sub-specialization.", ua = "Стань знавцем виготовлення довгої клинкової зброї, як-от мечів і глеф, отримуючи +$ev1 $en1 при виготовленні довгої клинкової зброї за кожне очко в цій підспеціалізації." },
    { en = "Become an expert at crafting maces, gaining +$ev1 $en1 when crafting maces per point in this sub-specialization.", ua = "Стань знавцем виготовлення булав, отримуючи +$ev1 $en1 при виготовленні булав за кожне очко в цій підспеціалізації." },
    { en = "Become an expert at crafting metal tools and accessories for various professions, gaining +$ev1 $en1 per point in this Specialization.", ua = "Стань знавцем виготовлення металевих інструментів і приладдя для різних професій, отримуючи +$ev1 $en1 за кожне очко в цій спеціалізації." },
    { en = "Become an expert at crafting optional threads used in completing the best crafts, gaining +$ev1 $en1 per point in this specialization.", ua = "Стань знавцем виготовлення додаткових нитей, що використовуються для найкращих виробів, отримуючи +$ev1 $en1 за кожне очко в цій спеціалізації." },
    { en = "Become an expert at crafting plate armor for the hands, gaining +$ev1 $en1 per point in this Specialization.", ua = "Стань знавцем виготовлення латного обладунку для кистей, отримуючи +$ev1 $en1 за кожне очко в цій спеціалізації." },
