    { en = "Become an expert at embroidering both simple items such as polishing cloth, and intricate items such as banners and bags. Gain +$ev1 $en1 per point in this specialization.", ua = "Стань знавцем вишивання як простих речей, як-от полірувальної тканини, так і складних, як-от прапорів і сумок. Отримуй +$ev1 $en1 за кожне очко в цій спеціалізації." },
    { en = "Become an expert at smelting alloys and other special reagents, gaining +$ev1 $en1 per point in this Specialization.", ua = "Стань знавцем виплавляння сплавів та інших особливих реагентів, отримуючи +$ev1 $en1 за кожне очко в цій спеціалізації." },
    { en = "Become an expert at spinning powerful spellthreads used on legwear. Gain +$ev1 $en1 per point in this specialization.", ua = "Стань знавцем прядіння потужних чаросниток для спорядження ніг. Отримуй +$ev1 $en1 за кожне очко в цій спеціалізації." },
    { en = "Become an expert at unraveling cloth and spinning various threads, gaining +$ev1 $en1 per point in this Specialization.", ua = "Стань знавцем розпускання тканини та прядіння різних ниток, отримуючи +$ev1 $en1 за кожне очко в цій спеціалізації." },
    { en = "Become an expert at weaving cloth into bolts, gaining +$ev1 $en1 per point in this Specialization.", ua = "Стань знавцем ткання тканини в сувої, отримуючи +$ev1 $en1 за кожне очко в цій спеціалізації." },
    { en = "Become an expert in Darkmoon Cards of Air as well as craft a more powerful version of the Darkmoon Deck: Dance. Gain +$ev1 $en1 per point in this Specialization.", ua = "Стань знавцем Карт Темного Місяця Повітря, а також навчися створювати потужнішу версію Колоди Темного Місяця: Танець. Отримуй +$ev1 $en1 за кожне очко в цій спеціалізації." },
    { en = "Become an expert in Darkmoon Cards of Earth as well as craft a more powerful version of the Darkmoon Deck: Watcher. Gain +$ev1 $en1 per point in this Specialization.", ua = "Стань знавцем Карт Темного Місяця Землі, а також навчися створювати потужнішу версію Колоди Темного Місяця: Вартовий. Отримуй +$ev1 $en1 за кожне очко в цій спеціалізації." },
    { en = "Become an expert in Darkmoon Cards of Fire as well as craft a more powerful version of the Darkmoon Deck: Inferno. Gain +$ev1 $en1 per point in this Specialization.", ua = "Стань знавцем Карт Темного Місяця Вогню, а також навчися створювати потужнішу версію Колоди Темного Місяця: Пекло. Отримуй +$ev1 $en1 за кожне очко в цій спеціалізації." },
    { en = "Become an expert in Darkmoon Cards of Frost as well as craft a more powerful version of the Darkmoon Deck: Rime. Gain +$ev1 $en1 per point in this Specialization.", ua = "Стань знавцем Карт Темного Місяця Морозу, а також навчися створювати потужнішу версію Колоди Темного Місяця: Паморозь. Отримуй +$ev1 $en1 за кожне очко в цій спеціалізації." },
    { en = "Become and expert at unraveling and weaving cloth. Gain +$ev1 $en1 per point in this specialization.", ua = "Стань знавцем розпускання та ткання тканини. Отримуй +$ev1 $en1 за кожне очко в цій спеціалізації." },
    { en = "Become aware of salvaging scraps of Dawnweave from humanoids around Khaz Algar and learn to craft $@spellname446928s.", ua = "Навчися видобувати клапті Світанкового Плетива з гуманоїдів навколо Каз Алґара та виготовляти $@spellname446928." },
    { en = "Become inspired through your devotion to magical enchantment, gaining +$ev1 $en1 per point in this Specialization.", ua = "Здобудь натхнення через свою відданість магічному зачаруванню, отримуючи +$ev1 $en1 за кожне очко в цій спеціалізації." },
    { en = "Become meticulous in your stitchery, gaining +$ev1 $en1 per point in this Specialization.", ua = "Стань прискіпливим у своєму шитві, отримуючи +$ev1 $en1 за кожне очко в цій спеціалізації." },
    { en = "Become more adept at making the most of your flask reagents. Gain +$ev1 $en1 when crafting Midnight flasks and phials.", ua = "Навчися краще використовувати реагенти для флаконів. Отримуй +$ev1 $en1 при виготовленні флаконів і фіалів Опівночі." },
    { en = "Become more adept at making the most of your potion reagents. Gain +$ev1 $en1 when crafting Midnight potions.", ua = "Навчися краще використовувати реагенти для зіль. Отримуй +$ev1 $en1 при виготовленні зілля Опівночі." },
    { en = "Become more effective at performing Transmutations! Gain +$ev1 $en1 to Midnight Transmutations per point in this specialization.", ua = "Стань ефективнішим у проведенні трансмутацій! Отримуй +$ev1 $en1 до трансмутацій Опівночі за кожне очко в цій спеціалізації." },
    { en = "Become more inspired when crafting Leatherworking Patterns, gaining +$ev1 $en1 per point in this Specialization.", ua = "Ставай натхненнішим, виготовляючи Викрійки шкіряної справи, і здобувай +$ev1 $en1 за кожне очко в цій спеціалізації." },
    { en = "Become more likely to find Dazzling Thorium in Brilliant Silver deposits.", ua = "Ти частіше знаходитимеш Сліпучий торій у покладах Сяйливого срібла." },
    { en = "Become more likely to find Dazzling Thorium in Refulgent Copper deposits.", ua = "Ти частіше знаходитимеш Сліпучий торій у покладах Осяйної міді." },
    { en = "Become more likely to find Dazzling Thorium in Umbral Tin deposits.", ua = "Ти частіше знаходитимеш Сліпучий торій у покладах Тіньового олова." },
    { en = "Become more resistant to Primal vines, reducing the amount you are slowed by.", ua = "Стань витривалішим до первісних лоз, зменшивши спричинене ними уповільнення." },
    { en = "Begin mastering the final type of Prospecting, learning a sub-specialization of your choice.|n|nProspect $ev1% faster.|n|nWhenever you find a gem while Prospecting, you have a chance to find an additional gem.", ua = "Почни опановувати останній вид Розвідування, вивчивши підспеціалізацію на свій вибір.|n|nРозвідування на $ev1% швидше.|n|nЩоразу, коли ти знаходиш самоцвіт під час Розвідування, маєш шанс знайти додатковий самоцвіт." },
    { en = "Begin to finalize your studies, learning the final sub-specialization.", ua = "Почни завершувати своє навчання, вивчивши останню підспеціалізацію." },
    { en = "Begin to master the last disenchanting ritual style, learn the final sub-specialization.", ua = "Почни опановувати останній стиль ритуалу розчаклування, вивчивши останню підспеціалізацію." },
    { en = "Begin to sharpen your skills, learning a sub-specialization of your choice.", ua = "Почни відточувати свої навички, вивчивши підспеціалізацію на свій вибір." },
    { en = "Begin your harvesting training in earnest, learning a sub-specialization of your choice.", ua = "Почни всерйоз опановувати збирання, вивчивши підспеціалізацію на свій вибір." },
    { en = "Begin your journey as a Lasting Leather armor crafter, learning your first sub-specialization.", ua = "Почни свій шлях як майстер обладунків із Тривкої шкіри, вивчивши першу підспеціалізацію." },
    { en = "Begin your journey as a Learned Leatherworker, learning a sub-specialization of your choice.", ua = "Почни свій шлях як Обізнаний шкіряник, вивчивши підспеціалізацію на свій вибір." },
    { en = "Begin your journey as a Safeguarding Scales armor crafter, learning your first sub-specialization.", ua = "Почни свій шлях як майстер обладунків із Захисної луски, вивчивши першу підспеціалізацію." },
    { en = "Begin your journey at making Azeroth a tad more fashionable and learn a sub-specialization of your choice.", ua = "Почни свій шлях до того, щоб зробити Азерот трохи моднішим, і вивчи підспеціалізацію на свій вибір." },
    { en = "Begin your journey in processing techniques, learning a sub-specialization of your choice.", ua = "Почни свій шлях у техніках обробки, вивчивши підспеціалізацію на свій вибір." },
    { en = "Begin your studies in earnest, learning a sub-specialization of your choice.", ua = "Візьмися за навчання всерйоз, вивчивши підспеціалізацію на свій вибір." },
    { en = "Bigachu.", ua = "Біґачу." },
    { en = "Blacksmithing is $ev1% faster.", ua = "Ковальство на $ev1% швидше." },
    { en = "Blacksmithing is $ev1% faster.|n|n+$ev2 $en2 and +$ev3 $en3 when making Blacksmithing goods.", ua = "Ковальство на $ev1% швидше.|n|n+$ev2 $en2 та +$ev3 $en3 під час виготовлення ковальських виробів." },
    { en = "Bolster your Basic Reagents, gaining +$ev1 $en1 while crafting them per point in this Specialization.", ua = "Зміцни свої Базові реагенти, здобуваючи +$ev1 $en1 під час їх виготовлення за кожне очко в цій спеціалізації." },
    { en = "Bombs used outdoors in the Dragon Isles have a reduced cooldown.", ua = "Бомби, застосовані просто неба на Драконових Островах, мають менше перезарядження." },
    { en = "Bottle the essences of Light & Void to create even more wonderful yet terrifying potions. Gain +$ev1 $en1 in Midnight Potion Crafting per point in this specialization.", ua = "Розливай по флаконах есенції Світла й Порожнечі, щоб створювати ще чудовіші, але водночас моторошніші зілля. Здобувай +$ev1 $en1 до виготовлення зіль Опівночі за кожне очко в цій спеціалізації." },
    { en = "Broaden your Securely Shaped knowledge by learning another sub-specialization.", ua = "Розшир свої знання Надійної форми, вивчивши ще одну підспеціалізацію." },
    { en = "Broaden your efforts by learning another sub-specialization of your choice.", ua = "Розшир свої зусилля, вивчивши ще одну підспеціалізацію на свій вибір." },
    { en = "Broaden your horizons by learning another sub-specialization of your choice.", ua = "Розшир свої обрії, вивчивши ще одну підспеціалізацію на свій вибір." },
    { en = "Broaden your studies to a second magical element, learning another sub-specialization of your choice.", ua = "Розшир своє навчання на другу магічну стихію, вивчивши ще одну підспеціалізацію на свій вибір." },
    { en = "Broaden your techniques to include another ore, learning a sub-specialization of your choice.", ua = "Розшир свої техніки, охопивши ще одну руду, і вивчи підспеціалізацію на свій вибір." },
    { en = "Build your knowledge in all of the Midnight ores, learning how to make the most of each deposit.", ua = "Нарощуй знання про всі руди Опівночі, опановуючи, як здобути якнайбільше з кожного покладу." },
    { en = "Cariel Roame has a chance to join you in combat.", ua = "Каріель Роум має шанс приєднатися до тебе в бою." },
    { en = "Cariel lends you one of her holy tomes which contains a healing spell.", ua = "Каріель позичає тобі один зі своїх священних фоліантів, що містить закляття зцілення." },
    { en = "Cariel will apply a Shield of Vengeance on you when she appears.", ua = "Каріель накладе на тебе «Щит помсти», коли з'явиться." },
    { en = "Choose your first focus within the realm of specialty items, learning the first sub-specialization.", ua = "Обери своє перше зосередження в царині спеціальних предметів, вивчивши першу підспеціалізацію." },
    { en = "Cloth drops more often in Eversong Woods and Zul'Aman.", ua = "Тканина частіше випадає в Лісі Вічної Пісні та Зул'Амані." },
    { en = "Cloth drops more often in Harandar and in the Voidstorm.", ua = "Тканина частіше випадає в Гарандарі та Войдштормі." },
    { en = "Consume $ev1% less Concentration when Concentrating on Khaz Algar Enchanting recipes.", ua = "Витрачай на $ev1% менше Зосередження, зосереджуючись на рецептах Накладання чарів Каз Алґару." },
    { en = "Consume $ev1% less Concentration when Concentrating on Midnight formulas.", ua = "Витрачай на $ev1% менше Зосередження, зосереджуючись на формулах Опівночі." },
    { en = "Consume $ev1% less Concentration when crafting Profession Accessories.", ua = "Витрачай на $ev1% менше Зосередження під час виготовлення професійного приладдя." },
    { en = "Consume $ev1% less Concentration when crafting Profession Tools.", ua = "Витрачай на $ev1% менше Зосередження під час виготовлення професійних інструментів." },
    { en = "Consume $ev1% less Concentration when crafting Tool Stones.", ua = "Витрачай на $ev1% менше Зосередження під час виготовлення інструментальних каменів." },
    { en = "Consuming a Dragon Isles potion will grant a brief burst of movement speed.", ua = "Споживання зілля Драконових Островів дарує короткий сплеск швидкості пересування." },
    { en = "Consuming a Dragon Isles potion will heal a portion of your health over time.", ua = "Споживання зілля Драконових Островів поступово відновлює частину твого здоров'я." },
    { en = "Consuming toxic potions has a chance to grant toxic reagents.", ua = "Споживання токсичних зіль має шанс дарувати токсичні реагенти." },
    { en = "Continue to improve at Embroidered Ensembles by learning another sub-specialization.", ua = "Удосконалюйся далі у Вишитих ансамблях, вивчивши ще одну підспеціалізацію." },
    { en = "Continue your journey by learning another sub-specialization of your choice.", ua = "Продовж свій шлях, вивчивши ще одну підспеціалізацію на свій вибір." },
    { en = "Continue your studies in the art of Alluring Accessories, learning a sub-specialization of your choice.", ua = "Продовж навчання мистецтву Звабливих аксесуарів, вивчивши підспеціалізацію на свій вибір." },
    { en = "Continue your studies in the arts of a Learned Leatherworker, learning a second sub-specialization of your choice.", ua = "Продовж навчання мистецтву Обізнаного шкіряника, вивчивши другу підспеціалізацію на свій вибір." },
    { en = "Contracts and Missives craft $ev1% faster.|n|n+$ev2 $en2 when making these crafts.", ua = "Контракти й послання виготовляються на $ev1% швидше.|n|n+$ev2 $en2 під час виготовлення цих виробів." },
    { en = "Craft items more effectively, gaining +$ev1 $en1 per point in this Specialization.", ua = "Виготовляй предмети ефективніше, здобуваючи +$ev1 $en1 за кожне очко в цій спеціалізації." },
    { en = "Crafting Inscription goods is $ev1% faster.|n|n+$ev2 $en2 and +$ev3 $en3 when making Inscription goods.", ua = "Виготовлення виробів письмознавства на $ev1% швидше.|n|n+$ev2 $en2 та +$ev3 $en3 під час виготовлення виробів письмознавства." },
    { en = "Crafting Parts can now sometimes result in spare scrap. You never know when it might come in handy!", ua = "Виготовлення деталей тепер іноді дає зайвий брухт. Ніколи не знаєш, коли він стане в пригоді!" },
    { en = "Crafting bombs is $ev1% faster.", ua = "Виготовлення бомб на $ev1% швидше." },
    { en = "Create marvels of Algari engineering to be utilized in both combat and tradeskills alike!", ua = "Створюй дива алґарської інженерії, придатні як для бою, так і для ремесел!" },
    { en = "Creatures have a chance to drop health globes.", ua = "Істоти мають шанс упустити кулі здоров'я." },
    { en = "Creatures killed while phase diving have a higher chance to drop energy orbs which increase phase diving duration.", ua = "Істоти, убиті під час фазового занурення, мають вищий шанс упустити кулі енергії, що продовжують тривалість фазового занурення." },
    { en = "Crushing and Prospecting is now +$ev1% faster.", ua = "Подрібнення та Розвідування тепер на +$ev1% швидші." },
    { en = "Cute tiny bunny.", ua = "Милесеньке крихітне кроленя." },
    { en = "Damage dealt by bombs while on the Dragon Isles is increased.", ua = "Шкода від бомб на Драконових Островах збільшена." },
    { en = "Damage dealt by mining Molten deposits reduced by 50%.", ua = "Шкода від видобутку розплавлених покладів зменшена на 50%." },
    { en = "Damage taken from Horrific Poison when gathering Weeping deposits is reduced.", ua = "Шкода від «Жахливої отрути» під час видобутку мокрих покладів зменшена." },
    { en = "Damage taken from dislodged dynamite is significantly less lethal.", ua = "Шкода від зрушеного динаміту значно менш смертельна." },
    { en = "Damage taken from the side-effects of drinking Toxic potions and phials is reduced by up to 25%.", ua = "Шкода від побічних ефектів вживання токсичних зіль і фіалів зменшена аж до 25%." },
    { en = "Damage taken from the side-effects of drinking Toxic potions and phials is reduced by up to an additional 25%.", ua = "Шкода від побічних ефектів вживання токсичних зіль і фіалів зменшена ще аж до 25%." },
    { en = "Damaging an enemy with Empyrean Hammer grants you a stack of Sanctification. At 8 stacks, you cast an additional Consecration 3 sec after casting your next Consecration.", ua = "Завдаючи шкоди ворогові Емпірейським молотом, ти отримуєш заряд «Посвячення». За 8 зарядів ти застосовуєш додаткове «Освячення» через 3 сек після наступного «Освячення»." },
    { en = "Dare to share your jeweler's flair with the world, learning the final Alluring Accessories sub-specialization.|n|n+$ev1% $en1 when crafting Accessories.|n|nConsume $ev2% less when Concentrating on crafting Accessories.", ua = "Насмілься поділитися своїм ювелірським хистом зі світом, вивчивши останню підспеціалізацію Звабливих аксесуарів.|n|n+$ev1% $en1 під час виготовлення аксесуарів.|n|nВитрачай на $ev2% менше, зосереджуючись на виготовленні аксесуарів." },
    { en = "Darkmoon Deck Boxes craft $ev1% faster.|n|n+$ev2 $en2 when making Darkmoon Deck Boxes.", ua = "Скриньки колод Темного Місяця виготовляються на $ev1% швидше.|n|n+$ev2 $en2 під час виготовлення Скриньок колод Темного Місяця." },
    { en = "Dedicate yourself solely to mastering boots. Gain +$ev1 $en1 when crafting cloth boots.", ua = "Присвяти себе виключно опануванню чобіт. Здобувай +$ev1 $en1 під час виготовлення тканинних чобіт." },
    { en = "Dedicate yourself to the Moon Goddess, increasing your control over the moon and stars. Infuse your abilities with astral might and call down potent lunar magic from the sky.", ua = "Присвяти себе Місячній Богині, посилюючи свою владу над місяцем і зорями. Наповнюй свої здібності астральною міццю й закликай із неба могутню місячну магію." },
    { en = "Deepen your Botany knowledge, learning a sub-specialization of your choice.", ua = "Поглиб свої знання Ботаніки, вивчивши підспеціалізацію на свій вибір." },
    { en = "Deepen your knowledge of Bolstered Bulwarks armor pieces, learning another sub-specialization of your choice.", ua = "Поглиб свої знання про обладунки Зміцнених бастіонів, вивчивши ще одну підспеціалізацію на свій вибір." },
    { en = "Deepen your knowledge of Embroidered Ensembles by learning another sub-specialization.", ua = "Поглиб свої знання про Вишиті ансамблі, вивчивши ще одну підспеціалізацію." },
    { en = "Deepen your pool of knowledge, learning another sub-specialization of your choice.", ua = "Поглибте свій запас знань, вивчивши ще одну підспеціалізацію на ваш вибір." },
    { en = "Defeating creatures has a chance to create up to 2 additional treasure portals.", ua = "Перемога над істотами дає шанс створити до 2 додаткових скарбових порталів." },
    { en = "Delve further into the mysteries of Rousing and Awakened Decay, gaining +$ev1 $en1 for crafts that use Decay per point in this specialization.", ua = "Зануртеся глибше в таємниці буремного та пробудженого тління, отримуючи +$ev1 $en1 для виробів, що використовують тління, за кожне очко в цій спеціалізації." },
    { en = "Delve further into the mysteries of phials and related alchemist stones, gaining +$ev1 $en1 per point in this specialization.", ua = "Зануртеся глибше в таємниці фіалів і пов'язаних каменів алхіміка, отримуючи +$ev1 $en1 за кожне очко в цій спеціалізації." },
    { en = "Delve further into the mysteries of potions and related alchemist stones, gaining +$ev1 $en1 per point in this specialization.", ua = "Зануртеся глибше в таємниці зіль і пов'язаних каменів алхіміка, отримуючи +$ev1 $en1 за кожне очко в цій спеціалізації." },
    { en = "Delve into Embroidered Ensemble techniques, learning a sub-specialization of your choice.", ua = "Опануйте техніки Вишитих комплектів, вивчивши підспеціалізацію на ваш вибір." },
    { en = "Delve into the secrets behind the Bronze Dragonflight's time magic in your tailoring, gaining +$ev1 $en1 per point in this specialization when making and using Chronocloth.", ua = "Зануртеся в секрети часової магії бронзового роду драконів у своєму кравецтві, отримуючи +$ev1 $en1 за кожне очко в цій спеціалізації під час створення й використання хронотканини." },
    { en = "Develop an affinity for the common fungus of Khaz Algar -- Mycobloom, gaining +$ev1 $en1 per point in this sub-specialization while gathering Mycobloom.", ua = "Розвиньте спорідненість зі звичайним грибом Каз Алґару — Грибоцвітом, отримуючи +$ev1 $en1 за кожне очко в цій підспеціалізації під час збору Грибоцвіту." },
    { en = "Devote your Tailoring Knowledge towards cloth armor to take on the most powerful foes in Khaz Algar, gaining +$ev1 $en1 per point in this Specialization.", ua = "Присвятіть свої кравецькі знання тканинним обладункам, щоб протистояти наймогутнішим ворогам Каз Алґару, отримуючи +$ev1 $en1 за кожне очко в цій спеціалізації." },
    { en = "Devote your time to learning Amani Weapon, Ring, and Chest Armor enchantments, gaining +$ev1 $en1 per point in this Specialization.", ua = "Присвятіть свій час вивченню зачарувань зброї, перснів і нагрудних обладунків амані, отримуючи +$ev1 $en1 за кожне очко в цій спеціалізації." },
    { en = "Dig deep in mastering Earthen Profession Tool formulas, gaining +$ev1 $en1 per point in this Specialization.", ua = "Копайте глибше в опануванні формул ремісничих інструментів земельників, отримуючи +$ev1 $en1 за кожне очко в цій спеціалізації." },
    { en = "Dragon Isles phials last 30 minutes longer.", ua = "Фіали Драконових Островів діють на 30 хвилин довше." },
    { en = "Dust up on the details of Deadly Amethysts, gaining +$ev1 $en1 when cutting them per point in this Specialization.", ua = "Освіжіть знання про смертоносні аметисти, отримуючи +$ev1 $en1 за їхнє огранювання за кожне очко в цій спеціалізації." },
    { en = "Dust up on the details of Deadly Lapises, gaining +$ev1 $en1 when cutting them per point in this Specialization.", ua = "Освіжіть знання про смертоносні лапіси, отримуючи +$ev1 $en1 за їхнє огранювання за кожне очко в цій спеціалізації." },
    { en = "Dust up on the details of Deadly Peridots, gaining +$ev1 $en1 when cutting them per point in this Specialization.", ua = "Освіжіть знання про смертоносні перидоти, отримуючи +$ev1 $en1 за їхнє огранювання за кожне очко в цій спеціалізації." },
    { en = "Elevate your knowledge, learning the final sub-specialization.", ua = "Піднесіть свої знання, вивчивши останню підспеціалізацію." },
    { en = "Embrace the art of formulas related to illusions, equipment, reagents, and consumables, gaining +$ev1 $en1 per point in this Specialization while crafting them.", ua = "Опануйте мистецтво формул для ілюзій, спорядження, реагентів і витратних матеріалів, отримуючи +$ev1 $en1 за кожне очко в цій спеціалізації під час їхнього створення." },
    { en = "Embrace the chaos found within Primal deposits to increase your ability to gather elemental essences and further your understanding of the chaotic elements. Gain +$ev1 $en1 on Primal deposits per point in this specialization.", ua = "Прийміть хаос, що таїться в первинних покладах, щоб посилити свою здатність збирати елементальні есенції та поглибити розуміння хаотичних елементів. Отримуйте +$ev1 $en1 на первинних покладах за кожне очко в цій спеціалізації." },
    { en = "Embrace your potential. Increase efficiency while crafting Void potions by gaining +$ev1 $en1 per point in this specialization.", ua = "Розкрийте свій потенціал. Підвищте ефективність створення зіль Порожнечі, отримуючи +$ev1 $en1 за кожне очко в цій спеціалізації." },
    { en = "Embrace your whimsical side to learn how to create a variety of surprisingly safe inventions to entertain yourself and those around you. Furthermore, your ingenious breakthroughs refund an additional $ev1% of the Concentration spent on Engineering goods per point in this specialization.", ua = "Прийміть свою химерну натуру, щоб навчитися створювати різноманітні напрочуд безпечні винаходи на розвагу собі й оточенню. Ба більше, ваші геніальні прориви повертають додатково $ev1% Зосередження, витраченої на інженерні вироби, за кожне очко в цій спеціалізації." },
    { en = "Empower your Ingenuity, causing ingenious breakthroughs to refund an additional $ev1% of the Concentration spent per point in this Specialization.", ua = "Підсильте свою Кмітливість, завдяки чому геніальні прориви повертають додатково $ev1% витраченої Зосередження за кожне очко в цій спеціалізації." },
    { en = "Empower your ability to magically enhance equipment, improving your talents at creating permanent equipment enchantments.", ua = "Підсильте свою здатність магічно вдосконалювати спорядження, покращуючи свій хист до створення постійних зачарувань спорядження." },
    { en = "Empower your philosopher stone, increasing the maximum number of Transmutation charges you can accrue by $ev1.", ua = "Підсильте свій філософський камінь, збільшивши максимальну кількість зарядів трансмутації, які ви можете накопичити, на $ev1." },
    { en = "Empower your senses when dealing with Renowned Beasts, gaining +$ev1 $en1 when skinning them per point in this Specialization.", ua = "Загостріть свої чуття у поводженні з уславленими звірами, отримуючи +$ev1 $en1 за їхнє свіжування за кожне очко в цій спеціалізації." },
    { en = "Empower your techniques that work with Sunfire and Arcanoweave to create wondrous garments and materials.", ua = "Підсильте свої техніки роботи з сонячним вогнем і арканотканиною для створення чудесного вбрання та матеріалів." },
    { en = "Empyrean Hammer critical strikes increases the size and the damage of next Consecration by 10% up to 50%.", ua = "Критичні удари Емпірейського молота збільшують розмір і шкоду наступного Освячення на 10%, аж до 50%." },
    { en = "Enable the use of Finishing Reagents when crafting gadgets, gizmos, devices, and other miscellaneous crafts.", ua = "Дає змогу використовувати фінішні реагенти під час створення гаджетів, штуковин, пристроїв та інших різноманітних виробів." },
    { en = "Enchanting crafts are $ev1% faster.", ua = "Створення зачарувань на $ev1% швидше." },
    { en = "Enemies in Midnight zones can now drop Arcanoweave.|n|nLearn how to make $@spellname1227926s.", ua = "Вороги в зонах Опівночі тепер можуть скидати арканове плетиво.|n|nНавчіться виготовляти $@spellname1227926." },
    { en = "Enemies in Midnight zones can now drop Sunfire Silk. Learn how to make $@spellname1228060s.", ua = "Вороги в зонах Опівночі тепер можуть скидати шовк сонячного вогню. Навчіться виготовляти $@spellname1228060." },
    { en = "Engineering is $ev1% faster.", ua = "Інженерна справа на $ev1% швидша." },
    { en = "Everburning Ignition charges reset 25% faster and Ingenuity refunds 10% additional Concentration.", ua = "Заряди Вічногорючого займання відновлюються на 25% швидше, а Кмітливість повертає на 10% більше Зосередження." },
    { en = "Expand your Securely Shaped knowledge by learning a sub-specialization.", ua = "Розширте свої знання Надійної форми, вивчивши підспеціалізацію." },
    { en = "Expand your creative prowess, causing Ingenious Breakthroughs to refund an additional $ev1% of the Concentration spent per point in this Specialization.", ua = "Розширте свою творчу майстерність, завдяки чому Геніальні прориви повертають додатково $ev1% витраченої Зосередження за кожне очко в цій спеціалізації." },
    { en = "Expand your elemental knowledge, learning another sub-specialization of your choice.", ua = "Розширте свої знання про елементи, вивчивши ще одну підспеціалізацію на ваш вибір." },
    { en = "Expand your fundamental horizons, learning another sub-specialization of your choice.", ua = "Розширте свої фундаментальні обрії, вивчивши ще одну підспеціалізацію на ваш вибір." },
    { en = "Expand your harvesting repertoire, learning another sub-specialization of your choice.", ua = "Розширте свій збиральницький репертуар, вивчивши ще одну підспеціалізацію на ваш вибір." },
    { en = "Expand your horizons in Advanced Armor, learning another sub-specialization of your choice.", ua = "Розширте свої обрії у Вдосконалених обладунках, вивчивши ще одну підспеціалізацію на ваш вибір." },
    { en = "Expand your innovative mind by elevating the science of inventing to new heights. Gain +$ev1 $en1 toward all Engineering crafts.", ua = "Розширте свій новаторський розум, піднісши науку винахідництва на нові висоти. Отримайте +$ev1 $en1 до всіх інженерних виробів." },
    { en = "Expand your knowledge of the Seeds found in the Midnight region, allowing you to find them more often.", ua = "Розширте свої знання про насіння, що трапляється в регіоні Опівночі, завдяки чому ви знаходитимете його частіше." },
    { en = "Expand your knowledge of the Verdant Seeds found in Khaz Algar, allowing you to find them more often. These seeds can be planted at the Beledar's Bounty in Hallowfall.", ua = "Розширте свої знання про зелене насіння, що трапляється в Каз Алґарі, завдяки чому ви знаходитимете його частіше. Це насіння можна садити біля Щедрості Беледара в Голловфолі." },
    { en = "Expand your knowledge, learning a sub-specialization of your choice.", ua = "Розширте свої знання, вивчивши підспеціалізацію на ваш вибір." },
    { en = "Expand your processing repertoire, learning a sub-specialization of your choice.", ua = "Розширте свій переробний репертуар, вивчивши підспеціалізацію на ваш вибір." },
    { en = "Expand your repertoire to another disenchanting ritual, learning another sub-specialization of your choice.", ua = "Розширте свій репертуар ще одним ритуалом розчаклування, вивчивши ще одну підспеціалізацію на ваш вибір." },
    { en = "Experimentation can now sometimes yield toxic reagents.", ua = "Експериментування тепер інколи дає токсичні реагенти." },
    { en = "Familiarize yourself with the magic of the Worldsoul, granting your Haranir Helm, Shoulder, and Boot enchantments +$ev1 $en1 per point in this Specialization.", ua = "Ознайомтеся з магією Світодуші, що дає вашим гаранірським зачаруванням шоломів, наплічників і чобіт +$ev1 $en1 за кожне очко в цій спеціалізації." },
    { en = "Fauna Runes craft $ev1% faster.|n|nLearn to craft and use the $@spellname391781 Finishing Reagent to improve Skill when crafting Fauna Runes.", ua = "Руни фауни створюються на $ev1% швидше.|n|nНавчіться створювати й використовувати фінішний реагент $@spellname391781 для покращення навички під час створення рун фауни." },
    { en = "Fauna runes craft $ev1% faster.|n|n+$ev2 $en2 when making Fauna Runes.", ua = "Руни фауни створюються на $ev1% швидше.|n|n+$ev2 $en2 під час створення рун фауни." },
    { en = "Finesse has a chance to yield more ore while mining Brilliant Silver.", ua = "Витонченість дає шанс отримати більше руди під час видобутку Сяйливого срібла." },
    { en = "Finesse has a chance to yield more ore while mining Refulgent Copper.", ua = "Витонченість дає шанс отримати більше руди під час видобутку Осяйної міді." },
    { en = "Finesse has a chance to yield more ore while mining Umbral Tin.", ua = "Витонченість дає шанс отримати більше руди під час видобутку Тіньового олова." },
    { en = "Fire Breath's damage over time is increased by 15%. Dream Breath's heal over time is increased by 15%.", ua = "Періодична шкода Вогняного подиху збільшена на 15%. Періодичне зцілення Подиху сну збільшене на 15%." },
    { en = "Focus on Amani Helm, Shoulder, and Boot enchantments, gaining +$ev1 $en1 per point in this Specialization.", ua = "Зосередьтеся на зачаруваннях шоломів, наплічників і чобіт амані, отримуючи +$ev1 $en1 за кожне очко в цій спеціалізації." },
    { en = "Focus on a new type of ore to prospect, learning a sub-specialization of your choice.", ua = "Зосередьтеся на розвідуванні нового типу руди, вивчивши підспеціалізацію на ваш вибір." },
    { en = "Focus on a particular disenchanting ritual style, learning a sub-specialization of your choice.", ua = "Зосередьтеся на певному стилі ритуалу розчаклування, вивчивши підспеціалізацію на ваш вибір." },
    { en = "Focus on a specific field of production, learning a sub-specialization of your choice.|n|n+$ev1 $en1 while crafting Reagents.", ua = "Зосередьтеся на конкретній галузі виробництва, вивчивши підспеціалізацію на ваш вибір.|n|n+$ev1 $en1 під час створення реагентів." },
    { en = "Focus on another Midnight herb, learning another sub-specialization of your choice.", ua = "Зосередьтеся на ще одній траві Опівночі, вивчивши ще одну підспеціалізацію на ваш вибір." },
    { en = "Focus on creating more specialized crafts ranging from Professions Equipment to Reagents and Consumables! Increase the quality of these crafts to support adventurer's and fellow crafters alike.", ua = "Зосередьтеся на створенні спеціалізованіших виробів — від спорядження професій до реагентів і витратних матеріалів! Підвищуйте якість цих виробів на підтримку як шукачів пригод, так і побратимів-ремісників." },
    { en = "Focus on one facet of shattering, learning a sub-specialization of your choice.", ua = "Зосередьтеся на одному аспекті дроблення, вивчивши підспеціалізацію на ваш вибір." },
    { en = "Focus on scale skinning techniques, gaining +$ev1 $en1 while skinning primarily scale-yielding creatures per point in this Specialization.", ua = "Зосередьтеся на техніках свіжування луски, отримуючи +$ev1 $en1 під час свіжування істот, що дають переважно луску, за кожне очко в цій спеціалізації." },
    { en = "Focus on the Arcane nature of the Blue Dragonflight in your tailoring, gaining +$ev1 $en1 per point in this specialization when making and using Azureweave.", ua = "Зосередьтеся на арканній природі синього роду драконів у своєму кравецтві, отримуючи +$ev1 $en1 за кожне очко в цій спеціалізації під час створення й використання лазурної тканини." },
    { en = "Focus on the final lessons of Thoughtful Throughput, learning the final sub-specialization.", ua = "Зосередьтеся на останніх уроках Розважливої продуктивності, вивчивши останню підспеціалізацію." },
    { en = "Focus on the sciences of the plants found in the Midnight region and how to gather them efficiently, gaining +$ev1 $en1 per point in this specialization while gathering herbs.", ua = "Зосередьтеся на науці про рослини, що трапляються в регіоні Опівночі, та на тому, як ефективно їх збирати, отримуючи +$ev1 $en1 за кожне очко в цій спеціалізації під час збору трав." },
    { en = "Focus on the sciences of various plantlife on Khaz Algar and how to gather them efficiently, gaining +$ev1 $en1 per point in this specialization while gathering herbs.", ua = "Зосередьтеся на науці про різноманітну рослинність Каз Алґару та на тому, як ефективно її збирати, отримуючи +$ev1 $en1 за кожне очко в цій спеціалізації під час збору трав." },
    { en = "Focus on the threading the perfect loop, increasing Ingenuity by +$ev1 $en1 per point in this specialization.", ua = "Зосередьтеся на протягуванні ідеальної петлі, підвищуючи Кмітливість на +$ev1 $en1 за кожне очко в цій спеціалізації." },
    { en = "Focus on your Jewelcrafting fundamentals to become a market powerhouse through greater efficiency.", ua = "Зосередьтеся на основах ювелірної справи, щоб стати ринковим велетнем завдяки більшій ефективності." },
    { en = "Focus on your scale gathering techniques, gaining +$ev1 $en1 while skinning scaled creatures in the Midnight region per point in this Specialization.", ua = "Зосередьтеся на своїх техніках збору луски, отримуючи +$ev1 $en1 під час свіжування лускатих істот у регіоні Опівночі за кожне очко в цій спеціалізації." },
    { en = "Focus on your studies of Azeroot, gaining +$ev1 $en1 per point in this sub-specialization while gathering it.", ua = "Зосередьтеся на вивченні Азекореня, отримуючи +$ev1 $en1 за кожне очко в цій підспеціалізації під час його збору." },
    { en = "Focus your efforts into the production of materials, gaining +$ev1 $en1 while Prospecting, Crushing, and creating Reagents per point in this Specialization.", ua = "Спрямуйте свої зусилля на виробництво матеріалів, отримуючи +$ev1 $en1 під час розвідування, подрібнення та створення реагентів за кожне очко в цій спеціалізації." },
    { en = "Focus your efforts on Earthen weapon enchantments, gaining +$ev1 $en1 per point in this Specialization.", ua = "Спрямуйте свої зусилля на зачарування зброї земельників, отримуючи +$ev1 $en1 за кожне очко в цій спеціалізації." },
    { en = "Focus your efforts on making the most of your reagents.", ua = "Зосередьте зусилля на тому, щоб узяти якнайбільше зі своїх реагентів." },
    { en = "Focus your efforts on mass production, gaining +$ev1 $en1 per point in this Specialization when crafting commodities.", ua = "Зосередьте зусилля на масовому виробництві, надаючи +$ev1 $en1 за кожен бал у цій спеціалізації під час створення товарів." },
    { en = "Focus your efforts on processing Amani Lapises, gaining +$ev1 $en1 when cutting them per point in this Specialization.", ua = "Зосередьте зусилля на обробці лазуриту амані, надаючи +$ev1 $en1 за їхнє огранювання за кожен бал у цій спеціалізації." },
    { en = "Focus your efforts on processing Harandar Peridots, gaining +$ev1 $en1 when cutting them per point in this Specialization.", ua = "Зосередьте зусилля на обробці перидотів Гарандара, надаючи +$ev1 $en1 за їхнє огранювання за кожен бал у цій спеціалізації." },
    { en = "Focus your efforts on processing Sanguine Garnets, gaining +$ev1 $en1 when cutting them per point in this Specialization.", ua = "Зосередьте зусилля на обробці кривавих гранатів, надаючи +$ev1 $en1 за їхнє огранювання за кожен бал у цій спеціалізації." },
    { en = "Focus your efforts on processing Tenebrous Amethysts, gaining +$ev1 $en1 when cutting them per point in this Specialization.", ua = "Зосередьте зусилля на обробці темітливих аметистів, надаючи +$ev1 $en1 за їхнє огранювання за кожен бал у цій спеціалізації." },
    { en = "Focus your learnings in another Bolstered Bulwarks armor piece, learning another sub-specialization of your choice.", ua = "Зосередьте навчання на ще одному елементі обладунку Зміцнених Бастіонів, вивчаючи ще одну підспеціалізацію на свій вибір." },
    { en = "Focus your mind on your Leatherworking fundamentals, gaining +$ev1 $en1 per point in this Specialization.", ua = "Зосередьте розум на основах Шкіряної справи, надаючи +$ev1 $en1 за кожен бал у цій спеціалізації." },
    { en = "Focus your skills on creating specialty items beyond standard armor, gaining +$ev1 $en1 per point in this Specialization when crafting specialty items.", ua = "Зосередьте вміння на створенні особливих виробів поза стандартною бронею, надаючи +$ev1 $en1 за кожен бал у цій спеціалізації під час створення особливих виробів." },
    { en = "Focus your studies on another Securely Shaped sub-specialization.", ua = "Зосередьте вивчення на ще одній підспеціалізації Надійної Форми." },
    { en = "Foster your knowledge for the uncommon blossom of Khaz Algar's outdoors -- Blessing Blossom, gaining +$ev1 $en1 per point in this sub-specialization while gathering Blessing Blossom.", ua = "Плекайте знання про незвичайний цвіт просторів Каз Алґару — Благословенний цвіт, надаючи +$ev1 $en1 за кожен бал у цій підспеціалізації під час збирання Благословенного цвіту." },
    { en = "Frost-formulated phials last 30 minutes longer.", ua = "Фіали на основі льоду діють на 30 хвилин довше." },
    { en = "Fully realize your shattering potential, learning the final sub-specialization.", ua = "Повністю розкрийте свій потенціал трощення, вивчивши останню підспеціалізацію." },
    { en = "Further empower your philosopher stone, increasing the frequency in which you can perform transmutations.", ua = "Ще більше підсильте свій філософський камінь, збільшуючи частоту, з якою ви можете виконувати трансмутації." },
    { en = "Further improve in the art of carving idols, gain +$ev1 $en1 when carving idols per point in this specialization.", ua = "Далі вдосконалюйтеся в мистецтві різьблення ідолів, отримуючи +$ev1 $en1 за різьблення ідолів за кожен бал у цій спеціалізації." },
    { en = "Further improve in the art of carving statues, gain +$ev1 $en1 when carving statues per point in this specialization.", ua = "Далі вдосконалюйтеся в мистецтві різьблення статуй, отримуючи +$ev1 $en1 за різьблення статуй за кожен бал у цій спеціалізації." },
    { en = "Further improve in the creation and usage of tinkers specifically rather than gadgets and whirlygigs. Gain +$ev1 $en1 when crafting Tinkers.", ua = "Далі вдосконалюйте створення й використання саме механізмів, а не пристроїв і вертушок. Отримуйте +$ev1 $en1 під час створення механізмів." },
    { en = "Further improve in the creation of ammunition and scopes. Gain +$ev1 $en1 per point in this specialization.", ua = "Далі вдосконалюйте створення боєприпасів і прицілів. Отримуйте +$ev1 $en1 за кожен бал у цій спеціалізації." },
    { en = "Further improve in the creation of combat equipment. Gain +$ev1 $en1 for these crafts per point in this specialization.", ua = "Далі вдосконалюйте створення бойового спорядження. Отримуйте +$ev1 $en1 для цих виробів за кожен бал у цій спеціалізації." },
    { en = "Further improve in the creation of profession equipment, cogwheels, and optional reagents. Gain +$ev1 $en1 for these crafts per point in this specialization.", ua = "Далі вдосконалюйте створення професійного спорядження, зубчастих коліс і необов'язкових реагентів. Отримуйте +$ev1 $en1 для цих виробів за кожен бал у цій спеціалізації." },
    { en = "Further improve in the production of all bombs, gaining +$ev1 $en1 when crafting bombs per point in this specialization.", ua = "Далі вдосконалюйте виробництво всіх бомб, отримуючи +$ev1 $en1 під час створення бомб за кожен бал у цій спеціалізації." },
    { en = "Further improve your connection with Dawnweave, decreasing how quickly you exhaust the magic used to craft Dawnweave Bolts.", ua = "Далі зміцнюйте свій зв'язок зі світанковим плетивом, сповільнюючи те, як швидко ви вичерпуєте магію, потрібну для створення сувоїв світанкового плетива." },
    { en = "Further improve your connection with Duskweave, decreasing how quickly you exhaust the magic used to craft Duskweave Bolts.", ua = "Далі зміцнюйте свій зв'язок із присмерковим плетивом, сповільнюючи те, як швидко ви вичерпуєте магію, потрібну для створення сувоїв присмеркового плетива." },
    { en = "Further improve your connection with the magic of the Blue Dragonflight, decreasing how quickly you exhaust the magic used to craft Azureweave Bolts.", ua = "Далі зміцнюйте свій зв'язок із магією Синього Роду Драконів, сповільнюючи те, як швидко ви вичерпуєте магію, потрібну для створення лазуротканих сувоїв." },
    { en = "Further improve your connection with the magic of the Bronze Dragonflight, decreasing how quickly you exhaust the magic used to craft Chronocloth Bolts.", ua = "Далі зміцнюйте свій зв'язок із магією Бронзового Роду Драконів, сповільнюючи те, як швидко ви вичерпуєте магію, потрібну для створення часотканинних сувоїв." },
    { en = "Further improve your mastery over Arcanoweave and make additional bolts per day.", ua = "Далі вдосконалюйте свою майстерність над арканотканим плетивом і виготовляйте додаткові сувої на день." },
    { en = "Further improve your mastery over Sunfire Silk and make additional bolts per day.", ua = "Далі вдосконалюйте свою майстерність над шовком сонячного вогню і виготовляйте додаткові сувої на день." },
    { en = "Further improve your understanding of the mayhem you are capable of unleashing, reducing the likelihood of tinkers malfunctioning.", ua = "Далі поглиблюйте розуміння хаосу, який ви здатні вивільнити, знижуючи ймовірність збоїв механізмів." },
    { en = "Further increases the yield of gems from hoards.", ua = "Ще більше збільшує здобуток самоцвітів із запасів." },
    { en = "Further specialize in the art of crafting Amulets and other Neck pieces. Gain +$ev1 $en1 to all Neck designs per point in this sub-specialization.", ua = "Спеціалізуйтеся далі в мистецтві створення амулетів та інших нашийних прикрас. Отримуйте +$ev1 $en1 до всіх нашийних виробів за кожен бал у цій підспеціалізації." },
    { en = "Further specialize in the art of crafting Rings. Gain +$ev $en1 to all Ring designs per point in this sub-specialization.", ua = "Спеціалізуйтеся далі в мистецтві створення перснів. Отримуйте +$ev $en1 до всіх перснів за кожен бал у цій підспеціалізації." },
    { en = "Further specialize in the art of crafting profession accessories. Gain +$ev $en1 to all profession accessories designs per point in this sub-specialization.", ua = "Спеціалізуйтеся далі в мистецтві створення професійних аксесуарів. Отримуйте +$ev $en1 до всіх професійних аксесуарів за кожен бал у цій підспеціалізації." },
    { en = "Further specialize in the cutting of $@spellname434541, gaining +$ev1 $en1 for this type of gem cut.", ua = "Спеціалізуйтеся далі на огранюванні $@spellname434541, надаючи +$ev1 $en1 для цього типу огранювання." },
