    { en = "Further study the shattering process, improving your skill at crafting with the element while its shattered power lingers within you.", ua = "Далі вивчайте процес трощення, покращуючи свою вправність у створенні за допомогою стихії, доки її роздроблена сила ще перебуває у вас." },
    { en = "Further your harvesting studies, learning another sub-specialization of your choice.", ua = "Поглибте своє вивчення збирання, вивчаючи ще одну підспеціалізацію на свій вибір." },
    { en = "Further your understanding of Gleaming Transmutagen and its uses. This knowledge improves your mastery of $@spellname430315, increasing your $en1 by $ev1 per point in this specialization.", ua = "Поглибте розуміння осяйного трансмутагену та його застосувань. Це знання покращує вашу майстерність $@spellname430315, підвищуючи вашу $en1 на $ev1 за кожен бал у цій спеціалізації." },
    { en = "Further your understanding of the compounds which make up all things. Gain +$ev1 $en1 to $@spellname430315 and transmutations per point in this specialization.", ua = "Поглибте розуміння сполук, з яких складається все суще. Отримуйте +$ev1 $en1 до $@spellname430315 та трансмутацій за кожен бал у цій спеціалізації." },
