    { en = "Gain 2% crafting speed for 30 seconds when milling herbs, stacking up to 15 times.", ua = "Отримуйте 2% швидкості виготовлення на 30 секунд, коли мелете трави; накопичується до 15 разів." },
    { en = "Gain 5% Breakthrough chance with Phial Experimentation.", ua = "Отримуйте 5% шансу на Прорив під час Експериментування з флаконами." },
    { en = "Gain 5% Breakthrough chance with Potion Experimentation.", ua = "Отримуйте 5% шансу на Прорив під час Експериментування із зіллям." },
    { en = "Gain Multicraft, Resourcefulness, Ingenuity, and additional Skill when crafting alloys.", ua = "Отримуйте Багатовиробництво, Винахідливість, Кмітливість та додаткове Уміння під час виготовлення сплавів." },
    { en = "Gain a better understanding of how to handle your own deathtraps, reducing the likelihood of bombs exploding in your face.", ua = "Ви краще розумієте, як поводитися з власними смертельними пастками, тож бомби рідше вибухають вам в обличчя." },
    { en = "Gain a better understanding of your reagents to improve the likelihood of your experiments yielding satisfying results, gaining +1% increased chance at breakthroughs with Phial Experimentation per point in this specialization.", ua = "Ви краще розумієте свої реагенти, тож ваші експерименти частіше дають задовільні результати: +1% до шансу на прорив під час Експериментування з флаконами за кожен пункт у цій спеціалізації." },
    { en = "Gain a better understanding of your reagents to improve the likelihood of your experiments yielding satisfying results, gaining +1% increased chance at breakthroughs with Potion Experimentation per point in this specialization.", ua = "Ви краще розумієте свої реагенти, тож ваші експерименти частіше дають задовільні результати: +1% до шансу на прорив під час Експериментування із зіллям за кожен пункт у цій спеціалізації." },
    { en = "Gain a portion of a bosses boon for $d after defeating them or canceling the buff at the source.", ua = "Отримуйте частину благословення боса на $d після перемоги над ним або скасувавши підсилення в джерелі." },
    { en = "Gain a second charge of $@spellname1223388.", ua = "Отримуйте другий заряд $@spellname1223388." },
    { en = "Gain a second charge of $@spellname440977.", ua = "Отримуйте другий заряд $@spellname440977." },
    { en = "Gain a small increased chance to gather meat while skinning certain creatures of the Dragon Isles.", ua = "Невеликий додатковий шанс здобути м'ясо під час білування певних істот Драконових Островів." },
    { en = "Gain a third charge of $@spellname1223388.", ua = "Отримуйте третій заряд $@spellname1223388." },
    { en = "Gain a third charge of $@spellname440977.", ua = "Отримуйте третій заряд $@spellname440977." },
    { en = "Gain additional Rousing Essences when mining elemental deposits.", ua = "Отримуйте додаткові бентежні есенції під час видобутку елементальних покладів." },
    { en = "Gain an additional +$ev1 $en1 while affected by $@spellname1235733.", ua = "Отримуйте додатково +$ev1 $en1, поки на вас діє $@spellname1235733." },
    { en = "Gain an additional +$ev1 $en1 while affected by Shattered Essence.", ua = "Отримуйте додатково +$ev1 $en1, поки на вас діє Розтрощена есенція." },
    { en = "Gain an additional charge of $@spellname1230856.", ua = "Отримуйте додатковий заряд $@spellname1230856." },
    { en = "Gain an additional charge of $@spellname423394.", ua = "Отримуйте додатковий заряд $@spellname423394." },
    { en = "Gain an additional charge of $@spellname442615.", ua = "Отримуйте додатковий заряд $@spellname442615." },
    { en = "Gain an additional charge of Overload Infused Deposit.", ua = "Отримуйте додатковий заряд Перевантаження наповненого покладу." },
    { en = "Gain an affinity for the leathery creatures of Khaz Algar, gaining +$ev1 $en1 while skinning leather creatures in Khaz Algar per point in this Specialization.", ua = "Отримайте спорідненість зі шкірястими істотами Каз Алґару: +$ev1 $en1 під час білування шкіряних істот у Каз Алґарі за кожен пункт у цій Спеціалізації." },
    { en = "Gain an extra charge of Everburning Ignition and unlock a sub-specialization of your choice.", ua = "Отримайте додатковий заряд Незгасного займання та розблокуйте підспеціалізацію на свій вибір." },
    { en = "Gain an increased chance to gather Bite-Sized Morsels while skinning.|n|nLearn to craft a $@spellname375786.", ua = "Підвищений шанс здобути Дрібні шматочки під час білування.|n|nНавчіться виготовляти $@spellname375786." },
    { en = "Gain an increased chance to gather species-specific reagents from the creatures of Khaz Algar.", ua = "Підвищений шанс здобути реагенти, властиві певним видам, з істот Каз Алґару." },
    { en = "Gain an increased chance to gather species-specific reagents from the creatures of the Dragon Isles.", ua = "Підвищений шанс здобути реагенти, властиві певним видам, з істот Драконових Островів." },
    { en = "Gain even more ore from Finesse.", ua = "Отримуйте ще більше руди завдяки Вправності." },
    { en = "Gain the ability to craft weapons with higher item levels through the use of optional reagents.|n|nUnlock a sub-specialization of your choice.", ua = "Отримайте здатність виготовляти зброю з вищим рівнем предмета за допомогою необов'язкових реагентів.|n|nРозблокуйте підспеціалізацію на свій вибір." },
    { en = "Gain the ability to gather Exceptional Morsels while skinning.|n|nLearn to craft a $@spellname383094.", ua = "Отримайте здатність здобувати Виняткові шматочки під час білування.|n|nНавчіться виготовляти $@spellname383094." },
    { en = "Gain the ability to include optional reagents into certain jewelry crafts to empower the equipment with a higher item level.", ua = "Отримайте здатність додавати необов'язкові реагенти до певних ювелірних виробів, щоб посилити спорядження вищим рівнем предмета." },
    { en = "Gain the ability to include optional reagents into your idol crafts to empower the equipment with a higher item level.", ua = "Отримайте здатність додавати необов'язкові реагенти до виготовлення ваших ідолів, щоб посилити спорядження вищим рівнем предмета." },
    { en = "Gain the ability to use Finishing Reagents when crafting Tool Stones.", ua = "Отримайте здатність використовувати завершальні реагенти під час виготовлення Інструментальних каменів." },
    { en = "Gain the ability to use Polishing Cloth to add the finishing touches on idols and statues.", ua = "Отримайте здатність використовувати Полірувальну тканину, щоб додавати завершальні штрихи ідолам і статуям." },
    { en = "Gain the ability to use Polishing Cloth to add the finishing touches on jewelry.", ua = "Отримайте здатність використовувати Полірувальну тканину, щоб додавати завершальні штрихи прикрасам." },
    { en = "Gain the following bonuses to all Blacksmithing crafts per point of knowledge spent in this specialization:|n+$ev1 $en1|n+$ev2 $en2|n+$ev3 $en3", ua = "Отримуйте такі бонуси до всіх виробів Ковальства за кожен пункт знань, витрачений у цій спеціалізації:|n+$ev1 $en1|n+$ev2 $en2|n+$ev3 $en3" },
    { en = "Gain the following bonuses to all Blacksmithing crafts: |n+$ev1 $en1|n+$ev2 $en2|n+$ev3 $en3", ua = "Отримуйте такі бонуси до всіх виробів Ковальства: |n+$ev1 $en1|n+$ev2 $en2|n+$ev3 $en3" },
    { en = "Gain two extra charges of Everburning Ignition.", ua = "Отримайте два додаткові заряди Незгасного займання." },
    { en = "Gaining Blessing of Dawn, reduces the cooldown of your Blessing of Freedom by 1 sec, and your other blessing abilities by 2 sec.", ua = "Отримання Благословення Світанку зменшує час перезарядження вашого Благословення Свободи на 1 сек, а інших благословень — на 2 сек." },
    { en = "Gathering a Primal herb will grant an additional charge for your skyriding abilities.", ua = "Збір первісної трави надає додатковий заряд ваших здібностей небесної їзди." },
    { en = "Gathering herbs in the Midnight region will replenish 1 charge of your skyriding abilities.|n|n+$ev1 $en1 while gathering herbs.", ua = "Збір трав у регіоні Опівночі відновлює 1 заряд ваших здібностей небесної їзди.|n|n+$ev1 $en1 під час збору трав." },
    { en = "Get ahead on your haberdashery. Gain +$ev1 $en1 when crafting cloth hats.", ua = "Візьміться до капелюшної справи. Отримуйте +$ev1 $en1 під час виготовлення тканинних капелюхів." },
    { en = "Get extra materials from mining defeated Rumbling Orelings.", ua = "Отримуйте додаткові матеріали, видобуваючи переможених Гуркотливих руднів." },
    { en = "Grand Crusader and Art of War grants you a stack of Sanction. At 8 stacks, your next Avengers Shield or Judgment calls down an Empyrean Hammer on targets hit.", ua = "«Великий Хрестоносець» і «Мистецтво Війни» надають заряд «Санкції». За 8 зарядів ваш наступний «Щит Месника» або «Правосуддя» закликає «Емпірейський Молот» на уражені цілі." },
    { en = "Greatly improve at recovering ore from rich deposits and seams.", ua = "Значно покращте видобуток руди з багатих покладів і жил." },
    { en = "Grow your expertise in wristwear. Gain +$ev1 $en1 while crafting cloth bracers.", ua = "Розвивайте майстерність у наручах. Отримуйте +$ev1 $en1 під час виготовлення тканинних наручів." },
    { en = "Hammer of Wrath increases the critical strike chance of Empyrean Hammer by 50% for 6 sec.", ua = "«Молот Гніву» підвищує шанс критичного удару «Емпірейського Молота» на 50% на 6 сек." },
    { en = "Harness the crafting style of the Nerubians and infuse the resulting items with writhing power, gaining +$ev1 $en1 per point in this sub-specialization when crafting Nerubian items.", ua = "Опануйте виробничий стиль нерубіанців і наповніть створені предмети звивною силою: +$ev1 $en1 за кожен пункт у цій підспеціалізації під час виготовлення нерубіанських предметів." },
    { en = "Harness the energy imbued in threads around Khaz Algar to make powerful cloth gear and reagent items, gaining +$ev1 $en1 per point in this Specialization.", ua = "Опануйте енергію, наповнену в нитках Каз Алґару, щоб виготовляти потужне тканинне спорядження та реагенти: +$ev1 $en1 за кожен пункт у цій Спеціалізації." },
    { en = "Harness the shadows of the depths with Nerubian formulas, gaining +$ev1 $en1 per point in this Specialization.", ua = "Опануйте тіні глибин за допомогою нерубіанських формул: +$ev1 $en1 за кожен пункт у цій Спеціалізації." },
    { en = "Harness your magical formulas to create wands to be utilized by the casters of Azeroth in combat, gaining +$ev1 $en1 per point in this Specialization.", ua = "Опануйте свої магічні формули, щоб створювати чарівні палички для заклиначів Азероту в бою: +$ev1 $en1 за кожен пункт у цій Спеціалізації." },
    { en = "Having mastered the processes of mining, you are now able to gather ore while mounted on the Dragon Isles.|n|nA master of mining processes, you also gain +$ev1 $en1 while mining deposits.", ua = "Опанувавши процеси гірництва, ви тепер можете збирати руду верхи на Драконових Островах.|n|nЯк майстер гірничих процесів, ви також отримуєте +$ev1 $en1 під час видобутку покладів." },
    { en = "Heighten your prowess with Haranir enchantments, gaining +$ev1 $en1 per point in this Specialization.", ua = "Підвищте свою майстерність із гаранірськими чарами: +$ev1 $en1 за кожен пункт у цій Спеціалізації." },
    { en = "High Quality cloth drops more often in Eversong Woods and Zul'Aman.", ua = "Високоякісна тканина частіше випадає в Лісі Вічної Пісні та Зул'Амані." },
    { en = "High Quality cloth drops more often in Harandar and in the Voidstorm.", ua = "Високоякісна тканина частіше випадає в Гарандарі та Войдштормі." },
    { en = "High quality cloth can now drop in Midnight zones.", ua = "Високоякісна тканина тепер може випадати в зонах Опівночі." },
    { en = "High quality cloth drops more often in Midnight Zones.", ua = "Високоякісна тканина частіше випадає в зонах Опівночі." },
    { en = "Hone the magical essences released upon a shatter, improving your Ingenuity and enhancing your Concentration. Additionally, you gain +$ev1 $en1 per point in this Specialization.", ua = "Вдоскональте магічні есенції, що вивільняються під час розтрощення, покращуючи свою Кмітливість і посилюючи Зосередження. Крім того, ви отримуєте +$ev1 $en1 за кожен пункт у цій Спеціалізації." },
    { en = "Hone the magical essences released upon a shatter, improving your Ingenuity for a time. Additionally, your ingenious breakthroughs will refund an additional $ev1% of the Concentration spent per point in this Specialization.", ua = "Вдоскональте магічні есенції, що вивільняються під час розтрощення, покращуючи свою Кмітливість на деякий час. Крім того, ваші кмітливі прориви повертають додатково $ev1% витраченого Зосередження за кожен пункт у цій Спеціалізації." },
    { en = "Hone your Concentration, consuming $ev1% less when Concentrating on Jewelcrafting designs.", ua = "Вдоскональте своє Зосередження, витрачаючи на $ev1% менше під час зосередження на ювелірних кресленнях." },
    { en = "Hone your Concentration, consuming $ev1% less when Concentrating on Leatherworking patterns.", ua = "Вдоскональте своє Зосередження, витрачаючи на $ev1% менше під час зосередження на викрійках Шкіряної справи." },
    { en = "Hone your Concentration, using $ev1% less when Concentrating on Jewelcrafting designs.", ua = "Вдоскональте своє Зосередження, використовуючи на $ev1% менше під час зосередження на ювелірних кресленнях." },
    { en = "Hone your Concentration, using $ev1% less when Concentrating on Leatherworking patterns.", ua = "Вдоскональте своє Зосередження, використовуючи на $ev1% менше під час зосередження на викрійках Шкіряної справи." },
    { en = "Hone your anatomical knowledge of the Renowned Beasts, gaining +$ev1 $en1 when skinning them per point in this Specialization.", ua = "Вдоскональте свої анатомічні знання про Уславлених звірів: +$ev1 $en1 під час їх білування за кожен пункт у цій Спеціалізації." },
    { en = "Hone your craft on a specific Advanced Armor piece, learning a sub-specialization of your choice.", ua = "Вдоскональте свою майстерність на певному елементі Вдосконаленої броні, вивчивши підспеціалізацію на свій вибір." },
    { en = "Hone your knowledge for Tranquility Bloom, gaining +$ev1 $en1 per point in this sub-specialization while gathering it.", ua = "Вдоскональте свої знання про Квіт Спокою: +$ev1 $en1 за кожен пункт у цій підспеціалізації під час його збору." },
    { en = "Hone your senses, gaining +$ev1 $en1 while skinning in the Midnight region per point in this Specialization.", ua = "Вигостріть свої чуття: +$ev1 $en1 під час білування в регіоні Опівночі за кожен пункт у цій Спеціалізації." },
    { en = "Hone your skills as a jeweler, gaining +$ev1 $en1 when fitting jewelry per point in this specialization.", ua = "Вдоскональте свою майстерність ювеліра: +$ev1 $en1 під час припасування прикрас за кожен пункт у цій спеціалізації." },
    { en = "Hone your skills at consumable creation formulas, learning how to more efficiently create reagents and mana oils, gaining +$ev1 $en1 per point in this Specialization.", ua = "Вдоскональте свою майстерність у формулах створення витратних предметів, навчившись ефективніше створювати реагенти та манаолії: +$ev1 $en1 за кожен пункт у цій Спеціалізації." },
    { en = "Hone your skills at crafting profession equipment, gaining +$ev1 $en1 when crafting profession equipment per point in this sub-specialization.", ua = "Вдоскональте свою майстерність у виготовленні професійного спорядження: +$ev1 $en1 під час виготовлення професійного спорядження за кожен пункт у цій підспеціалізації." },
    { en = "Hone your skills at gathering usable morsels in the Dragon Isles, gaining a slightly increased chance to find morsels while skinning per point in this Specialization.", ua = "Вдоскональте свою майстерність у здобуванні придатних шматочків на Драконових Островах: трохи підвищений шанс знайти шматочки під час білування за кожен пункт у цій Спеціалізації." },
    { en = "Hone your skills at making various lures to help reel in specific species of fish. Additionally, gain +$ev1 $en1 while skinning in Khaz Algar per point in this Specialization.", ua = "Вдоскональте свою майстерність у виготовленні різних принад, щоб виловлювати певні види риб. Крім того, отримуйте +$ev1 $en1 під час білування в Каз Алґарі за кожен пункт у цій Спеціалізації." },
    { en = "Hone your skills to craft more consumables and reagents, gaining +$ev1 $en1 per point in this Specialization when crafting consumables and reagents.", ua = "Вдоскональте свою майстерність, щоб виготовляти більше витратних предметів і реагентів: +$ev1 $en1 за кожен пункт у цій Спеціалізації під час виготовлення витратних предметів і реагентів." },
    { en = "Hone your skills to lure out bigger game. Additionally, gain +$ev1 $en1 while skinning in Khaz Algar per point in this Specialization.", ua = "Вдоскональте свою майстерність, щоб приваблювати більшу дичину. Крім того, отримуйте +$ev1 $en1 під час білування в Каз Алґарі за кожен пункт у цій Спеціалізації." },
    { en = "Hone your techniques for producing Basic Reagents, gaining +$ev1 $en1 per point in this Specialization when crafting them.", ua = "Вдоскональте свої техніки виробництва базових реагентів: +$ev1 $en1 за кожен пункт у цій Спеціалізації під час їх виготовлення." },
    { en = "Ignite the forge and learn useful techniques to improve your crafts. Gain +$ev1 Ingenuity, Multicraft, and Resourcefulness per point in this specialization.", ua = "Розпаліть горно і опануйте корисні техніки, щоб покращити свої вироби. Отримуйте +$ev1 до Кмітливості, Багатовиробництва та Винахідливості за кожен пункт у цій спеціалізації." },
    { en = "Imbue more energy into your Reshii Wraps, enhancing its power.|n|nAn ethereal presence now lingers in Khaz Algar Delves, revealing secret rooms.|n|nYou may now find phase orbs that increase your primary stat while Phase Diving. Phase orbs have a chance to recover a Phase-Lost appearance.", ua = "Наповніть свої Обгортки Реші більшою енергією, посилюючи їхню міць.|n|nУ Глибинах Каз Алґару тепер витає ефірна присутність, відкриваючи таємні кімнати.|n|nТепер ви можете знаходити фазові сфери, що підвищують вашу основну характеристику під час Фазового занурення. Фазові сфери мають шанс відновити втрачений у фазі образ." },
    { en = "Imbue more energy into your Reshii Wraps, enhancing its power.|n|nEnemies killed while Phase Diving now have a chance to drop a phase orb that increases your primary stat. Phase orbs have a chance to recover a Phase-Lost appearance.|n|nYou may now ride Phase-Lost Slatebacks when Phase Diving.", ua = "Наповни свої Пов'язки Решії ще більшою енергією, посилюючи їхню міць.|n|nВороги, убиті під час Фазового занурення, тепер мають шанс скинути фазову кулю, що підвищує твою основну характеристику. Фазові кулі мають шанс відновити загублений у фазі образ.|n|nТепер під час Фазового занурення ти можеш їздити верхи на загублених у фазі сланцеспинах." },
    { en = "Imbue more energy into your Reshii Wraps, enhancing its power.|n|nUnlock the appearances of the Reshii Cowl and Reshii Scrolls.", ua = "Наповни свої Пов'язки Решії ще більшою енергією, посилюючи їхню міць.|n|nВідкрий образи Каптура Решії та Сувоїв Решії." },
    { en = "Imbue more energy into your Reshii Wraps, enhancing its power.|n|nYou can now see treasures in K'aresh while Phase Diving.", ua = "Наповни свої Пов'язки Решії ще більшою енергією, посилюючи їхню міць.|n|nТепер під час Фазового занурення ти бачиш скарби на Кареші." },
