    { en = "Improve at making the largest armor pieces, including those for the chest and legs, as well as shields, gaining +$ev1 $en1 per point in this Specialization.", ua = "Покращуй виготовлення найбільших елементів броні, зокрема для грудей і ніг, а також щитів, отримуючи +$ev1 $en1 за кожен бал у цій спеціалізації." },
    { en = "Improve at making the smallest plate armor pieces, including those for the waist, wrists and hands, gaining +$ev1 $en1 per point in this Specialization.", ua = "Покращуй виготовлення найменших елементів латної броні, зокрема для пояса, зап'ясть і кистей, отримуючи +$ev1 $en1 за кожен бал у цій спеціалізації." },
    { en = "Improve at making various bladed weapons and tools, gaining +$ev1 $en1 per point in this Specialization.", ua = "Покращуй виготовлення різноманітної клинкової зброї та інструментів, отримуючи +$ev1 $en1 за кожен бал у цій спеціалізації." },
    { en = "Improve at making weapons and large tools, gaining +$ev1 $en1 per point in this Specialization.", ua = "Покращуй виготовлення зброї та великих інструментів, отримуючи +$ev1 $en1 за кожен бал у цій спеціалізації." },
    { en = "Improve at milling various herbs in the Dragon Isles, gaining +$ev1 $en1 per point in this Specialization.", ua = "Покращуй перемелювання різних трав на Драконових Островах, отримуючи +$ev1 $en1 за кожен бал у цій спеціалізації." },
    { en = "Improve at modifying equipment for your every need, increasing your skill when crafting enchantments for bracers, chestpieces, cloaks, rings, and profession tools. Gain +$ev1 $en1 per point in this specialization.", ua = "Покращуй модифікацію спорядження на будь-який випадок, підвищуючи свою навичку при створенні чарів для наручів, нагрудників, плащів, перснів та професійних інструментів. Отримуй +$ev1 $en1 за кожен бал у цій спеціалізації." },
    { en = "Improve at perceiving magical sources, allowing you to discover Mystic items from enemies and treasures in the Dragon Isles that can be disenchanted into reagents. Gain +$ev1% chance to locate Mystic items per point in this specialization.", ua = "Покращуй сприйняття магічних джерел, що дозволяє знаходити містичні предмети у ворогів і скарбах на Драконових Островах, які можна розчаклувати на реагенти. Отримуй +$ev1% шансу знайти містичні предмети за кожен бал у цій спеціалізації." },
    { en = "Improve at specialty recipes such as those for alchemical reagents and incenses, gaining +$ev1 $en1 for these crafts per point in this specialization.", ua = "Покращуй спеціальні рецепти, як-от для алхімічних реагентів та пахощів, отримуючи +$ev1 $en1 для цих виробів за кожен бал у цій спеціалізації." },
    { en = "Improve at tailoring Cloth Armor to take on the most powerful foes in the Dragon Isles, gaining +$ev1 $en1 per point in this Specialization.", ua = "Покращуй кравецтво тканинної броні, щоб долати найпотужніших ворогів на Драконових Островах, отримуючи +$ev1 $en1 за кожен бал у цій спеціалізації." },
    { en = "Improve at tailoring the embelishments of an outfit such as Hand, Feet, Head, and Back pieces. Gain +$ev1 $en1 per point in this Specialization.", ua = "Покращуй кравецтво оздоблень вбрання, як-от елементів для кистей, стоп, голови та спини. Отримуй +$ev1 $en1 за кожен бал у цій спеціалізації." },
    { en = "Improve at tailoring the embelishments of an outfit such as hand, feet, head, and back pieces. Gain +$ev1 $en1 per point in this Specialization.", ua = "Покращуй кравецтво оздоблень вбрання, як-от елементів для кистей, стоп, голови та спини. Отримуй +$ev1 $en1 за кожен бал у цій спеціалізації." },
    { en = "Improve at tailoring the embellishments of an outfit such as Hand, Feet, Head, and Back pieces. Gain +$ev1 $en1 per point in this Specialization.", ua = "Покращуй кравецтво оздоблень вбрання, як-от елементів для кистей, стоп, голови та спини. Отримуй +$ev1 $en1 за кожен бал у цій спеціалізації." },
    { en = "Improve at tailoring the embellishments of an outfit such as Waist, Shoulder, and Wrist pieces. Gain +$ev1 $en1 per point in this Specialization.", ua = "Покращуй кравецтво оздоблень вбрання, як-от елементів для пояса, плечей та зап'ясть. Отримуй +$ev1 $en1 за кожен бал у цій спеціалізації." },
    { en = "Improve at tailoring the equipment such as shoulders, wrists, and belts. Gain +$ev1 $en1 per point in this Specialization.", ua = "Покращуй кравецтво спорядження, як-от для плечей, зап'ясть та поясів. Отримуй +$ev1 $en1 за кожен бал у цій спеціалізації." },
    { en = "Improve at tailoring the major aspects of an outfit such as Chest and Leg pieces of armor, gaining +$ev1 $en1 per point in this Specialization.", ua = "Покращуй кравецтво головних елементів вбрання, як-от елементів броні для грудей і ніг, отримуючи +$ev1 $en1 за кожен бал у цій спеціалізації." },
    { en = "Improve at tailoring the major aspects of an outfit such as chest and leg pieces of armor, gaining +$ev1 $en1 per point in this Specialization.", ua = "Покращуй кравецтво головних елементів вбрання, як-от елементів броні для грудей і ніг, отримуючи +$ev1 $en1 за кожен бал у цій спеціалізації." },
    { en = "Improve at the art of Inscription and utilizing various reagents, gaining +$ev1 $en1 per point in this Specialization.", ua = "Покращуй мистецтво Накреслення та використання різних реагентів, отримуючи +$ev1 $en1 за кожен бал у цій спеціалізації." },
    { en = "Improve at the art of archiving various texts, gaining +$ev1 $en1 per point in this Specialization.|n|nArchiving goods include Darkmoon Deck Boxes, Contracts, Missives, Draconic Treatises, and Scale Sigils.", ua = "Покращуй мистецтво архівування різних текстів, отримуючи +$ev1 $en1 за кожен бал у цій спеціалізації.|n|nДо архівних виробів належать Коробки колод Темного Місяця, контракти, послання, драконічні трактати та лускаті сигіли." },
    { en = "Improve at the art of binding runic items that provide both crafting and combat utility, gaining +$EV1 $EN1 per point in this Specialization.|n|nRunebinding goods include Profession Tools, Staves, Codexes, Vantus Runes, and Fauna Runes.", ua = "Покращуй мистецтво зв'язування рунічних предметів, що дають користь як у виготовленні, так і в бою, отримуючи +$EV1 $EN1 за кожен бал у цій спеціалізації.|n|nДо рунов'язальних виробів належать професійні інструменти, посохи, кодекси, руни Вантуса та руни фауни." },
    { en = "Improve at the art of blacksmithing, gaining +$ev1 $en1 per point in this specialization.", ua = "Покращуй мистецтво Ковальства, отримуючи +$ev1 $en1 за кожен бал у цій спеціалізації." },
    { en = "Improve at the art of carving intricate designs into stone, gain +$ev1 $en1 when carving idols or statues per point in this specialization.", ua = "Покращуй мистецтво різьблення складних візерунків по каменю, отримуючи +$ev1 $en1 при вирізьблюванні ідолів чи статуй за кожен бал у цій спеціалізації." },
    { en = "Improve at the art of jewelcrafting, gaining +$ev1 $en1 per point in this specialization.", ua = "Покращуй мистецтво Ювелірства, отримуючи +$ev1 $en1 за кожен бал у цій спеціалізації." },
    { en = "Improve at the art of tailoring, gaining +$ev1 $en1 per point in this specialization.", ua = "Покращуй мистецтво Кравецтва, отримуючи +$ev1 $en1 за кожен бал у цій спеціалізації." },
    { en = "Improve at the delicate art of fitting jewelry and carving stone, gaining +$ev1 $en per point in this specialization.", ua = "Покращуй витончене мистецтво оправлення прикрас та різьблення по каменю, отримуючи +$ev1 $en за кожен бал у цій спеціалізації." },
    { en = "Improve at the fundamentals of mining all Khaz Algar deposits. You gain +$ev1 $en1 per point in this specialization.", ua = "Покращуй основи видобутку всіх покладів Каз Алґару. Ти отримуєш +$ev1 $en1 за кожен бал у цій спеціалізації." },
    { en = "Improve at the more industrial aspects of Blacksmithing, gaining +$ev1 $en1 when crafting profession equipment and consumables per point in this specialization.", ua = "Покращуй промисловіші аспекти Ковальства, отримуючи +$ev1 $en1 при виготовленні професійного спорядження та розхідників за кожен бал у цій спеціалізації." },
    { en = "Improve at understanding magical properties and their applications, increasing your skill when crafting enchantments. Gain +$ev1 $en1 per point in this Specialization.", ua = "Покращуй розуміння магічних властивостей та їх застосування, підвищуючи свою навичку при створенні чарів. Отримуй +$ev1 $en1 за кожен бал у цій спеціалізації." },
    { en = "Improve at using your Herbalism tools, gaining +$ev1 $en1 per point in this specialization while gathering herbs.", ua = "Покращуй користування інструментами Травництва, отримуючи +$ev1 $en1 за кожен бал у цій спеціалізації під час збору трав." },
    { en = "Improve at utilizing your tool and reagents effectively and efficiently, increasing your skill at crafting enchantments and Enchanting goods. Gain +$ev1 $en1 per point in this Specialization.", ua = "Покращуй ефективне й раціональне використання інструментів і реагентів, підвищуючи свою навичку при створенні чарів та виготовленні виробів Накладання чарів. Отримуй +$ev1 $en1 за кожен бал у цій спеціалізації." },
    { en = "Improve at your Enchanting matrices, increasing your probability of producing additional items when crafting illusions or consumables. Additionally, you will gain +$ev1 $en1 per point in this Specialization.", ua = "Покращуй свої матриці Накладання чарів, підвищуючи ймовірність створення додаткових предметів при виготовленні ілюзій чи розхідників. Крім того, ти отримуєш +$ev1 $en1 за кожен бал у цій спеціалізації." },
    { en = "Improve at your Enchanting matrices, increasing your probability of producing additional items when crafting illusions or reagents. Additionally, you will gain +$ev1 $en1 per point in this Specialization.", ua = "Покращуй свої матриці Накладання чарів, підвищуючи ймовірність створення додаткових предметів при виготовленні ілюзій чи реагентів. Крім того, ти отримуєш +$ev1 $en1 за кожен бал у цій спеціалізації." },
    { en = "Improve at your Tailoring crafts and learn to collect cloth from humanoids more effectively, gaining increased chance for all cloth to drop in Khaz Algar by 1% per point in this specialization.", ua = "Покращуй свої кравецькі вироби та навчися ефективніше збирати тканину з гуманоїдів, підвищуючи шанс випадання будь-якої тканини в Каз Алґарі на 1% за кожен бал у цій спеціалізації." },
    { en = "Improve at your general harvesting skills, gaining +$ev1 $en1 per point in this specialization while gathering herbs.", ua = "Покращуй загальні навички збирання, отримуючи +$ev1 $en1 за кожен бал у цій спеціалізації під час збору трав." },
    { en = "Improve at your general skinning techniques, learning how to gather, prepare, and store the various standard reagents you can gather from the creatures of Khaz Algar.", ua = "Покращуй загальні техніки білування, вивчаючи, як збирати, обробляти та зберігати різноманітні стандартні реагенти, які можна здобути з істот Каз Алґару." },
    { en = "Improve at your general skinning techniques, learning how to gather, prepare, and store the various standard reagents you can gather from the creatures of Midnight.", ua = "Покращуй загальні техніки білування, вивчаючи, як збирати, обробляти та зберігати різноманітні стандартні реагенти, які можна здобути з істот Опівночі." },
    { en = "Improve in crafting Staves and Off-hand weapons, gaining +$ev1 $en1 per point in this sub-specialization", ua = "Покращуй виготовлення посохів та зброї другої руки, отримуючи +$ev1 $en1 за кожен бал у цій підспеціалізації" },
    { en = "Improve in the business of jewelcrafting, gaining +$ev1 $en1 for prospecting, reagents of all kinds, and profession equipment per point in this specialization.", ua = "Покращуй ремесло Ювелірства, отримуючи +$ev1 $en1 для сортування руди, реагентів усіх видів та професійного спорядження за кожен бал у цій спеціалізації." },
    { en = "Improve in the delicate task of prospecting to increase yield and efficiency, gaining +$ev1 $en1 when prospecting per point in this specialization.", ua = "Покращуй витончену справу сортування руди задля збільшення виходу та ефективності, отримуючи +$ev1 $en1 при сортуванні за кожен бал у цій спеціалізації." },
