    { en = "Learn how to create a $@spellname382369, a toy that allows party and raid members to perceive their surrounding environment in unexpected but familiar ways.", ua = "Навчіться створювати $@spellname382369 — іграшку, що дозволяє членам групи та рейду сприймати навколишнє середовище несподіваними, але знайомими способами." },
    { en = "Learn how to create a $@spellname382370, a toy that allows you to view the world as though it were overrun with gnolls.", ua = "Навчіться створювати $@spellname382370 — іграшку, що дозволяє бачити світ так, наче його заполонили гноли." },
    { en = "Learn how to create a $@spellname382371, a toy that propels you far into the sky! It's probably safe, because you said so.", ua = "Навчіться створювати $@spellname382371 — іграшку, що підкидає вас високо в небо! Напевно, це безпечно, бо ви так сказали." },
