    { en = "Learn how to further improve hides, refining them from |A:Professions-Icon-Quality-Tier2-Small:20:20|a to |A:Professions-Icon-Quality-Tier3-Small:20:20|a. In addition, learn the final sub-specialization.", ua = "Навчіться ще краще обробляти шкури, переробляючи їх з |A:Professions-Icon-Quality-Tier2-Small:20:20|a на |A:Professions-Icon-Quality-Tier3-Small:20:20|a. Крім того, вивчіть останню підспеціалізацію." },
    { en = "Learn how to further improve leather, refining it from |A:Professions-Icon-Quality-Tier2-Small:20:20|a to |A:Professions-Icon-Quality-Tier3-Small:20:20|a.", ua = "Навчіться ще краще обробляти шкіру, переробляючи її з |A:Professions-Icon-Quality-Tier2-Small:20:20|a на |A:Professions-Icon-Quality-Tier3-Small:20:20|a." },
    { en = "Learn how to further improve scales, refining them from |A:Professions-Icon-Quality-Tier2-Small:20:20|a to |A:Professions-Icon-Quality-Tier3-Small:20:20|a.", ua = "Навчіться ще краще обробляти луску, переробляючи її з |A:Professions-Icon-Quality-Tier2-Small:20:20|a на |A:Professions-Icon-Quality-Tier3-Small:20:20|a." },
    { en = "Learn how to gather Khaz Algar herbs while mounted.", ua = "Навчіться збирати трави Каз Алґара верхи на їздовій тварині." },
    { en = "Learn how to gather Midnight herbs while mounted.", ua = "Навчіться збирати трави Опівночі верхи на їздовій тварині." },
    { en = "Learn how to handle altered herbs deep under Khaz Algar, resisting their dangerous side effects while gathering precious resources. Gain +$ev1 $en1 per point in this specialization while gathering them.", ua = "Навчіться поводитися зі зміненими травами глибоко під Каз Алґаром, протистоячи їхнім небезпечним побічним ефектам під час збирання цінних ресурсів. Отримуйте +$ev1 $en1 за кожен бал у цій спеціалізації під час їх збирання." },
    { en = "Learn how to handle the uncommon herb of Khaz Algar's outdoors -- Arathor's Spear, gaining +$ev1 $en1 per point in this sub-specialization while gathering it.", ua = "Навчіться поводитися з незвичайною травою відкритих просторів Каз Алґара — Списом Аратора, отримуючи +$ev1 $en1 за кожен бал у цій підспеціалізації під час її збирання." },
    { en = "Learn how to identify rare materials belonging to particular species of creatures, gaining +$ev1 $en1 while skinning in Khaz Algar per point in this Specialization.", ua = "Навчіться розпізнавати рідкісні матеріали, що належать певним видам істот, отримуючи +$ev1 $en1 під час білування в Каз Алґарі за кожен бал у цій спеціалізації." },
    { en = "Learn how to improve lower quality hides, refining them from |A:Professions-Icon-Quality-Tier1-Small:20:20|a to |A:Professions-Icon-Quality-Tier2-Small:20:20|a.", ua = "Навчіться покращувати шкури нижчої якості, переробляючи їх з |A:Professions-Icon-Quality-Tier1-Small:20:20|a на |A:Professions-Icon-Quality-Tier2-Small:20:20|a." },
    { en = "Learn how to improve lower quality hides, refining them from |A:Professions-Icon-Quality-Tier1-Small:20:20|a to |A:Professions-Icon-Quality-Tier2-Small:20:20|a. Also learn a sub-specialization of your choice.", ua = "Навчіться покращувати шкури нижчої якості, переробляючи їх з |A:Professions-Icon-Quality-Tier1-Small:20:20|a на |A:Professions-Icon-Quality-Tier2-Small:20:20|a. Також вивчіть підспеціалізацію на свій вибір." },
    { en = "Learn how to improve lower quality leather, refining it from |A:Professions-Icon-Quality-Tier1-Small:20:20|a to |A:Professions-Icon-Quality-Tier2-Small:20:20|a.", ua = "Навчіться покращувати шкіру нижчої якості, переробляючи її з |A:Professions-Icon-Quality-Tier1-Small:20:20|a на |A:Professions-Icon-Quality-Tier2-Small:20:20|a." },
    { en = "Learn how to improve lower quality scales, refining them from |A:Professions-Icon-Quality-Tier1-Small:20:20|a to |A:Professions-Icon-Quality-Tier2-Small:20:20|a.", ua = "Навчіться покращувати луску нижчої якості, переробляючи її з |A:Professions-Icon-Quality-Tier1-Small:20:20|a на |A:Professions-Icon-Quality-Tier2-Small:20:20|a." },
    { en = "Learn how to infuse your combat equipment crafts with reagents that increase its power.", ua = "Навчіться насичувати виготовлене бойове спорядження реагентами, що збільшують його потужність." },
    { en = "Learn how to make $@spellname392697 which is used with the Engineering crafted Zapthrottle Soul Inhaler to capture elemental souls.", ua = "Навчіться виготовляти $@spellname392697, що використовується разом із виготовленим інженерами Душовловлювачем Зептротла, щоб уловлювати душі елементалів." },
    { en = "Learn how to properly utilize Mycobloom while performing experiments to minimize the risk of a hazardous outcome, now matching that of the other Algari herbs.", ua = "Навчіться правильно застосовувати Грибоцвіт під час експериментів, щоб мінімізувати ризик небезпечного результату, який тепер такий самий, як в інших алгарійських трав." },
    { en = "Learn how to refine Draconium from Quality 2 to Quality 3.", ua = "Навчіться переробляти Драконій з 2-ї якості на 3-тю якість." },
    { en = "Learn how to refine Quality 1 Khaz'gorite to Quality 2.", ua = "Навчіться переробляти Хазгорит 1-ї якості на 2-гу якість." },
    { en = "Learn how to refine Quality 1 Serevite to Quality 2.", ua = "Навчіться переробляти Серевіт 1-ї якості на 2-гу якість." },
    { en = "Learn how to refine Quality 2 Khaz'gorite to Quality 3.", ua = "Навчіться переробляти Хазгорит 2-ї якості на 3-тю якість." },
    { en = "Learn how to refine Serevite from Quality 2 to Quality 3.", ua = "Навчіться переробляти Серевіт з 2-ї якості на 3-тю якість." },
    { en = "Learn how to sculpt $@spellname374502, a statue you can place that briefly empowers you.", ua = "Навчіться висікати $@spellname374502 — статую, яку можна встановити, щоб ненадовго підсилити себе." },
    { en = "Learn how to tap into Signal Transmitters scattered across the Dragon Isles to triangulate your Wyrmhole Generator to specific locations.", ua = "Навчіться використовувати Сигнальні передавачі, розкидані по Драконових Островах, щоб тріангуляцією наводити ваш Генератор Вирмочервоточин на конкретні місцини." },
    { en = "Learn how to transcribe other Khaz Algar Darkmoon Cards into Darkmoon Cards of Ascension.", ua = "Навчіться переписувати інші Карти Темного Місяця Каз Алґару в Карти Темного Місяця Піднесення." },
    { en = "Learn how to transcribe other Khaz Algar Darkmoon Cards into Darkmoon Cards of Evolution.", ua = "Навчіться переписувати інші Карти Темного Місяця Каз Алґару в Карти Темного Місяця Еволюції." },
    { en = "Learn how to transcribe other Khaz Algar Darkmoon Cards into Darkmoon Cards of Radiance.", ua = "Навчіться переписувати інші Карти Темного Місяця Каз Алґару в Карти Темного Місяця Сяйва." },
    { en = "Learn how to transcribe other Khaz Algar Darkmoon Cards into Darkmoon Cards of Symbiosis.", ua = "Навчіться переписувати інші Карти Темного Місяця Каз Алґару в Карти Темного Місяця Симбіозу." },
    { en = "Learn how to transcribe other Khaz Algar Darkmoon Cards into Darkmoon Cards of Vivacity.", ua = "Навчіться переписувати інші Карти Темного Місяця Каз Алґару в Карти Темного Місяця Жвавості." },
    { en = "Learn how to transmute Awakened Decay into an assortment of Rousing elements.", ua = "Навчіться перетворювати Пробуджене Гниття на набір Бентежних елементів." },
    { en = "Learn how to transmute Awakened Order into its entropic elements.", ua = "Навчіться перетворювати Пробуджений Порядок на його ентропійні елементи." },
    { en = "Learn how to transmute mundane transmutagens into Gleaming Transmutagen.", ua = "Навчіться перетворювати звичайні трансмутагени на Осяйний трансмутаген." },
    { en = "Learn how to use Finishing Reagents in the creation of Professions Equipment, allowing you to improve the crafts in various ways.", ua = "Навчіться використовувати завершальні реагенти при створенні Спорядження професій, що дозволяє покращувати вироби різними способами." },
    { en = "Learn how to use Finishing Reagents in the creation of reagents and consumables.|n|nBegin your learning in the realm of reagents and consumables, learning a sub-specialization.", ua = "Навчіться використовувати завершальні реагенти при створенні реагентів і витратних матеріалів.|n|nРозпочніть навчання у царині реагентів і витратних матеріалів, опановуючи підспеціалізацію." },
    { en = "Learn how to use Finishing Reagents to further improve your Alchemy Tools and gain +$ev1 $en1 when crafting this equipment.", ua = "Навчіться використовувати завершальні реагенти, щоб іще більше вдосконалити ваші Інструменти алхімії, і отримайте +$ev1 $en1 при виготовленні цього спорядження." },
    { en = "Learn how to use Finishing Reagents to further improve your Cooking Tools and gain +$ev1 $en1 when crafting this equipment.", ua = "Навчіться використовувати завершальні реагенти, щоб іще більше вдосконалити ваші Інструменти кулінарії, і отримайте +$ev1 $en1 при виготовленні цього спорядження." },
    { en = "Learn how to use Finishing Reagents to further improve your Inscription Tools and gain +$ev1 $en1 when crafting this equipment.", ua = "Навчіться використовувати завершальні реагенти, щоб іще більше вдосконалити ваші Інструменти накреслення, і отримайте +$ev1 $en1 при виготовленні цього спорядження." },
    { en = "Learn how to use Finishing Reagents to further improve your Off-hands and gain +$ev1 $en1 when crafting these weapons.", ua = "Навчіться використовувати завершальні реагенти, щоб іще більше вдосконалити вашу зброю другої руки, і отримайте +$ev1 $en1 при виготовленні цієї зброї." },
    { en = "Learn how to use Finishing Reagents to further improve your Staves and gain +$ev1 $en1 when crafting these weapons.", ua = "Навчіться використовувати завершальні реагенти, щоб іще більше вдосконалити ваші посохи, і отримайте +$ev1 $en1 при виготовленні цієї зброї." },
    { en = "Learn how to use Inscription crafted missives to specify the secondary stats on your crafted guns.", ua = "Навчіться використовувати створені Накресленням послання, щоб задавати вторинні характеристики на ваших виготовлених рушницях." },
    { en = "Learn how to use Missives to specify the stats on carveable equipment and learn a sub-specialization of your choosing.", ua = "Навчіться використовувати послання, щоб задавати характеристики на різьблюваному спорядженні, та опануйте підспеціалізацію на власний вибір." },
    { en = "Learn how to use Polishing Cloth finishing reagents when cutting gems.", ua = "Навчіться використовувати завершальні реагенти Полірувальна тканина при огранюванні самоцвітів." },
    { en = "Learn how to use Spare Part finishing reagents when crafting devices and tinkers.", ua = "Навчіться використовувати завершальні реагенти Запасні частини при виготовленні пристроїв і дрібних винаходів." },
    { en = "Learn how to use Spare Part finishing reagents when creating bombs of any type.", ua = "Навчіться використовувати завершальні реагенти Запасні частини при створенні бомб будь-якого типу." },
    { en = "Learn how to use Spare Part finishing reagents when creating... well, Parts.", ua = "Навчіться використовувати завершальні реагенти Запасні частини при створенні... ну, деталей." },
    { en = "Learn how to use cogwheels to calibrate engineering bracers to a specific stat.", ua = "Навчіться використовувати шестерні, щоб калібрувати інженерні наручі під конкретну характеристику." },
    { en = "Learn how to use inscription created missives to specify secondary stats on jewelry.", ua = "Навчіться використовувати створені накресленням послання, щоб задавати вторинні характеристики на прикрасах." },
    { en = "Learn how to utilize your resources as efficiently as possible.", ua = "Навчіться використовувати ваші ресурси якомога ефективніше." },
    { en = "Learn the $@spellname445318 formula.", ua = "Вивчіть формулу $@spellname445318." },
