    { en = "Learn the $@spellname445403 formula.", ua = "Вивчіть формулу $@spellname445403." },
    { en = "Learn the art of Disenchanting Uncommon Midnight equipment, gaining +$ev1 Skill per point in this Specialization when disenchanting them.", ua = "Опануйте мистецтво розчаклування Незвичайного спорядження Опівночі, отримуючи +$ev1 Уміння за кожен пункт у цій Спеціалізації при їх розчаклуванні." },
    { en = "Learn the art of shattering the magical essences of Khaz Algar, temporarily empowering your Resourcefulness, Multicraft, and Ingenuity. Additionally, your studies will grant you +$ev1 $en1 per point in this Specialization.", ua = "Опануйте мистецтво дроблення магічних есенцій Каз Алґару, тимчасово посилюючи вашу Винахідливість, Багатовиробництво та Кмітливість. Крім того, ваші студії даруватимуть вам +$ev1 $en1 за кожен пункт у цій Спеціалізації." },
    { en = "Learn the arts of Arathi crafting and utilize their techniques to make specialty armor, gaining +$ev1 $EN1 per point in this sub-specialization when crafting Arathi items.", ua = "Опануйте мистецтва аратійського виготовлення й застосовуйте їхні техніки, щоб створювати особливу броню, отримуючи +$ev1 $EN1 за кожен пункт у цій підспеціалізації при виготовленні аратійських предметів." },
    { en = "Learn the final Austere Amethyst sub-specialization.", ua = "Опануйте останню підспеціалізацію Суворого аметиста." },
    { en = "Learn the final Glamorous Gems sub-specialization.", ua = "Опануйте останню підспеціалізацію Гламурних самоцвітів." },
    { en = "Learn the final Glorious Garnet sub-specialization.", ua = "Опануйте останню підспеціалізацію Славетного гранату." },
    { en = "Learn the final Lustrous Lapis sub-specialization.", ua = "Опануйте останню підспеціалізацію Лискучого лазуриту." },
    { en = "Learn the final Powerful Peridot sub-specialization.", ua = "Опануйте останню підспеціалізацію Потужного перидоту." },
    { en = "Learn the final sub-specialization", ua = "Опануйте останню підспеціалізацію" },
    { en = "Learn the final sub-specialization and gain +$ev1 $en1 when crafting Waist, Shoulder, and Wrist pieces.", ua = "Опануйте останню підспеціалізацію та отримайте +$ev1 $en1 при виготовленні предметів на Пояс, Плечі й Зап'ястя." },
    { en = "Learn the final sub-specialization and your chance to find Weavercloth from humanoids in Khaz Algar increases by 25%.", ua = "Опануйте останню підспеціалізацію, і ваш шанс знайти Ткацьке полотно з гуманоїдів у Каз Алґарі зросте на 25%." },
    { en = "Learn the final sub-specialization of a Learned Leatherworker.", ua = "Опануйте останню підспеціалізацію Досвідченого шкіряника." },
    { en = "Learn the final sub-specialization of your choice and gain +$ev1 $en1 when crafting Hand, Feet, Head, and Back pieces.", ua = "Опануйте останню підспеціалізацію на власний вибір та отримайте +$ev1 $en1 при виготовленні предметів на Кисті, Стопи, Голову й Спину." },
    { en = "Learn the final sub-specialization of your choice and gain +$ev1 $en1, +$ev2 $en2, and +$ev3 $en3 when crafting Khaz Algar Inscription recipes.|n|nEarn an additional Knowledge point when reading an Algari Treatise on Inscription.", ua = "Опануйте останню підспеціалізацію на власний вибір та отримайте +$ev1 $en1, +$ev2 $en2 і +$ev3 $en3 при виготовленні рецептів накреслення Каз Алґару.|n|nОтримайте додатковий пункт Знання, читаючи Алгарійський трактат про накреслення." },
    { en = "Learn the final sub-specialization.", ua = "Опануйте останню підспеціалізацію." },
    { en = "Learn the final sub-specialization.|n|n+$ev1 $en1 when crafting Bundle O' Cards: Dragon Isles.", ua = "Опануйте останню підспеціалізацію.|n|n+$ev1 $en1 при виготовленні «Стос карт: Драконові Острови»." },
    { en = "Learn the final sub-specialization.|n|n+$ev1 $en1 when crafting Runic Scripture goods.", ua = "Опануйте останню підспеціалізацію.|n|n+$ev1 $en1 при виготовленні виробів Рунічного письма." },
    { en = "Learn the final sub-specialization.|n|nArmor Crafting is $ev1% faster.|n|n+$ev2 $en2 and +$ev3 $en3 when making plate armor.", ua = "Опануйте останню підспеціалізацію.|n|nВиготовлення броні на $ev1% швидше.|n|n+$ev2 $en2 і +$ev3 $en3 при створенні латної броні." },
    { en = "Learn the final sub-specialization.|n|nCutting gems is $ev1% faster.", ua = "Опануйте останню підспеціалізацію.|n|nОгранювання самоцвітів на $ev1% швидше." },
    { en = "Learn the final sub-specialization.|n|nGain +$ev1 $en1 and +$ev2 $en2 when crafting Cloth Armor.", ua = "Опануйте останню підспеціалізацію.|n|nОтримайте +$ev1 $en1 і +$ev2 $en2 при виготовленні тканинної броні." },
    { en = "Learn the final sub-specialization.|n|nGain +$ev1 $en1 and +$ev2 $en2 when crafting cloth armor.", ua = "Опануйте останню підспеціалізацію.|n|nОтримайте +$ev1 $en1 і +$ev2 $en2 при виготовленні тканинної броні." },
    { en = "Learn the final sub-specialization.|n|nGain +$ev1 $en1 when crafting various boots.", ua = "Опануйте останню підспеціалізацію.|n|nОтримайте +$ev1 $en1 при виготовленні різноманітних чобіт." },
    { en = "Learn the final sub-specialization.|n|nGain +$ev1 $en1 when crafting various bracers.", ua = "Опануйте останню підспеціалізацію.|n|nОтримайте +$ev1 $en1 при виготовленні різноманітних наручів." },
    { en = "Learn the final sub-specialization.|n|nGain +$ev1 $en1 when crafting various goggles.", ua = "Опануйте останню підспеціалізацію.|n|nОтримайте +$ev1 $en1 при виготовленні різноманітних окулярів." },
    { en = "Learn the final sub-specialization.|n|nGain +$ev2 $en2, +$ev3 $en3, and Resourcefulness refunds 5% more materials when crafting Midnight Inscription recipes.|n|nEarn an additional Knowledge point when reading an Thalassian Treatise on Inscription.", ua = "Опануйте останню підспеціалізацію.|n|nОтримайте +$ev2 $en2, +$ev3 $en3, а Винахідливість повертає на 5% більше матеріалів при виготовленні рецептів накреслення Опівночі.|n|nОтримайте додатковий пункт Знання, читаючи Таласійський трактат про накреслення." },
    { en = "Learn the final sub-specialization.|n|nLearn how to create the $@spellname374522 toy.", ua = "Опануйте останню підспеціалізацію.|n|nНавчіться створювати іграшку $@spellname374522." },
    { en = "Learn the final sub-specialization.|n|nLearn to craft and use the $@spellname391781 Finishing Reagent to improve Skill when crafting Darkmoon Sigils.", ua = "Опануйте останню підспеціалізацію.|n|nНавчіться створювати й використовувати завершальний реагент $@spellname391781, щоб покращувати Уміння при виготовленні Печаток Темного Місяця." },
    { en = "Learn the final sub-specialization.|n|nLearn to use Catalyst Finishing Reagents with recipes for phials and the Sustaining Alchemist Stone.", ua = "Опануйте останню підспеціалізацію.|n|nНавчіться використовувати завершальні реагенти Каталізатор із рецептами флаконів і Живильного каменя алхіміка." },
    { en = "Learn the final sub-specialization.|n|nLearn to use Catalyst Finishing Reagents with recipes for potions and the Alacritous Alchemist Stone.", ua = "Опануйте останню підспеціалізацію.|n|nНавчіться використовувати завершальні реагенти Каталізатор із рецептами зілль і Меткого каменя алхіміка." },
    { en = "Learn the final sub-specialization.|n|nLearn to use Chain Oil Finishing Reagents on intricate mail armor patterns.", ua = "Опануйте останню підспеціалізацію.|n|nНавчіться використовувати завершальні реагенти Ланцюгова олія на вигадливих викрійках кольчужної броні." },
    { en = "Learn the final sub-specialization.|n|nLearn to use Chain Oil Finishing Reagents on large mail armor patterns.", ua = "Опануйте останню підспеціалізацію.|n|nНавчіться використовувати завершальні реагенти Ланцюгова олія на великих викрійках кольчужної броні." },
    { en = "Learn the final sub-specialization.|n|nLearn to use Curing Agent Finishing Reagents on embroidered leather armor patterns.", ua = "Опануйте останню підспеціалізацію.|n|nНавчіться використовувати завершальні реагенти Дубильний засіб на викрійках вишитої шкіряної броні." },
    { en = "Learn the final sub-specialization.|n|nLearn to use Curing Agent Finishing Reagents on shaped leather armor patterns.", ua = "Опануйте останню підспеціалізацію.|n|nНавчіться використовувати завершальні реагенти Дубильний засіб на викрійках формованої шкіряної броні." },
    { en = "Learn the final sub-specialization.|n|nLearn to use Finishing Reagents such as Blotting Sand to further improve your Archiving crafts.", ua = "Опануйте останню підспеціалізацію.|n|nНавчіться використовувати завершальні реагенти на кшталт Промокального піску, щоб іще більше покращувати ваші архівні вироби." },
    { en = "Learn the final sub-specialization.|n|nLearn to use Quenching Fluid Finishing Reagents on large plate armor plans.", ua = "Опануйте останню підспеціалізацію.|n|nНавчіться використовувати завершальні реагенти Гартівна рідина на планах великої латної броні." },
