    { en = "Learn to add Embroidery Thread Finishing Reagents to Wrist armor.", ua = "Навчіться додавати завершальні реагенти з вишивальної нитки до броні для зап'ясть." },
    { en = "Learn to add Finishing Reagents when crafting contracts, missives, and vantus runes.", ua = "Навчіться додавати завершальні реагенти під час виготовлення контрактів, послань і рун Вантуса." },
    { en = "Learn to add Finishing Reagents when crafting runic goods.", ua = "Навчіться додавати завершальні реагенти під час виготовлення рунічних виробів." },
    { en = "Learn to add Optional Reagents to all Cloth Armor and Profession equipment.", ua = "Навчіться додавати необов'язкові реагенти до всієї тканинної броні та професійного спорядження." },
    { en = "Learn to apply Enchanted Crests when crafting Neck designs to improve their power potential.", ua = "Навчіться застосовувати зачаровані герби під час виготовлення намист, щоб покращити їхній потенціал потужності." },
    { en = "Learn to apply Enchanted Crests when crafting Ring designs to improve their power potential.", ua = "Навчіться застосовувати зачаровані герби під час виготовлення перстенів, щоб покращити їхній потенціал потужності." },
    { en = "Learn to apply missives to select secondary stats when crafting necks.", ua = "Навчіться застосовувати послання, щоб обирати вторинні характеристики під час виготовлення намист." },
    { en = "Learn to apply missives to select secondary stats when crafting rings.", ua = "Навчіться застосовувати послання, щоб обирати вторинні характеристики під час виготовлення перстенів." },
    { en = "Learn to better disenchant armor and profession equipment, gaining a small chance to acquire additional Vibrant Shards when disenchanting them.", ua = "Навчіться краще розчакловувати броню та професійне спорядження, отримуючи невеликий шанс здобути додаткові Яскраві уламки під час їхнього розчаклування." },
    { en = "Learn to better disenchant weapons, gaining a small chance to acquire additional Resonant Crystals when disenchanting them.", ua = "Навчіться краще розчакловувати зброю, отримуючи невеликий шанс здобути додаткові Резонансні кристали під час її розчаклування." },
    { en = "Learn to better handle Arathor's Spear, gaining +$ev1 $en1 to potion, flask, and phial recipes that use Arathor's Spears.", ua = "Навчіться краще поводитися зі Списом Аратора, отримуючи +$ev1 $en1 до рецептів зілль, флаконів і фіалів, що використовують Списи Аратора." },
    { en = "Learn to better handle Blessing Blossom, gaining +$ev1 $en1 to potion, flask, and phial recipes that use Blessing Blossoms.", ua = "Навчіться краще поводитися з Цвітом Благословення, отримуючи +$ev1 $en1 до рецептів зілль, флаконів і фіалів, що використовують Цвіт Благословення." },
    { en = "Learn to better handle Luredrop, gaining +$ev1 $en1 to potion, flask, and phial recipes that use this herb.", ua = "Навчіться краще поводитися з Принадокраплею, отримуючи +$ev1 $en1 до рецептів зілль, флаконів і фіалів, що використовують цю траву." },
    { en = "Learn to better handle Mycobloom, the most common and volatile of Algari herbs, gaining +$ev1 $en1 to potion, flask, and phial recipes that use this herb.", ua = "Навчіться краще поводитися з Грибоцвітом — найпоширенішою та найнестабільнішою з алгарських трав, — отримуючи +$ev1 $en1 до рецептів зілль, флаконів і фіалів, що використовують цю траву." },
    { en = "Learn to better handle Orbinid, gaining +$ev1 $en1 to potion, flask, and phial recipes that use Orbinids.", ua = "Навчіться краще поводитися з Орбінідом, отримуючи +$ev1 $en1 до рецептів зілль, флаконів і фіалів, що використовують Орбініди." },
    { en = "Learn to better recover magical reagents from items, gaining +$ev1% chance to acquire additional reagents when disenchanting items per point in this Specialization.", ua = "Навчіться краще відновлювати магічні реагенти з предметів, отримуючи +$ev1% шансу здобути додаткові реагенти під час розчаклування предметів за кожне очко в цій спеціалізації." },
    { en = "Learn to bind powerful Scale Sigils that customize how your Deck shuffles cards.", ua = "Навчіться зв'язувати могутні Сигіли Луски, що налаштовують те, як ваша Колода тасує карти." },
    { en = "Learn to bind the earth within your enchantments, increasing your skill when crafting enchantments that utilize Rousing or Awakened Earth. Gain +$ev1 $en1 per point in this Specialization.", ua = "Навчіться зв'язувати землю у своїх чарах, підвищуючи навички під час виготовлення чарів, що використовують Бурхливу або Пробуджену Землю. Отримуйте +$ev1 $en1 за кожне очко в цій спеціалізації." },
    { en = "Learn to channel air currents within your enchantments, increasing your skill when crafting enchantments that utilize Rousing or Awakened Air. Gain +$ev1 $en1 per point in this Specialization.", ua = "Навчіться скеровувати повітряні потоки у своїх чарах, підвищуючи навички під час виготовлення чарів, що використовують Бурхливе або Пробуджене Повітря. Отримуйте +$ev1 $en1 за кожне очко в цій спеціалізації." },
    { en = "Learn to collect cloth more effectively, increasing the amount of cloth found from Humanoids in the Dragon Isles by 1% per point in this Specialization.", ua = "Навчіться ефективніше збирати тканину, збільшуючи кількість тканини, яку знаходите на гуманоїдах Драконових Островів, на 1% за кожне очко в цій спеціалізації." },
    { en = "Learn to control fire within your enchantments, increasing your skill when crafting enchantments that utilize Rousing or Awakened Fire. Gain +$ev1 $en1 per point in this Specialization.", ua = "Навчіться керувати вогнем у своїх чарах, підвищуючи навички під час виготовлення чарів, що використовують Бурхливий або Пробуджений Вогонь. Отримуйте +$ev1 $en1 за кожне очко в цій спеціалізації." },
