    { en = "Learn to create $@spellname374546 which will allow you to periodically convert Queen's Ruby into Alexstraszite.", ua = "Навчає створювати $@spellname374546, що дає змогу періодично перетворювати рубіни королеви на алекстразит." },
    { en = "Learn to create $@spellname374547 which will allow you to periodically convert Vibrant Emeralds into Ysemeralds.", ua = "Навчає створювати $@spellname374547, що дає змогу періодично перетворювати яскраві смарагди на ісмарагд." },
    { en = "Learn to create $@spellname374548 which will allow you to periodically convert Mystic Sapphires into Malygite.", ua = "Навчає створювати $@spellname374548, що дає змогу періодично перетворювати містичні сапфіри на малігіт." },
    { en = "Learn to create $@spellname374549 which will allow you to periodically convert Sundered Onyx into Neltharite.", ua = "Навчає створювати $@spellname374549, що дає змогу періодично перетворювати розколотий онікс на нелтарит." },
    { en = "Learn to create only the finest of profession equipment for you and your fellow crafters, gaining +$ev1 $en1 per point in this sub-specialization when crafting Profession Equipment.", ua = "Навчає створювати лише найкраще професійне спорядження для тебе та твоїх колег-майстрів, надаючи +$ev1 $en1 за кожен бал у цій підспеціалізації під час виготовлення професійного спорядження." },
    { en = "Learn to create potent Mana Oils used to temporarily empower the weapons of the heroes of Azeroth, gaining +$ev1 $en1 per point in this Specialization.", ua = "Навчає створювати потужні манаолії, якими тимчасово підсилюють зброю героїв Азероту, надаючи +$ev1 $en1 за кожен бал у цій спеціалізації." },
    { en = "Learn to create the finest Profession Equipment in Quel'Thalas for you and your fellow crafters, gaining +$ev1 $en1 per point in this Specialization when crafting them.", ua = "Навчає створювати найкраще професійне спорядження в Кель'Таласі для тебе та твоїх колег-майстрів, надаючи +$ev1 $en1 за кожен бал у цій спеціалізації під час їх виготовлення." },
    { en = "Learn to create the most potent of accessories to compliment the wardrobe of any adventurer or crafter.", ua = "Навчає створювати найпотужніші аксесуари, що доповнять гардероб будь-якого шукача пригод чи майстра." },
    { en = "Learn to entertain and mystify with illusory magic and enchantments, increasing your skill at crafting illusory goods. Gain +$ev1 $en1 per point in this Specialization.", ua = "Навчає розважати й дивувати ілюзорною магією та чарами, підвищуючи твою майстерність у виготовленні ілюзорних виробів. Надає +$ev1 $en1 за кожен бал у цій спеціалізації." },
    { en = "Learn to extract Awakened Air from Darkmoon Cards.", ua = "Навчає видобувати пробуджене повітря з карт Темного Місяця." },
    { en = "Learn to extract Awakened Earth from Darkmoon Cards.", ua = "Навчає видобувати пробуджену землю з карт Темного Місяця." },
    { en = "Learn to extract Awakened Fire from Darkmoon Cards.", ua = "Навчає видобувати пробуджений вогонь з карт Темного Місяця." },
    { en = "Learn to extract Awakened Frost from Darkmoon Cards.", ua = "Навчає видобувати пробуджений мороз з карт Темного Місяця." },
    { en = "Learn to extract the elements within primal elementals, further studying their magic and acquiring additional reagents. Gain +$ev1% chance to acquire additional Rousing elements per point in this specialization.", ua = "Навчає видобувати стихії з первісних елементалів, поглиблюючи вивчення їхньої магії та здобуваючи додаткові реагенти. Надає +$ev1% шансу здобути додаткові буремні стихії за кожен бал у цій спеціалізації." },
    { en = "Learn to fashion a $@spellname1225939.", ua = "Навчає виготовляти $@spellname1225939." },
    { en = "Learn to fashion a $@spellname1225940.", ua = "Навчає виготовляти $@spellname1225940." },
    { en = "Learn to fashion a $@spellname1225941.", ua = "Навчає виготовляти $@spellname1225941." },
    { en = "Learn to fashion a $@spellname1225942.", ua = "Навчає виготовляти $@spellname1225942." },
    { en = "Learn to find scraps of Dawnweave from humanoids around Khaz Algar and how to craft $@spellname446928s.", ua = "Навчає знаходити клапті світанкоплетива на гуманоїдах довкола Каз Алґару та виготовляти $@spellname446928." },
    { en = "Learn to find scraps of Duskweave from humanoids around Khaz Algar and how to craft $@spellname446927s.", ua = "Навчає знаходити клапті сутінкоплетива на гуманоїдах довкола Каз Алґару та виготовляти $@spellname446927." },
    { en = "Learn to gather frost within your enchantments, increasing your skill when crafting enchantments that utilize Rousing or Awakened Frost. Gain +$ev1 $en1 per point in this Specialization.", ua = "Навчає збирати мороз у твоїх чарах, підвищуючи майстерність у виготовленні чарів, що використовують буремний або пробуджений мороз. Надає +$ev1 $en1 за кожен бал у цій спеціалізації." },
    { en = "Learn to guarantee a Rousing Element from certain types of wildercloth during the unraveling process.", ua = "Навчає гарантовано отримувати буремну стихію з певних видів дикотканини під час розпускання." },
    { en = "Learn to harness the primal elements of the Dragon Isles, increasing your skill when crafting enchantments that utilize Rousing or Awakened elements. Gain +$ev1 $en1 per point in this Specialization.", ua = "Навчає опановувати первісні стихії Драконових Островів, підвищуючи майстерність у виготовленні чарів, що використовують буремні або пробуджені стихії. Надає +$ev1 $en1 за кожен бал у цій спеціалізації." },
    { en = "Learn to harness the radiant light of Beledar, gaining +$ev1 $en1 per point in this Specialization when crafting Arathi Weapon enchantments.", ua = "Навчає опановувати сяйливе світло Беледара, надаючи +$ev1 $en1 за кожен бал у цій спеціалізації під час виготовлення аратійських чарів для зброї." },
    { en = "Learn to improve essential combat abilities, increasing your skill when crafting enchantments for chestpieces and rings. Gain +$ev1 $en1 per point in this Specialization.", ua = "Навчає покращувати ключові бойові здібності, підвищуючи майстерність у виготовленні чарів для нагрудників і перснів. Надає +$ev1 $en1 за кожен бал у цій спеціалізації." },
    { en = "Learn to improve your elemental extraction, gaining a small chance to acquire additional Rousing elements.", ua = "Навчає покращувати видобування стихій, надаючи невеликий шанс здобути додаткові буремні стихії." },
    { en = "Learn to increase your disenchanting potency, gaining a small chance to acquire additional reagents when disenchanting items.", ua = "Навчає підвищувати потужність розчаклування, надаючи невеликий шанс здобути додаткові реагенти під час розчаклування предметів." },
    { en = "Learn to increase your magical perception, gaining a small chance to locate Mystic items that can be disenchanted into reagents.", ua = "Навчає загострювати магічне чуття, надаючи невеликий шанс знаходити містичні предмети, які можна розчаклувати на реагенти." },
    { en = "Learn to infuse toxic reagents with your potions.", ua = "Навчає просочувати твої зілля токсичними реагентами." },
    { en = "Learn to infuse your standard lures with Crystalline Powder.", ua = "Навчає просочувати твої звичайні приманки кристалічним порошком." },
    { en = "Learn to infuse your standard lures with Viridescent Spores.", ua = "Навчає просочувати твої звичайні приманки зеленкуватими спорами." },
    { en = "Learn to infuse your standard lures with Writhing Samples.", ua = "Навчіться просочувати звичайні наживки Звивистими Зразками." },
    { en = "Learn to inscribe Darkmoon Card: Blood.|n|nLearn a sub-specialization of your choice.", ua = "Навчіться накреслювати Карту Темного Місяця: Кров.|n|nВивчіть підспеціалізацію на ваш вибір." },
    { en = "Learn to inscribe Darkmoon Card: Hunt.|n|nLearn a sub-specialization of your choice.", ua = "Навчіться накреслювати Карту Темного Місяця: Полювання.|n|nВивчіть підспеціалізацію на ваш вибір." },
    { en = "Learn to inscribe Darkmoon Card: Rot.|n|nLearn a sub-specialization of your choice.", ua = "Навчіться накреслювати Карту Темного Місяця: Гниль.|n|nВивчіть підспеціалізацію на ваш вибір." },
    { en = "Learn to inscribe Darkmoon Card: Void.|n|nLearn a sub-specialization of your choice.", ua = "Навчіться накреслювати Карту Темного Місяця: Порожнеча.|n|nВивчіть підспеціалізацію на ваш вибір." },
    { en = "Learn to invoke titanic power within your enchantments, increasing your skill when crafting enchantments that utilize Rousing or Awakened Order. Gain +$ev1 $en1 per point in this Specialization.", ua = "Навчіться викликати титанічну силу у своїх чарах, підвищуючи навички при виготовленні чарів, які використовують Буремний або Пробуджений Порядок. Отримуйте +$ev1 $en1 за кожен пункт цієї Спеціалізації." },
    { en = "Learn to make every bit of material count, gaining +$ev1 $en1 when skinning Renowned Beasts per point in this Specialization.", ua = "Навчіться використовувати кожен клаптик матеріалу, отримуючи +$ev1 $en1 за кожен пункт цієї Спеціалізації під час білування Прославлених звірів." },
    { en = "Learn to occasionaly extract Rousing Elements from certain types of wildercloth during the unraveling process.", ua = "Навчіться час від часу видобувати Буремні Елементи з певних видів дикотканини під час розпускання." },
    { en = "Learn to perform $@spellname391302, destroying an Enchanting reagent to acquire 3 of lesser rarity.", ua = "Навчіться застосовувати $@spellname391302, знищуючи реагент Накладання чарів, щоб отримати 3 меншої рідкісності." },
    { en = "Learn to perform $@spellname391304, destroying an Awakened element to briefly grant you combat stats while outdoors in the Dragon Isles.", ua = "Навчіться застосовувати $@spellname391304, знищуючи Пробуджений елемент, щоб ненадовго надати вам бойові характеристики на відкритій місцевості Драконових Островів." },
    { en = "Learn to process herbs into $@spellname1221179.", ua = "Навчіться переробляти трави на $@spellname1221179." },
    { en = "Learn to process herbs into $@spellname1221180.", ua = "Навчіться переробляти трави на $@spellname1221180." },
