    { en = "Learn to rarely collect Wildercloth Bolts off humanoids in the Dragon Isles.", ua = "Навчіться зрідка збирати Сувої дикотканини з гуманоїдів на Драконових Островах." },
    { en = "Learn to recognize rare materials, gaining +$ev1 $en1 while skinning per point in this Specialization.", ua = "Навчіться розпізнавати рідкісні матеріали, отримуючи +$ev1 $en1 за кожен пункт цієї Спеціалізації під час білування." },
    { en = "Learn to refine Quality 1 Aqirite into Quality 2.", ua = "Навчіться переробляти Акірит якості 1 на якість 2." },
    { en = "Learn to refine Quality 1 Bismuth into Quality 2.", ua = "Навчіться переробляти Бісмут якості 1 на якість 2." },
    { en = "Learn to refine Quality 1 Ironclaw Ore into Quality 2.", ua = "Навчіться переробляти Залізокігтеву руду якості 1 на якість 2." },
    { en = "Learn to refine Quality 2 Aqirite into Quality 3.", ua = "Навчіться переробляти Акірит якості 2 на якість 3." },
    { en = "Learn to refine Quality 2 Bismuth into Quality 3.", ua = "Навчіться переробляти Бісмут якості 2 на якість 3." },
    { en = "Learn to refine Quality 2 Ironclaw Ore into Quality 3.", ua = "Навчіться переробляти Залізокігтеву руду якості 2 на якість 3." },
    { en = "Learn to shatter magical essences native to Midnight areas, temporarily empowering your Resourcefulness, Multicraft, and Ingenuity. Additionally, you will gain +$ev1 $en1 per point in this Specialization.", ua = "Навчіться розбивати магічні есенції, притаманні місцевостям Опівночі, тимчасово підсилюючи вашу Винахідливість, Багатовиробництво та Кмітливість. Крім того, ви отримаєте +$ev1 $en1 за кожен пункт цієї Спеціалізації." },
    { en = "Learn to sometimes collect particularly damaged forms of Wildercloth for use in Unraveling.", ua = "Навчіться інколи збирати особливо пошкоджені форми дикотканини для використання в розпусканні." },
    { en = "Learn to spare more and more thread gaining +$ev1 $en1 per point in this specialization.", ua = "Навчіться заощаджувати дедалі більше ниток, отримуючи +$ev1 $en1 за кожен пункт цієї спеціалізації." },
    { en = "Learn to transcribe Darkmoon Card: Blood.|n|nGain +$ev1 $en1 when crafting Blood Sigils and Dominions.", ua = "Навчіться переписувати Карту Темного Місяця: Кров.|n|nОтримуйте +$ev1 $en1 під час виготовлення Сигілів та Володінь Крові." },
    { en = "Learn to transcribe Darkmoon Card: Hunt.|n|nGain +$ev1 $en1 when crafting Hunt Sigils and Dominions.", ua = "Навчіться переписувати Карту Темного Місяця: Полювання.|n|nОтримуйте +$ev1 $en1 під час виготовлення Сигілів та Володінь Полювання." },
    { en = "Learn to transcribe Darkmoon Card: Rot.|n|nGain +$ev1 $en1 when crafting Rot Sigils and Dominions.", ua = "Навчіться переписувати Карту Темного Місяця: Гниль.|n|nОтримуйте +$ev1 $en1 під час виготовлення Сигілів та Володінь Гнилі." },
