    { en = "Learn to use the $@spellname391781 Finishing Reagent to improve Skill when crafting the Rime Deck Box.", ua = "Навчіться використовувати завершальний реагент $@spellname391781, щоб покращувати майстерність під час виготовлення Скриньки колоди «Паморозь»." },
    { en = "Learn to use the $@spellname391781 Finishing Reagent to improve Skill when crafting the Watcher Deck Box.", ua = "Навчіться використовувати завершальний реагент $@spellname391781, щоб покращувати майстерність під час виготовлення Скриньки колоди «Спостерігач»." },
    { en = "Learn to use the materials at hand in Khaz Algar to infuse your baits, causing the lured creatures to have additional reagents when you gather from them. Additionally, gain +$ev1 $en1 while skinning in Khaz Algar per point in the Specialization.", ua = "Навчіться використовувати підручні матеріали Каз Алґару, щоб просочувати ними свої принади, завдяки чому приваблені істоти даватимуть додаткові реагенти, коли ви з них збираєте здобич. Крім того, отримуйте +$ev1 $en1 під час білування в Каз Алґарі за кожен бал у цій спеціалізації." },
    { en = "Learn to use various Optional Reagents to  infuse Staves and Off-hand weapons with power and learn a sub-specialization of your choice.", ua = "Навчіться використовувати різні необов'язкові реагенти, щоб наповнювати силою посохи та зброю другої руки, і вивчіть підспеціалізацію на свій вибір." },
    { en = "Learn to use your tools on plant creatures, gaining the ability to get useful herbs and items from them.", ua = "Навчіться застосовувати свої інструменти на рослинних істотах, отримуючи здатність здобувати з них корисні трави та предмети." },
    { en = "Learn what causes plants to grow and thrive in Khaz Algar, increasing your skills related to lush herbs while learning how to make potent mulches. Gain +$ev1 $en1 per point in this specialization while gathering lush herbs.", ua = "Дізнайтеся, що змушує рослини рости й буяти в Каз Алґарі, підвищуючи ваші навички роботи з буйними травами та навчаючись готувати потужні мульчі. Отримуйте +$ev1 $en1 за кожен бал у цій спеціалізації під час збирання буйних трав." },
    { en = "Learn what causes plants to grow and thrive in the Midnight region, increasing your skills related to lush herbs while learning how to make potent mulches. Gain +$ev1 $en1 per point in this specialization while gathering lush herbs.", ua = "Дізнайтеся, що змушує рослини рости й буяти в регіоні Опівночі, підвищуючи ваші навички роботи з буйними травами та навчаючись готувати потужні мульчі. Отримуйте +$ev1 $en1 за кожен бал у цій спеціалізації під час збирання буйних трав." },
    { en = "Leatherworking crafting is $ev1% faster.|n|n+$ev2 $en2 when crafting Leatherworking patterns.", ua = "Виготовлення у Шкіряній справі $ev1% швидше.|n|n+$ev2 $en2 під час виготовлення викрійок Шкіряної справи." },
    { en = "Leatherworking crafting is +$ev1% faster.|n|n+$ev2 $en2 and +$ev3 $en3 when crafting Leatherworking Patterns.|n|nLearn the final sub-specialization.", ua = "Виготовлення у Шкіряній справі +$ev1% швидше.|n|n+$ev2 $en2 та +$ev3 $en3 під час виготовлення викрійок Шкіряної справи.|n|nВивчіть останню підспеціалізацію." },
    { en = "Less lashers will appear when gathering Wild herbs, but the amount of reagents they grant is increased.", ua = "Під час збирання Диких трав з'являтиметься менше батожників, але кількість реагентів, які вони дають, збільшено." },
    { en = "Level up your lockets, gaining +$ev1 $en1 when crafting Necklaces per point in this Specialization.", ua = "Прокачуйте свої медальйони, отримуючи +$ev1 $en1 під час виготовлення намист за кожен бал у цій спеціалізації." },
    { en = "Leverage the diametric power of Light and Void to brew even more exhilirating potions.", ua = "Використайте діаметрально протилежну силу Світла та Порожнечі, щоб варити ще п'янкіші зілля." },
    { en = "Leverage the tools and techniques of Khaz Algar to craft plate armor.", ua = "Використайте інструменти та техніки Каз Алґару, щоб виготовляти латний обладунок." },
    { en = "Lighten your workload. Increase efficiency while crafting Light potions by gaining +$ev1 $en1 per point in this specialization.", ua = "Полегшіть своє навантаження. Підвищуйте ефективність виготовлення зілля Світла, отримуючи +$ev1 $en1 за кожен бал у цій спеціалізації." },
    { en = "Lower the distance in which the elite patrols will detect you by x yds.", ua = "Зменшіть на x ярдів дистанцію, на якій вас помічають елітні патрулі." },
    { en = "Lunar Eclipse is 3 sec longer and Solar Eclipse is 3 sec shorter.", ua = "Місячне затемнення триває на 3 сек. довше, а Сонячне затемнення — на 3 сек. коротше." },
    { en = "Magical Reinforcement crafts are $ev1% faster.|n|nLearn to craft and use the $@spellname391202 Finishing Reagent to improve Skill when crafting Magical Reinforcement enchantments.", ua = "Виготовлення Магічного підкріплення $ev1% швидше.|n|nНавчіться виготовляти та використовувати завершальний реагент $@spellname391202, щоб покращувати майстерність під час створення чарів Магічного підкріплення." },
    { en = "Make crafting belts a cinch. Gaining +$ev1 $en1 when crafting cloth belts.", ua = "Зробіть виготовлення поясів за іграшку. Отримуйте +$ev1 $en1 під час виготовлення тканинних поясів." },
    { en = "Master Inscription's fundamental reagents.", ua = "Опануйте основні реагенти Накреслення." },
    { en = "Master Inscription's fundemental reagents.", ua = "Опануйте основні реагенти Накреслення." },
    { en = "Master an Engineer's adaptable augmentations.", ua = "Опануйте пристосовні вдосконалення інженера." },
    { en = "Master crafting Midnight Alchemy reagents. Gain +$ev1 $en1 to all Midnight Alchemy reagents, transmutations, and Alchemist Stones per point in this specialization.", ua = "Опануйте виготовлення алхімічних реагентів Опівночі. Отримуйте +$ev1 $en1 до всіх алхімічних реагентів, трансмутацій та Каменів алхіміка Опівночі за кожен бал у цій спеціалізації." },
    { en = "Master synthesizing and gain +$ev1 $en1 to Midnight Transmutations per point in this specialization.", ua = "Опануйте синтез і отримуйте +$ev1 $en1 до трансмутацій Опівночі за кожен бал у цій спеціалізації." },
    { en = "Master techniques to reduce reagent waste, gaining +$ev1 $en1 per point in this Specialization.", ua = "Опануйте техніки, що зменшують марнування реагентів, отримуючи +$ev1 $en1 за кожен бал у цій спеціалізації." },
    { en = "Master the ability to utilize the shattered magical essences to supplement your crafting reagents, granting you +$ev1 $en1 per point in this Specialization.", ua = "Опануйте вміння використовувати розтрощені магічні есенції, щоб доповнювати свої реагенти для виготовлення, отримуючи +$ev1 $en1 за кожен бал у цій спеціалізації." },
    { en = "Master the ability to utilize the shattered magical essences to supplement your crafting reagents, increasing your $en1 by +$ev1 per point in this Specialization.", ua = "Опануйте вміння використовувати розтрощені магічні есенції, щоб доповнювати свої реагенти для виготовлення, підвищуючи вашу характеристику $en1 на +$ev1 за кожен бал у цій спеціалізації." },
    { en = "Master the ancient art of Thalassian enchantments, gaining +$ev1 $en1 per point in this Specialization.", ua = "Опануйте прадавнє мистецтво таласійських чарів, отримуючи +$ev1 $en1 за кожен бал у цій спеціалізації." },
    { en = "Master the arcane power trapped within these plants, increasing your mastery of the latent energy and learning how to propagate it. Gain +$ev1 $en1 per point in this specialization while gathering them.", ua = "Опануйте арканну силу, ув'язнену в цих рослинах, поглиблюючи своє володіння прихованою енергією та навчаючись її розмножувати. Отримуйте +$ev1 $en1 за кожен бал у цій спеціалізації під час їх збирання." },
    { en = "Master the art of crafting axes and polearms.|n|nGain +$ev1 $en1 when crafting axes and polearms.", ua = "Опануйте мистецтво виготовлення сокир і древкової зброї.|n|nОтримуйте +$ev1 $en1 при виготовленні сокир і древкової зброї." },
    { en = "Master the art of crafting chest armor.|n|nGain +$ev1 $en1 to crafting chest armor for each Knowledge point in this specialization.", ua = "Опануйте мистецтво виготовлення нагрудної броні.|n|nОтримуйте +$ev1 $en1 до виготовлення нагрудної броні за кожен пункт Знань у цій спеціалізації." },
    { en = "Master the art of crafting foot armor.|n|nGain +$ev1 $en1 when crafting foot armor.", ua = "Опануйте мистецтво виготовлення броні для стоп.|n|nОтримуйте +$ev1 $en1 при виготовленні броні для стоп." },
    { en = "Master the art of crafting hand armor.|n|nGain +$ev1 $en1 when crafting hand armor.", ua = "Опануйте мистецтво виготовлення броні для кистей.|n|nОтримуйте +$ev1 $en1 при виготовленні броні для кистей." },
    { en = "Master the art of crafting helms.|n|nGain +$ev1 $en1 when crafting helms.", ua = "Опануйте мистецтво виготовлення шоломів.|n|nОтримуйте +$ev1 $en1 при виготовленні шоломів." },
    { en = "Master the art of crafting leg armor.|n|nGain +$ev1 $en1 to crafting leg armor for each Knowledge point in this specialization.", ua = "Опануйте мистецтво виготовлення броні для ніг.|n|nОтримуйте +$ev1 $en1 до виготовлення броні для ніг за кожен пункт Знань у цій спеціалізації." },
    { en = "Master the art of crafting long blades.|n|nGain +$ev1 $en1 when crafting long blades.", ua = "Опануйте мистецтво виготовлення довгих клинків.|n|nОтримуйте +$ev1 $en1 при виготовленні довгих клинків." },
    { en = "Master the art of crafting maces.|n|nGain +$ev1 $en1 when crafting maces.", ua = "Опануйте мистецтво виготовлення булав.|n|nОтримуйте +$ev1 $en1 при виготовленні булав." },
    { en = "Master the art of crafting mail armor using chitin and the techniques learned on Khaz Algar, gaining +$ev1 $en1 per point in this Specialization.", ua = "Опануйте мистецтво виготовлення кольчужної броні з хітину й технік, опанованих у Каз Алґарі, отримуючи +$ev1 $en1 за кожен пункт у цій Спеціалізації." },
    { en = "Master the art of crafting shields.|n|nGain +$ev1 $en1 to crafting shields for each Knowledge point in this specialization.", ua = "Опануйте мистецтво виготовлення щитів.|n|nОтримуйте +$ev1 $en1 до виготовлення щитів за кожен пункт Знань у цій спеціалізації." },
    { en = "Master the art of crafting short blades.|n|nGain +$ev1 $en1 when crafting short blades.", ua = "Опануйте мистецтво виготовлення коротких клинків.|n|nОтримуйте +$ev1 $en1 при виготовленні коротких клинків." },
    { en = "Master the art of crafting shoulder armor.|n|nGain +$ev1 $en1 when crafting shoulder armor.", ua = "Опануйте мистецтво виготовлення броні для плечей.|n|nОтримуйте +$ev1 $en1 при виготовленні броні для плечей." },
    { en = "Master the art of crafting waist armor.|n|nGain +$ev1 $en1 when crafting waist armor.", ua = "Опануйте мистецтво виготовлення броні для пояса.|n|nОтримуйте +$ev1 $en1 при виготовленні броні для пояса." },
    { en = "Master the art of crafting whetstones and weightstones, consumable items that enhance your weapons. |n|nGain +$ev1 $en1 when crafting whetstones and weightstones for each point spent in this specialization.", ua = "Опануйте мистецтво виготовлення точильних та обважнювальних каменів — витратних предметів, що покращують вашу зброю. |n|nОтримуйте +$ev1 $en1 при виготовленні точильних та обважнювальних каменів за кожен вкладений пункт у цій спеціалізації." },
    { en = "Master the art of crafting wrist armor.|n|nGain +$ev1 $en1 when crafting wrist armor.", ua = "Опануйте мистецтво виготовлення броні для зап'ясть.|n|nОтримуйте +$ev1 $en1 при виготовленні броні для зап'ясть." },
    { en = "Master the art of creating Azureweave Bolts, gaining +$ev1 $en1 per point in this Specialization.", ua = "Опануйте мистецтво створення сувоїв Лазурового плетива, отримуючи +$ev1 $en1 за кожен пункт у цій Спеціалізації." },
    { en = "Master the art of creating Chronocloth Bolts, gaining +$ev1 $en1 per point in this Specialization.", ua = "Опануйте мистецтво створення сувоїв Хронотканини, отримуючи +$ev1 $en1 за кожен пункт у цій Спеціалізації." },
    { en = "Master the art of creating Dawnweave Bolts, gaining +$ev1 $en1 per point in this Specialization.", ua = "Опануйте мистецтво створення сувоїв Світанкового плетива, отримуючи +$ev1 $en1 за кожен пункт у цій Спеціалізації." },
    { en = "Master the art of creating Duskweave Bolts, gaining +$ev1 $en1 per point in this Specialization.", ua = "Опануйте мистецтво створення сувоїв Сутінкового плетива, отримуючи +$ev1 $en1 за кожен пункт у цій Спеціалізації." },
    { en = "Master the art of creating better enchanting rods, providing better quality tools for enchanters the world over with +$ev1 $en1 per point in this Specialization.", ua = "Опануйте мистецтво створення кращих жезлів для накладання чарів, забезпечуючи зачаровувачів по всьому світу якіснішими інструментами з +$ev1 $en1 за кожен пункт у цій Спеціалізації." },
    { en = "Master the art of ever-hungering curses, gaining +$ev1 $en1 per point in this Specialization when crafting Cursed Nerubian Ring enchantments.", ua = "Опануйте мистецтво вічно голодних проклять, отримуючи +$ev1 $en1 за кожен пункт у цій Спеціалізації при створенні чарів Проклятого Нерубіанського Персня." },
    { en = "Master the art of gathering Mana Lily, gaining +$ev1 $en1 per point in this sub-specialization while gathering it.", ua = "Опануйте мистецтво збору Манової лілії, отримуючи +$ev1 $en1 за кожен пункт у цій підспеціалізації під час її збору." },
    { en = "Master the art of magical matrices and formulas that permanently improve equipment.", ua = "Опануйте мистецтво магічних матриць і формул, що назавжди покращують спорядження." },
    { en = "Master the art of magical matrices that help permanently improve pieces of equipment, gaining +$ev1 $en1 per point in this Specialization.", ua = "Опануйте мистецтво магічних матриць, що допомагають назавжди покращувати частини спорядження, отримуючи +$ev1 $en1 за кожен пункт у цій Спеціалізації." },
    { en = "Master the art of making armor kits, reagents, and other consumable goods, gaining +$ev1 $en1 per point in this sub-specialization when crafting Armor Kits and Reagents.", ua = "Опануйте мистецтво виготовлення наборів для броні, реагентів та інших витратних товарів, отримуючи +$ev1 $en1 за кожен пункт у цій підспеціалізації при виготовленні Наборів для броні та Реагентів." },
    { en = "Master the art of milling and crafting reagents like inks and ciphers.", ua = "Опануйте мистецтво помелу та виготовлення реагентів, як-от чорнил і шифрів." },
    { en = "Master the art of mining in unexpected circumstances.", ua = "Опануйте мистецтво видобутку за несподіваних обставин." },
    { en = "Master the art of producing phials more efficiently, gaining +$ev1 $en1 per point in this specialization.", ua = "Опануйте мистецтво ефективнішого виготовлення фіалів, отримуючи +$ev1 $en1 за кожен пункт у цій спеціалізації." },
    { en = "Master the art of producing potions more efficiently, gaining +$ev1 $en1 per point in this specialization.", ua = "Опануйте мистецтво ефективнішого виготовлення зілля, отримуючи +$ev1 $en1 за кожен пункт у цій спеціалізації." },
    { en = "Master the art of recycling crafted reagents from other Midnight Professions into useful parts for Midnight Engineering!", ua = "Опануйте мистецтво переробки виготовлених реагентів з інших професій Опівночі на корисні деталі для Інженерії Опівночі!" },
    { en = "Master the art of sewing armor from your head to your toes. Gain +$ev1 $en1 when crafting cloth Boots, Gloves, and Hats.", ua = "Опануйте мистецтво шиття броні від голови до п'ят. Отримуйте +$ev1 $en1 при виготовленні тканинних Чобіт, Рукавиць та Капелюхів." },
    { en = "Master the art of sewing essential outfit pieces. Gain +$ev1 $en1 when crafting cloth Robes, Trousers, and Cloaks.", ua = "Опануйте мистецтво шиття основних предметів вбрання. Отримуйте +$ev1 $en1 при виготовленні тканинних Роб, Штанів та Плащів." },
    { en = "Master the art of sewing the finest of accessories. Gain +$ev1 $en1 when crafting cloth Belts, Bracers, and Shoulders.", ua = "Опануйте мистецтво шиття найвишуканіших аксесуарів. Отримуйте +$ev1 $en1 при виготовленні тканинних Поясів, Наручів та Наплічників." },
    { en = "Master the art of sifting through ore to find precious gems, gaining +$ev1 $en1 while Prospecting per point in this Specialization.", ua = "Опануйте мистецтво просіювання руди в пошуках коштовних самоцвітів, отримуючи +$ev1 $en1 під час Пошуку самоцвітів за кожен пункт у цій Спеціалізації." },
    { en = "Master the art of smithing profession equipment and consumable items.", ua = "Опануйте мистецтво кування професійного спорядження та витратних предметів." },
    { en = "Master the art of transmuting materials into other substances.", ua = "Опануйте мистецтво трансмутації матеріалів в інші речовини." },
    { en = "Master the arts of Advanced Armor, learning the final sub-specialization.|n|nLearn to use Finishing Reagents on Advanced Armor mail armor patterns.|n|n+$ev1 $en1 when crafting Advanced Armor mail armor pieces.", ua = "Опануйте мистецтво Вдосконаленої Броні, вивчивши останню підспеціалізацію.|n|nНавчіться застосовувати завершальні реагенти на викрійках кольчужної броні Вдосконаленої Броні.|n|n+$ev1 $en1 при виготовленні частин кольчужної броні Вдосконаленої Броні." },
    { en = "Master the arts of being a Material Manufacturer, learning the final sub-specialization.|n|n+$ev1 $en1 while crafting Reagents.|n|nConsume $ev2% less Concentration when Concentrating on crafting Reagents.", ua = "Опануйте мистецтво Виробника Матеріалів, вивчивши останню підспеціалізацію.|n|n+$ev1 $en1 при виготовленні Реагентів.|n|nВитрачайте на $ev2% менше Зосередження, зосереджуючись на виготовленні Реагентів." },
    { en = "Master the arts of creating reagents and consumables, gaining +$ev1 $en1 per point in this Specialization when crafting them.", ua = "Опануйте мистецтво створення реагентів і витратних предметів, отримуючи +$ev1 $en1 за кожен пункт у цій Спеціалізації при їх виготовленні." },
    { en = "Master the arts of flask and phial-crafting using techniques found in Khaz Algar.", ua = "Опануйте мистецтво виготовлення фляг і фіалів за техніками, знайденими в Каз Алґарі." },
    { en = "Master the basics of Midnight Alchemy. Gain +$ev1 $en1 to all Midnight Alchemy crafts per point in this specialization.", ua = "Опануйте основи Алхімії Опівночі. Отримуйте +$ev1 $en1 до всіх виробів Алхімії Опівночі за кожен пункт у цій спеціалізації." },
    { en = "Master the basics of being a Proficient Processor, learning the final sub-specialization.|n|nCrafting and Salvages are $ev1% faster. |n|nConsume $ev2% less Concentration when Concentrating on Reagents and Salvages.", ua = "Опануйте основи Вмілого Переробника, вивчивши останню підспеціалізацію.|n|nВиготовлення та переробка на $ev1% швидші. |n|nВитрачайте на $ev2% менше Зосередження, зосереджуючись на Реагентах і переробці." },
