    { en = "Master the creation of $@spellname447355 by gaining +$ev1 $en1 toward this particular part per point in this specialization.", ua = "Опануйте створення $@spellname447355, отримуючи +$ev1 $en1 до цієї конкретної частини за кожен пункт у цій спеціалізації." },
    { en = "Master the creation of $@spellname447356 by gaining +$ev1 $en1 toward this particular part per point in this specialization.", ua = "Опануйте створення $@spellname447356, отримуючи +$ev1 $en1 до цієї конкретної частини за кожен пункт у цій спеціалізації." },
    { en = "Master the creation of various inscription services and the esoteric Darkmoon Cards.", ua = "Опануйте створення різноманітних послуг накреслення та езотеричних Карт Темного Місяця." },
    { en = "Master the different tools and accessories used by various professions.", ua = "Опануйте різноманітні інструменти й приладдя, які використовують різні професії." },
    { en = "Master the esoteric Darkmoon Cards, molding them into your creation.", ua = "Опануйте езотеричні Карти Темного Місяця, вплітаючи їх у свій виріб." },
    { en = "Master the fine art of handling the uncommon carnivorous herb of Khaz Algar's caverns -- Luredrop, gaining +$ev1 $en1 per point in this sub-specialization while gathering it.", ua = "Опануйте витончене мистецтво поводження з рідкісною хижою травою печер Каз Алґара — Приманкоцвітом, отримуючи +$ev1 $en1 за кожен пункт у цій підспеціалізації під час її збору." },
    { en = "Master the fundamentals of Inscription, improving your ability to craft in general.", ua = "Опануйте основи Накреслення, покращивши свою здатність до виготовлення загалом." },
    { en = "Master the fundamentals of Midnight Botany, learning the final sub-specialization.", ua = "Опануйте основи Ботаніки Опівночі, вивчивши останню підспеціалізацію." },
    { en = "Master the fundamentals of working with the herbs of Khaz Algar, gaining +$ev1 Alchemy $en1 per point in this specialization.", ua = "Опануйте основи роботи з травами Каз Алґара, отримуючи +$ev1 $en1 для Алхімії за кожен пункт у цій спеціалізації." },
    { en = "Master the methods of Masterful Garnets, gaining +$ev1 $en1 when cutting them per point in this Specialization.", ua = "Опануйте методи Майстерних Гранатів, отримуючи +$ev1 $en1 при їх огранюванні за кожен пункт у цій Спеціалізації." },
    { en = "Master the methods of Masterful Lapises, gaining +$ev1 $en1 when cutting them per point in this Specialization.", ua = "Опануйте методи Майстерних Лазуритів, отримуючи +$ev1 $en1 при їх огранюванні за кожен пункт у цій Спеціалізації." },
    { en = "Master the methods of Masterful Peridots, gaining +$ev1 $en1 when cutting them per point in this Specialization.", ua = "Опануйте методи Майстерних Перидотів, отримуючи +$ev1 $en1 при їх огранюванні за кожен пункт у цій Спеціалізації." },
    { en = "Master the process of transmutation, gaining +$ev1 $en1 for these crafts per point in this specialization.", ua = "Опануйте процес трансмутації, отримуючи +$ev1 $en1 для цих виробів за кожен пункт у цій спеціалізації." },
    { en = "Master the subtle art of potion-making via techniques from Khaz Algar.", ua = "Опануйте витончене мистецтво виготовлення зілля за техніками з Каз Алґара." },
    { en = "Master the techniques of Khaz Algar to craft specialty items beyond that of standard armor.", ua = "Опануйте техніки Каз Алґара, щоб виготовляти спеціальні предмети поза межами стандартної броні." },
    { en = "Master the techniques of Khaz Algar to improve your ability to craft weapons of various types.", ua = "Опануйте техніки Каз Алґара, щоб покращити свою здатність виготовляти зброю різних типів." },
    { en = "Master your Leatherworking fundamentals to increase your reagent efficiency, ability to concentrate, general stitchwork, and production process.", ua = "Опануйте основи Шкіряної справи, щоб підвищити ефективність реагентів, здатність зосереджуватися, загальне шиття та процес виробництва." },
    { en = "Master your ability to craft new weapons and profession equipment.", ua = "Опануйте свою здатність виготовляти нову зброю та професійне спорядження." },
    { en = "Master your ability to experiment with the various flora found in Khaz Algar.", ua = "Опануйте свою здатність експериментувати з різноманітною флорою Каз Алґара." },
    { en = "Master your disenchanting capabilities, maximizing the quality of reagents you receive when destroying items.", ua = "Опануйте свої здібності розчаклування, максимізуючи якість реагентів, які ви отримуєте при знищенні предметів." },
    { en = "Master your flavorful illusions, aiding the heroes of Azeroth by making them look positively magical, gaining +$ev1 $en1 per point in this Specialization.", ua = "Опануйте свої вишукані ілюзії, допомагаючи героям Азероту виглядати справді магічно, отримуючи +$ev1 $en1 за кожен пункт у цій Спеціалізації." },
    { en = "Master your flavorful illusions, aiding the heroes of Azeroth by making them look positively magical. Gain +$ev1 $en1 per point in this Specialization while crafting temporary illusions.", ua = "Опануйте свої вишукані ілюзії, допомагаючи героям Азероту виглядати справді магічно. Отримуйте +$ev1 $en1 за кожен пункт у цій Спеціалізації при створенні тимчасових ілюзій." },
    { en = "Master your fundamental disenchanting rituals, maximizing the quality of reagents you create when destroying items. You will gain +$ev1 Skill per point in this Specialization when disenchanting.", ua = "Опануйте свої базові ритуали розчаклування, максимізуючи якість реагентів, які ви створюєте при знищенні предметів. Ви отримаєте +$ev1 Уміння за кожен пункт у цій Спеціалізації при розчаклуванні." },
    { en = "Master your fundamental rituals, increasing Skill by +$ev1 when disenchanting Khaz Algar equipment.", ua = "Опануйте свої базові ритуали, підвищуючи Уміння на +$ev1 при розчаклуванні спорядження Каз Алґара." },
    { en = "Master your fundamental rituals, increasing Skill by +$ev1 when disenchanting Midnight equipment.", ua = "Опануйте свої базові ритуали, підвищуючи Уміння на +$ev1 при розчаклуванні спорядження Опівночі." },
    { en = "Master your general Disenchanting Skill, gaining +$ev1 Skill per point in this Specialization when disenchanting Midnight equipment.", ua = "Опануйте своє загальне Уміння розчаклування, отримуючи +$ev1 Уміння за кожен пункт у цій Спеціалізації при розчаклуванні спорядження Опівночі." },
    { en = "Master your manufacturing skills, gaining +$ev1 $en1 while crafting Reagents per point in this Specialization.", ua = "Опануйте свої виробничі навички, отримуючи +$ev1 $en1 при виготовленні Реагентів за кожен пункт у цій Спеціалізації." },
    { en = "Master your skills over Arcane Duplication, creating an additional herb when you use it.", ua = "Опануйте свої навички Арканного Дублювання, створюючи додаткову траву при його використанні." },
    { en = "Maximum scrap yield from most sources is increased by $ev2.", ua = "Максимальний вихід брухту з більшості джерел збільшено на $ev2." },
    { en = "Meticulously study the art of glovemaking. Gain +$ev1 $en1 when crafting cloth gloves.", ua = "Ретельно вивчайте мистецтво виготовлення рукавиць. Отримуйте +$ev1 $en1 під час виготовлення тканинних рукавиць." },
    { en = "Milling is $ev1% faster.|n|n+$ev2 $en2 when milling Dragon Isles herbs.", ua = "Помел на $ev1% швидший.|n|n+$ev2 $en2 під час помелу трав Драконових Островів." },
    { en = "Mining Crystallized deposits grant an additional 30% cooldown reduction to $@spellname423394.", ua = "Видобуток кристалізованих покладів дає додаткові 30% зниження перезарядження для $@spellname423394." },
    { en = "Mining EZ-Mine deposits grant an additional 30% cooldown reduction to $@spellname423394.", ua = "Видобуток покладів EZ-Mine дає додаткові 30% зниження перезарядження для $@spellname423394." },
    { en = "Mining Hardened deposits will grant you a shield of stone that reduces all damage for a short while.", ua = "Видобуток загартованих покладів дарує вам кам'яний щит, що на короткий час зменшує всю отримувану шкоду." },
    { en = "Mining Lightfused deposits reduces the cooldown of Overload by an additional 5%.", ua = "Видобуток покладів, зрослих зі Світлом, додатково зменшує перезарядження Перевантаження на 5%." },
    { en = "Mining Molten deposits empowers you with the element of fire. Your abilities cause the enemy to erupt in flame for 6 sec.", ua = "Видобуток розплавлених покладів наділяє вас стихією вогню. Ваші здібності змушують ворога спалахнути полум'ям на 6 сек." },
    { en = "Mining Primal deposits reduces the cooldown of Overload by an additional 5%.", ua = "Видобуток первісних покладів додатково зменшує перезарядження Перевантаження на 5%." },
    { en = "Mining Voidbound deposits reduces the cooldown of Overload by an additional 5%.", ua = "Видобуток покладів, зв'язаних Порожнечею, додатково зменшує перезарядження Перевантаження на 5%." },
    { en = "Mining Webbed Ore Deposits grant an additional 30% cooldown reduction to $@spellname423394.", ua = "Видобуток обплетених павутиною рудних покладів дає додаткові 30% зниження перезарядження для $@spellname423394." },
    { en = "Mining Weeping deposits grant an additional 30% cooldown reduction to $@spellname423394.", ua = "Видобуток плакучих покладів дає додаткові 30% зниження перезарядження для $@spellname423394." },
    { en = "Mining Wild deposits reduces the cooldown of Overload by an additional 5%.", ua = "Видобуток диких покладів додатково зменшує перезарядження Перевантаження на 5%." },
    { en = "Mining any elemental deposit now reduces the cooldown of Overload by an additional 5%.", ua = "Видобуток будь-якого елементального покладу тепер додатково зменшує перезарядження Перевантаження на 5%." },
    { en = "Much can be learned from failure. Whenever your tinkers malfunction, you have a chance to devise schematics for Safety Components. These are optional reagents that alter tinker behavior.|n|nYou may now insert Safety Components into your crafted equipment.", ua = "Багато чого можна навчитися з невдач. Щоразу, коли ваші механізми дають збій, ви маєте шанс розробити креслення Запобіжних компонентів. Це необов'язкові реагенти, що змінюють поведінку механізмів.|n|nТепер ви можете вставляти Запобіжні компоненти у створене вами спорядження." },
    { en = "Multicraft grants up to $ev1% extra alloys and other reagents.", ua = "Багатовиробництво дає до $ev1% додаткових сплавів та інших реагентів." },
    { en = "Multicraft grants up to $ev1% extra phials.", ua = "Багатовиробництво дає до $ev1% додаткових фіалів." },
    { en = "Multicraft grants up to $ev1% extra potions.", ua = "Багатовиробництво дає до $ev1% додаткового зілля." },
    { en = "Multicraft grants up to $ev1% extra reagents and incenses.", ua = "Багатовиробництво дає до $ev1% додаткових реагентів і пахощів." },
    { en = "Multicraft grants up to $ev1% extra stone goods.", ua = "Багатовиробництво дає до $ev1% додаткових кам'яних виробів." },
    { en = "Multicraft grants up to $ev2% extra inks.", ua = "Багатовиробництво дає до $ev2% додаткового чорнила." },
