    { en = "Multicraft grants up to +$ev1% additional goods when crafting Tailoring Patterns.", ua = "Багатовиробництво дає до +$ev1% додаткових товарів під час виготовлення викрійок Кравецтва." },
    { en = "Multicraft grants up to +$ev1% additional goods when crafting consumables.", ua = "Багатовиробництво дає до +$ev1% додаткових товарів під час виготовлення витратних матеріалів." },
    { en = "Multicraft grants up to +$ev1% additional goods when crafting illusions.", ua = "Багатовиробництво дає до +$ev1% додаткових товарів під час виготовлення ілюзій." },
    { en = "Multicraft grants up to +$ev1% additional items when crafting armor kits.", ua = "Багатовиробництво дає до +$ev1% додаткових предметів під час виготовлення комплектів броні." },
    { en = "Multicraft grants up to +$ev1% additional items when crafting commodities.", ua = "Багатовиробництво дає до +$ev1% додаткових предметів під час виготовлення ходових товарів." },
    { en = "Multicraft grants up to +$ev1% additional items when crafting consumables.", ua = "Багатовиробництво дає до +$ev1% додаткових предметів під час виготовлення витратних матеріалів." },
    { en = "Multicraft grants up to +$ev1% additional items when crafting drums.", ua = "Багатовиробництво дає до +$ev1% додаткових предметів під час виготовлення барабанів." },
    { en = "Multicraft grants up to +$ev1% additional items when crafting reagents.", ua = "Багатовиробництво дає до +$ev1% додаткових предметів під час виготовлення реагентів." },
    { en = "Multicraft grants up to +$ev1% additional items.", ua = "Багатовиробництво дає до +$ev1% додаткових предметів." },
    { en = "Multicrafting grants $ev1% additional goods when crafting Midnight Tailoring recipes.", ua = "Багатовиробництво дає $ev1% додаткових товарів під час виготовлення рецептів Кравецтва Опівночі." },
    { en = "Multicrafting yields $ev1% more resources.", ua = "Багатовиробництво дає на $ev1% більше ресурсів." },
    { en = "Multicrafting yields more flasks.", ua = "Багатовиробництво дає більше флаконів." },
    { en = "Multicrafting yields more phials.", ua = "Багатовиробництво дає більше фіалів." },
    { en = "Neutralizing toxic potions now grants toxic reagents.", ua = "Нейтралізація токсичного зілля тепер дає токсичні реагенти." },
    { en = "Non-combat potions last longer.", ua = "Небойове зілля діє довше." },
    { en = "Not yet implemented!||n||nCome back later!", ua = "Ще не реалізовано!||n||nЗавітайте пізніше!" },
    { en = "Optimize your Crushing skills, gaining +$ev1 $en1 while Crushing gems per point in this Specialization.", ua = "Вдоскональте свої навички дроблення, отримуючи +$ev1 $en1 під час дроблення самоцвітів за кожне очко в цій Спеціалізації." },
    { en = "Optimize your Optional Reagents, gaining +$ev1 $en1 while crafting Optional Reagents per point in this Specialization.", ua = "Вдоскональте свої необов'язкові реагенти, отримуючи +$ev1 $en1 під час виготовлення необов'язкових реагентів за кожне очко в цій Спеціалізації." },
    { en = "Overloaded void chunks give more Motes of Pure Void when collected.", ua = "Перевантажені уламки Порожнечі дають більше Часток чистої Порожнечі під час збирання." },
    { en = "Overloading Frigid Herbs causes the frost to form a protective layer around you, freezing targets for a short while the first time they attack you.", ua = "Перевантаження Крижаних трав змушує мороз утворити навколо вас захисний шар, що на короткий час заморожує цілі, коли вони вперше на вас нападають." },
    { en = "Overloading Titan-Touched herbs will now sometimes reveal a Glowing Titan Orb.", ua = "Перевантаження торкнутих Титанами трав тепер іноді відкриває Сяйну титанову кулю." },
    { en = "Overloading Titan-Touched ore will now sometimes reveal a Glowing Titan Orb.", ua = "Перевантаження торкнутої Титанами руди тепер іноді відкриває Сяйну титанову кулю." },
    { en = "Overloading a Crystallized deposit grants bonus Crystalline Powder.", ua = "Перевантаження кристалізованого покладу дає додатковий кристалічний порошок." },
    { en = "Overloading a Crystallized herb has a chance to grant you extra Crystalline Powder.", ua = "Перевантаження кристалізованої трави має шанс дати вам додатковий кристалічний порошок." },
    { en = "Overloading a Lightfused deposit generates more Motes of Light.", ua = "Перевантаження покладу, зрослого зі Світлом, породжує більше Часток Світла." },
    { en = "Overloading a Webbed Ore Deposit now summons twice as many Spindlespiders to capture.", ua = "Перевантаження обплетеного павутиною рудного покладу тепер прикликає вдвічі більше веретенопавуків, яких можна впіймати." },
    { en = "Perfect the art of temporary illusions, equipment, and mana oils, gaining +$ev1 $en1 per point in this Specialization.", ua = "Вдоскональте мистецтво тимчасових ілюзій, спорядження та манаолій, отримуючи +$ev1 $en1 за кожне очко в цій Спеціалізації." },
    { en = "Perfect the art of temporary illusions, equipment, and mana oils.", ua = "Вдоскональте мистецтво тимчасових ілюзій, спорядження та манаолій." },
    { en = "Perfect the art of temporary illusions, equipment, reagents, and mana oils.", ua = "Вдоскональте мистецтво тимчасових ілюзій, спорядження, реагентів та манаолій." },
    { en = "Perfect your skills at generating armor kits, gaining +$ev1 $en1 per point in this Specialization when crafting them.", ua = "Вдоскональте свої навички створення комплектів броні, отримуючи +$ev1 $en1 за кожне очко в цій Спеціалізації під час їх виготовлення." },
    { en = "Performing acts of $@spellname430315 now grant Gleaming Transmutagen.", ua = "Виконання $@spellname430315 тепер дає Осяйний трансмутаген." },
    { en = "Performing acts of $@spellname430315 now have a chance to create a Coreway Catalyst.", ua = "Виконання $@spellname430315 тепер має шанс створити Каталізатор Серцевинного шляху." },
    { en = "Performing acts of $@spellname430315 now sometimes reveal a beautiful gemstone.", ua = "Виконання $@spellname430315 тепер іноді відкриває прекрасний самоцвіт." },
    { en = "Periodically gain an absorb shield for x when engaged with 2 or more enemies.", ua = "Періодично отримуйте поглинальний щит на x, коли б'єтеся з 2 або більше ворогами." },
    { en = "Phoenix Flames and Dragon's Breath always critically strike and Dragon's Breath contributes to Hot Streak.", ua = "Феніксове полум'я та Драконів подих завжди завдають критичного удару, а Драконів подих зараховується до Гарячої смуги." },
    { en = "Pick between Transitories, Tonics, or Tools and learn a sub-specialization of your choice.", ua = "Оберіть між Ефемерами, Тоніками чи Інструментами й вивчіть підспеціалізацію на свій вибір." },
    { en = "Polish your skills surrounding Arathi Accessory formulas, gaining +$ev1 $en1 per point in this Specialization.", ua = "Відточіть свої навички роботи з формулами аксесуарів Араті, отримуючи +$ev1 $en1 за кожне очко в цій Спеціалізації." },
    { en = "Polish your skills surrounding Nerubian Bracer and Cloak formulas, gaining +$ev1 $en1 per point in this Specialization.", ua = "Відточіть свої навички роботи з нерубіанськими формулами наручів і плащів, отримуючи +$ev1 $en1 за кожне очко в цій Спеціалізації." },
    { en = "Portable workstations you place last twice as long.", ua = "Переносні верстати, які ви розміщуєте, діють удвічі довше." },
    { en = "Practice creating special Finishing Reagents to empower the crafts of others, gaining +$ev1 $en1 per point in this Specialization.", ua = "Практикуйте створення особливих завершальних реагентів, щоб посилити витвори інших, отримуючи +$ev1 $en1 за кожне очко в цій Спеціалізації." },
    { en = "Practice general gemcutting techniques, gaining +$ev1 $en1 when cutting Midnight gems per point in this Specialization.", ua = "Практикуйте загальні техніки огранювання, отримуючи +$ev1 $en1 під час огранювання самоцвітів Опівночі за кожне очко в цій Спеціалізації." },
    { en = "Practice new methods for harvesting Writhebark, gaining +$ev1 $en1 per point in this specialization while gathering it.", ua = "Практикуйте нові методи збору звивокори, отримуючи +$ev1 $en1 за кожне очко в цій спеціалізації під час її збирання." },
    { en = "Practice the art of creating potent Optional Reagents, gaining +$ev1 $en1 per point in this Specialization when crafting them.", ua = "Практикуйте мистецтво створення потужних необов'язкових реагентів, отримуючи +$ev1 $en1 за кожне очко в цій Спеціалізації під час їх виготовлення." },
    { en = "Practice the meticulous process of spotting, harvesting, and storing the herbs of Khaz Algar more efficiently, gaining +$ev1 $en1 while gathering.", ua = "Вправляйся в ретельному процесі помічання, збору й зберігання трав Каз Алґара ефективніше, отримуючи +$ev1 $en1 під час збирання." },
    { en = "Practice the meticulous process of spotting, harvesting, and storing the herbs of the Midnight region more efficiently, gaining +$ev1 $en1 while gathering.", ua = "Вправляйся в ретельному процесі помічання, збору й зберігання трав регіону Опівночі ефективніше, отримуючи +$ev1 $en1 під час збирання." },
    { en = "Practice the meticulous process of spotting, harvesting, and storing your herbs more efficiently, gaining expertise focused on the various herbs found in the Midnight region.", ua = "Вправляйся в ретельному процесі помічання, збору й зберігання своїх трав ефективніше, здобуваючи досвід, зосереджений на різних травах регіону Опівночі." },
    { en = "Practice your Leatherworking fundamentals, gaining +$ev1 $en1 per point in this Specialization.", ua = "Вправляйся в основах шкіряної справи, отримуючи +$ev1 $en1 за кожне очко в цій спеціалізації." },
    { en = "Practice your gemcutting techniques, creating the most dazzling and glamorous gems available.", ua = "Вдосконалюй свої техніки огранювання самоцвітів, створюючи найсліпучіші та найчарівніші самоцвіти, які тільки є." },
    { en = "Practice your leather gathering techniques, gaining +$ev1 $en1 while skinning leathery creatures in the Midnight region per point in this Specialization.", ua = "Вправляй свої техніки збору шкіри, отримуючи +$ev1 $en1 під час білування шкірястих істот у регіоні Опівночі за кожне очко в цій спеціалізації." },
    { en = "Practice your more powerful disenchanting formulas, increasing your Skill by +$ev1 per point in this Specialization when disenchanting Rare equipment.", ua = "Вправляйся в потужніших формулах розчаклування, підвищуючи своє вміння на +$ev1 за кожне очко в цій спеціалізації під час розчаклування рідкісного спорядження." },
    { en = "Practice your most complex disenchanting formulas, increasing your Skill by +$ev1 per point in this Specialization when disenchanting Epic equipment.", ua = "Вправляйся в найскладніших формулах розчаклування, підвищуючи своє вміння на +$ev1 за кожне очко в цій спеціалізації під час розчаклування епічного спорядження." },
    { en = "Practice your ritual for disenchanting Rare Midnight equipment, gaining +$ev1 Skill per point in this Specialization when disenchanting Rare Midnight equipment.", ua = "Вправляй свій ритуал розчаклування рідкісного спорядження Опівночі, отримуючи +$ev1 вміння за кожне очко в цій спеціалізації під час розчаклування рідкісного спорядження Опівночі." },
    { en = "Prepare yourself to shine while working with Brilliant Silver, bestowing the ability to find Eversong Diamonds while prospecting it.", ua = "Готуйся сяяти в роботі з сяйливим сріблом, що дає здатність знаходити вічноспівні діаманти під час його перебирання." },
    { en = "Primal Essence now also gives your spells and abilities a chance to unleash a blast of damage from an elemental school.", ua = "Первісна есенція тепер також дає твоїм закляттям і здібностям шанс вивільнити вибух шкоди однієї зі стихійних шкіл." },
    { en = "Primal deposits now have a chance to contain Rousing Air or Rousing Frost, essences not traditionally found by miners.", ua = "Первісні поклади тепер мають шанс містити буремне повітря чи буремний мороз — есенції, які зазвичай не знаходять шахтарі." },
    { en = "Primal enchantment crafts are $ev1% faster.|n|nLearn the final sub-specialization.", ua = "Виготовлення первісних зачарувань на $ev1% швидше.|n|nВивчи останню підспеціалізацію." },
    { en = "Progress your skills towards mass production, gaining +$ev1 $en1 per point in this Specialization.", ua = "Розвивай свої вміння до масового виробництва, отримуючи +$ev1 $en1 за кожне очко в цій спеціалізації." },
    { en = "Prospecting Prismatic Ore has a chance to contain Khaz'gorite Ore.|n|nProspecting speed increased by $ev1%.", ua = "Перебирання призматичної руди має шанс містити каз'горитову руду.|n|nШвидкість перебирання підвищено на $ev1%." },
    { en = "Prospecting speed increased by $ev1%.", ua = "Швидкість перебирання підвищено на $ev1%." },
    { en = "Prove your mastery of Embroidered Ensembles by learning the final sub-specialization.|n|nLearn to use Finishing Reagents on embroidered leather armor patterns.|n|n+$ev1 $en1 when crafting embroidered leather armor pieces.", ua = "Доведи свою майстерність вишитих комплектів, вивчивши останню підспеціалізацію.|n|nНавчися використовувати завершальні реагенти на викрійках вишитого шкіряного обладунку.|n|n+$ev1 $en1 під час виготовлення частин вишитого шкіряного обладунку." },
    { en = "Qualify yourself to craft Quick Amethysts, gaining +$ev1 $en1 when cutting them per point in this Specialization.", ua = "Здобудь право виготовляти швидкі аметисти, отримуючи +$ev1 $en1 під час їх огранювання за кожне очко в цій спеціалізації." },
    { en = "Qualify yourself to craft Quick Garnets, gaining +$ev1 $en1 when cutting them per point in this Specialization.", ua = "Здобудь право виготовляти швидкі гранати, отримуючи +$ev1 $en1 під час їх огранювання за кожне очко в цій спеціалізації." },
    { en = "Qualify yourself to craft Quick Lapises, gaining +$ev1 $en1 when cutting them per point in this Specialization.", ua = "Здобудь право виготовляти швидкі лазурити, отримуючи +$ev1 $en1 під час їх огранювання за кожне очко в цій спеціалізації." },
    { en = "Qualify yourself to make quality Amani Profession Tool enchantments, gaining +$ev1 $en1 per point in this Specialization.", ua = "Здобудь право виготовляти якісні чари амані для професійних інструментів, отримуючи +$ev1 $en1 за кожне очко в цій спеціалізації." },
    { en = "Reach new heights with Advanced Armor, learning another sub-specialization of your choice.", ua = "Досягни нових висот у передовому обладунку, вивчивши ще одну підспеціалізацію на свій вибір." },
    { en = "Reach the apex of Bolstered Bulwarks mail armor, learning the final sub-specialization.|n|nLearn to use Finishing Reagents on Bolstered Bulwarks mail armor patterns.|n|n+$ev1 $en1 when crafting Bolstered Bulwarks mail armor pieces.", ua = "Досягни вершини кольчужного обладунку «Укріплені бастіони», вивчивши останню підспеціалізацію.|n|nНавчися використовувати завершальні реагенти на викрійках кольчужного обладунку «Укріплені бастіони».|n|n+$ev1 $en1 під час виготовлення частин кольчужного обладунку «Укріплені бастіони»." },
