    { en = "Reduces the likelihood for bombs to explode in your face or tinkers to malfunction.", ua = "Зменшує ймовірність того, що бомби вибухнуть тобі в обличчя чи механізми дадуть збій." },
    { en = "Refine your skills in the art of Amani enchantments, gaining +$ev1 $en1 per point in this Specialization.", ua = "Вдоскональ свою майстерність у мистецтві зачарувань амані, отримуючи +$ev1 $en1 за кожне очко в цій спеціалізації." },
    { en = "Refine your techniques to make the most of flasks and phials.", ua = "Вдоскональ свої техніки, щоб отримати якнайбільше від флаконів і фіалів." },
    { en = "Refining Draconium ore now has a small chance of finding Rousing Essences.", ua = "Обробка драконієвої руди тепер має невеликий шанс знайти буремні есенції." },
