    { en = "Restore 1 charge for your skyriding abilities when mining any Midnight deposit.", ua = "Відновлює 1 заряд твоїх здібностей небесної їзди при видобуванні будь-якого покладу Опівночі." },
    { en = "Return portals are now summoned at your destination after Overloading Crystallized deposits.", ua = "Тепер портали повернення викликаються в місці твого призначення після перевантаження Кристалізованих покладів." },
    { en = "Rexxar gains Arrow Volley. He will call out a location, and after a few seconds will fire arrows in that direction, dealing massive damage.", ua = "Рекссар отримує «Залп стріл». Він оголосить місце, а за кілька секунд випустить стріли в тому напрямку, завдаючи величезної шкоди." },
    { en = "Rexxar has a chance to join you in combat.", ua = "Рекссар має шанс приєднатися до тебе в бою." },
    { en = "Rod and wand crafts are $ev1% faster.|n|nLearn to craft and use the $@spellname391202 Finishing Reagent to improve Skill when crafting rods and wands.", ua = "Жезли й палички виготовляються на $ev1% швидше.|n|nНавчися виготовляти й використовувати завершальний реагент $@spellname391202, щоб покращити Навичку при виготовленні жезлів і паличок." },
    { en = "Round out your Securely Shaped knowledge by learning the final sub-specialization.|n|nLearn to use Finishing Reagents on shaped leather armor patterns.|n|n+$ev1 $en1 when crafting shaped leather armor pieces.", ua = "Доверши свої знання «Надійно формованого», вивчивши останню підспеціалізацію.|n|nНавчися використовувати завершальні реагенти на викрійках формованої шкіряної броні.|n|n+$ev1 $en1 при виготовленні деталей формованої шкіряної броні." },
    { en = "Round out your elemental prowess, learning the final sub-specialization.", ua = "Доверши свою стихійну майстерність, вивчивши останню підспеціалізацію." },
    { en = "Round yourself out by learning the final sub-specialization.", ua = "Удосконали себе, вивчивши останню підспеціалізацію." },
    { en = "Ruminate on your Rings, gaining +$ev1 $en1 when crafting them per point in this Specialization.", ua = "Розмірковуй над своїми Перснями, отримуючи +$ev1 $en1 при їх виготовленні за кожен пункт у цій спеціалізації." },
    { en = "Runebinding goods craft $ev1% faster.|n|nLearn to use special Finishing Reagents such as Blotting Sand to further improve your Runebinding crafts.", ua = "Вироби Зв'язування рун виготовляються на $ev1% швидше.|n|nНавчися використовувати особливі завершальні реагенти, як-от Промокальний пісок, щоб іще більше покращити свої вироби Зв'язування рун." },
    { en = "Runic Scripture goods craft $ev1% faster.|n|n+$ev2 $en2 when making Runic Scripture goods.", ua = "Вироби Рунічного письма виготовляються на $ev1% швидше.|n|n+$ev2 $en2 при виготовленні виробів Рунічного письма." },
    { en = "Sands of Time has a chance equal to your critical strike to extend Ebon Might by an additional 1/2 sec.", ua = "«Піски часу» мають шанс, рівний твоєму критичному удару, подовжити «Чорну Могутність» на додаткові 1/2 сек." },
    { en = "Shared Knowledge crafts are $ev1% faster.|n|n+$ev2 $en2 when making these crafts.", ua = "Вироби Спільного знання виготовляються на $ev1% швидше.|n|n+$ev2 $en2 при виготовленні цих виробів." },
    { en = "Shared Knowledge crafts are $ev1% faster.|n|n+$ev2 $en2 when making these crafts.|n|nLearn to craft and use the $@spellname391781 Finishing Reagent to improve Skill when making Shared Knowledge crafts.", ua = "Вироби Спільного знання виготовляються на $ev1% швидше.|n|n+$ev2 $en2 при виготовленні цих виробів.|n|nНавчися виготовляти й використовувати завершальний реагент $@spellname391781, щоб покращити Навичку при виготовленні виробів Спільного знання." },
    { en = "Shifting out of Incarnation before it expires ends the effect and refunds a portion of its cooldown.||n||n[OR]||n||nConvoke the Spirits has an increased chance to use an exceptional spell or ability.", ua = "Вихід із Втілення до його завершення припиняє ефект і повертає частину його перезарядження.||n||n[АБО]||n||n«Скликання духів» має підвищений шанс застосувати виняткове закляття чи здібність." },
    { en = "Shore up your skills in skinning leather, gaining +$ev1 $en1 while skinning primarily leather-yielding creatures per point in this Specialization.", ua = "Зміцни свої навички білування шкіри, отримуючи +$ev1 $en1 під час білування істот, що дають переважно шкіру, за кожен пункт у цій спеціалізації." },
    { en = "Shorten the recovery time after crafting Arcanoweave Bolts.", ua = "Скорочує час відновлення після виготовлення Сувоїв арканоплетива." },
    { en = "Shorten the recovery time after crafting Sunfire Silk Bolts.", ua = "Скорочує час відновлення після виготовлення Сувоїв шовку сонячного вогню." },
    { en = "Sir Finley Mrgggle has a chance to join you in battle.", ua = "Сер Фінлі Мрґґґл має шанс приєднатися до тебе в бою." },
    { en = "Skill up with Thalassian Profession Tool enchantments, gaining +$ev1 $en1 per point in this Specialization.", ua = "Вдосконалюйся в чарах Таласійських професійних інструментів, отримуючи +$ev1 $en1 за кожен пункт у цій спеціалізації." },
    { en = "Slows the rate of fungal spores infesting you. It's not advised to be exposed to them for too long.", ua = "Уповільнює швидкість зараження тебе грибковими спорами. Не радимо перебувати під їх впливом занадто довго." },
    { en = "Solar Eclipse is 3 sec longer and Lunar Eclipse is 3 sec shorter.", ua = "«Сонячне затемнення» триває на 3 сек. довше, а «Місячне затемнення» — на 3 сек. коротше." },
    { en = "Source the magic of the Dragon Isles to craft exceptional clothwear with reagents such as Azureweave and Chronocloth, gaining +$ev1 $en1 per point in this Specialization.", ua = "Черпай магію Драконових Островів, щоб виготовляти виняткові тканинні вироби з реагентів, як-от Лазурне плетиво і Хронотканина, отримуючи +$ev1 $en1 за кожен пункт у цій спеціалізації." },
    { en = "Specialize in Decayed herbs, gaining +$ev1 $en1 per point in this specialization while gathering them.", ua = "Спеціалізуйся на Зотлілих травах, отримуючи +$ev1 $en1 за кожен пункт у цій спеціалізації під час їх збору." },
    { en = "Specialize in Frigid herbs, gaining +$ev1 $en1 per point in this specialization while gathering them.", ua = "Спеціалізуйся на Крижаних травах, отримуючи +$ev1 $en1 за кожен пункт у цій спеціалізації під час їх збору." },
    { en = "Specialize in Titan-Touched herbs, gaining +$ev1 $en1 per point in this specialization while gathering them.", ua = "Спеціалізуйся на Титаноторкнутих травах, отримуючи +$ev1 $en1 за кожен пункт у цій спеціалізації під час їх збору." },
    { en = "Specialize in Windswept herbs, gaining +$ev1 $en1 per point in this specialization while gathering them.", ua = "Спеціалізуйся на Овіяних вітром травах, отримуючи +$ev1 $en1 за кожен пункт у цій спеціалізації під час їх збору." },
    { en = "Specialize in a variety of useful but nonspecific skills to improve your abilities generally as an Engineer. Gain +$ev1 $en1 to all Engineering crafts per point in this specialization.", ua = "Спеціалізуйся на різноманітних корисних, але неспецифічних навичках, щоб загалом покращити свої здібності як Інженера. Отримуй +$ev1 $en1 до всіх виробів Інженерії за кожен пункт у цій спеціалізації." },
    { en = "Specialize in acquiring additional materials when disenchanting items and objects.", ua = "Спеціалізуйся на здобутті додаткових матеріалів при розчаклуванні предметів і об'єктів." },
    { en = "Specialize in binding complex runes into Staves and Profession Tools, gaining +$ev1 $en1 per point in this Specialization.", ua = "Спеціалізуйся на зв'язуванні складних рун у Посохи й професійні інструменти, отримуючи +$ev1 $en1 за кожен пункт у цій спеціалізації." },
    { en = "Specialize in carving runic sigils into powerful pieces of equipment such as Codexes, Vantus Runes, and Fauna Runes. Gain +$ev1 $en1 per point in this Specialization.", ua = "Спеціалізуйся на вирізьблюванні рунічних сигілів на потужному спорядженні, як-от Кодекси, Руни Вантуса й Руни фауни. Отримуй +$ev1 $en1 за кожен пункт у цій спеціалізації." },
    { en = "Specialize in carving staves and profession tools, as well as forming runes to enhance your equipment and defeat powerful enemies.", ua = "Спеціалізуйся на вирізьблюванні посохів і професійних інструментів, а також на створенні рун, щоб покращувати своє спорядження й перемагати могутніх ворогів." },
    { en = "Specialize in crafting Scale Sigils that alter the shuffling effects of your Darkmoon Deck Box, gaining +$ev1 $en1 per point in this Specialization.", ua = "Спеціалізуйся на виготовленні Лускатих сигілів, що змінюють ефекти тасування твоєї Скриньки колоди Темного Місяця, отримуючи +$ev1 $en1 за кожен пункт у цій спеціалізації." },
    { en = "Specialize in crafting a broad range of equipment necessary for your adventures in Khaz Algar.", ua = "Спеціалізуйся на виготовленні широкого спектра спорядження, потрібного для твоїх пригод у Каз Алґарі." },
    { en = "Specialize in crafting and customizing high quality plate armor.", ua = "Спеціалізуйся на виготовленні й налаштуванні високоякісної латної броні." },
    { en = "Specialize in crafting and customizing weapons and tools.", ua = "Спеціалізуйся на виготовленні й налаштуванні зброї та інструментів." },
    { en = "Specialize in crafting cloth armor and profession garments.", ua = "Спеціалізуйтеся на виготовленні тканинної броні та фахового вбрання." },
    { en = "Specialize in crafting equipment and Optional Reagents utilizing unique materials.", ua = "Спеціалізуйтеся на виготовленні спорядження та необов'язкових реагентів із використанням унікальних матеріалів." },
    { en = "Specialize in crafting high quality leather armor.", ua = "Спеціалізуйтеся на виготовленні високоякісної шкіряної броні." },
    { en = "Specialize in crafting high quality mail armor.", ua = "Спеціалізуйтеся на виготовленні високоякісної кольчужної броні." },
    { en = "Specialize in crafting high quality wands, enchanting rods, and illusory goods. Additionally, you will also improve your enchanting efficiency.", ua = "Спеціалізуйтеся на виготовленні високоякісних чарівних паличок, стрижнів для накладання чарів та ілюзорних товарів. Крім того, ви також покращите свою ефективність накладання чарів." },
    { en = "Specialize in crafting highly unique pieces of equipment by communing with and harnessing the magics of both the Bronze and Azure Dragonflights.", ua = "Спеціалізуйтеся на виготовленні винятково унікальних предметів спорядження, спілкуючись із магією Бронзової та Лазурової драконових зграй і використовуючи її." },
    { en = "Specialize in crafting leather armor, increasing your ability to craft at a higher quality. In addition, learn new patterns and ways to customize the armor you craft!", ua = "Спеціалізуйтеся на виготовленні шкіряної броні, підвищуючи свою здатність створювати вищу якість. Крім того, вивчіть нові викрійки та способи налаштування броні, яку ви виготовляєте!" },
    { en = "Specialize in crafting mail armor, increasing your ability to craft at a higher quality. In addition, learn new patterns and ways to customize the armor you craft!", ua = "Спеціалізуйтеся на виготовленні кольчужної броні, підвищуючи свою здатність створювати вищу якість. Крім того, вивчіть нові викрійки та способи налаштування броні, яку ви виготовляєте!" },
    { en = "Specialize in creating bait to lure out elusive creatures for additional materials.", ua = "Спеціалізуйтеся на створенні наживки, щоб виманювати невловимих істот заради додаткових матеріалів." },
    { en = "Specialize in creating phials efficiently and at high qualities.", ua = "Спеціалізуйтеся на створенні флаконів ефективно та високої якості." },
    { en = "Specialize in creating potions efficiently and at high qualities.", ua = "Спеціалізуйтеся на створенні зіль ефективно та високої якості." },
    { en = "Specialize in creating special baits to lure out the elusive creatures of Khaz Algar.", ua = "Спеціалізуйтеся на створенні особливих наживок, щоб виманювати невловимих істот Каз Алґару." },
    { en = "Specialize in creating special lures that will draw out Renowned Beasts that are more valuable than standard creatures.", ua = "Спеціалізуйтеся на створенні особливих принад, що виманюють Славетних звірів, цінніших за звичайних істот." },
    { en = "Specialize in creating the basic parts necessary to create all manner of Engineering goods. Gain +$ev1 $en1 when crafting reagents.", ua = "Спеціалізуйтеся на виготовленні базових деталей, потрібних для створення всіляких інженерних виробів. Отримуйте +$ev1 $en1 під час виготовлення реагентів." },
    { en = "Specialize in efficiently sharing knowledge regarding the Dragon Isles through Contracts, Missives, and Treatises. Gain +$ev1 $en1 per point in this specialization.", ua = "Спеціалізуйтеся на ефективному поширенні знань про Драконові Острови через контракти, послання та трактати. Отримуйте +$ev1 $en1 за кожен бал у цій спеціалізації." },
    { en = "Specialize in enchanting equipment with powerful magic effects.", ua = "Спеціалізуйтеся на накладанні чарів на спорядження з потужними магічними ефектами." },
    { en = "Specialize in gathering Hochenblume, Writhebark, Bubble Poppy, and Saxifrage.", ua = "Спеціалізуйтеся на збиранні Хохенблуме, Звивокори, Бульбашкового маку та Ломикаменю." },
    { en = "Specialize in gathering Serevite and Draconium while always on the lookout for elusive Khaz'gorite.", ua = "Спеціалізуйтеся на збиранні Серевіту й Драконіуму, завжди виглядаючи невловимий Каз'горит." },
    { en = "Specialize in gathering efficiency while learning how to cultivate your own herbs by planting magic seeds.", ua = "Спеціалізуйтеся на ефективності збирання, навчаючись вирощувати власні трави, висаджуючи магічне насіння." },
    { en = "Specialize in gathering efficiency while learning the techniques necessary to make the most of your mining capabilities.", ua = "Спеціалізуйтеся на ефективності збирання, опановуючи техніки, потрібні, щоб якнайкраще використати свої здібності до видобутку." },
    { en = "Specialize in gathering elemental herbs and Overloading them to various effects.", ua = "Спеціалізуйтеся на збиранні елементальних трав і їх Перевантаженні задля різних ефектів." },
    { en = "Specialize in gathering empowered herbs and Overloading them to various effects.", ua = "Спеціалізуйтеся на збиранні наснажених трав і їх Перевантаженні задля різних ефектів." },
    { en = "Specialize in gathering general materials like leather, scales, and hides.", ua = "Спеціалізуйтеся на збиранні загальних матеріалів, як-от шкіра, луска та шкури." },
    { en = "Specialize in gathering the herbs found throughout Khaz Algar.", ua = "Спеціалізуйтеся на збиранні трав, що трапляються по всьому Каз Алґару." },
    { en = "Specialize in gathering unique materials beyond standard leather and scale.", ua = "Спеціалізуйтеся на збиранні унікальних матеріалів поза звичайною шкірою та лускою." },
    { en = "Specialize in harvesting unique materials that are utilized by many professions.", ua = "Спеціалізуйтеся на добуванні унікальних матеріалів, які використовують багато професій." },
    { en = "Specialize in making stone enhancements, reagents, alloys, profession tools, and accessories.", ua = "Спеціалізуйтеся на виготовленні кам'яних підсилень, реагентів, сплавів, професійних інструментів та приладдя." },
    { en = "Specialize in making the most out of seemingly useless junk. Resourcefulness saves $ev1% additional reagents for all Engineering crafts per point in this specialization.", ua = "Спеціалізуйтеся на тому, щоб отримувати максимум зі, здавалося б, непотрібного мотлоху. Винахідливість заощаджує додатково $ev1% реагентів для всіх інженерних виробів за кожен бал у цій спеціалізації." },
    { en = "Specialize in mining Rich deposits across Khaz Algar. Gain +$ev1 $en1 in these deposits per point in this specialization.", ua = "Спеціалізуйтеся на видобутку багатих покладів по всьому Каз Алґару. Отримуйте +$ev1 $en1 у цих покладах за кожен бал у цій спеціалізації." },
    { en = "Specialize in mining Seams across Khaz Algar. Gain +$ev1 $en1 in these deposits per point in this specialization.", ua = "Спеціалізуйтеся на видобутку жил по всьому Каз Алґару. Отримуйте +$ev1 $en1 у цих покладах за кожен бал у цій спеціалізації." },
    { en = "Specialize in mining elemental deposits and Overloading them to various effects.", ua = "Спеціалізуйтеся на видобутку елементальних покладів і їх Перевантаженні задля різних ефектів." },
    { en = "Specialize in mining unusual deposits across Khaz Algar, such as those touched by ominous forces.", ua = "Спеціалізуйтеся на видобутку незвичайних покладів по всьому Каз Алґару, як-от торкнутих зловісними силами." },
    { en = "Specialize in mining unusual deposits across Khaz Algar. You gain +$ev1 $en1 to these deposits per point in this specialization.", ua = "Спеціалізуйтеся на видобутку незвичайних покладів по всьому Каз Алґару. Ви отримуєте +$ev1 $en1 до цих покладів за кожен бал у цій спеціалізації." },
    { en = "Specialize in nuanced mining methodology to improve your techniques. Gain +$ev1 $en1 while mining in Khaz Algar per point in this specialization.", ua = "Спеціалізуйтеся на витонченій методології видобутку, щоб удосконалити свої техніки. Отримуйте +$ev1 $en1 під час видобутку в Каз Алґарі за кожен бал у цій спеціалізації." },
    { en = "Specialize in nuanced mining methodology to improve your techniques. Knowledge in this area will allow you to get the most out of your rich and seam deposits discoveries.", ua = "Спеціалізуйтеся на витонченій методології видобутку, щоб удосконалити свої техніки. Знання в цій царині дадуть вам змогу отримати максимум зі знайдених багатих покладів та жил." },
    { en = "Specialize in prospecting gems from ore and the creation of basic and finishing reagents used in your own crafts and those of other professions.", ua = "Спеціалізуйтеся на видобуванні самоцвітів із руди та створенні базових і завершальних реагентів, які використовуються у ваших власних виробах і виробах інших професій." },
    { en = "Specialize in shattering the magical essences of Khaz Algar, gleaning fleeting but increasingly potent crafting bonuses from the magic within. Your studies will also benefit your Concentration!", ua = "Спеціалізуйтеся на розбиванні магічних есенцій Каз Алґару, здобуваючи з прихованої в них магії скороминущі, але дедалі потужніші бонуси виготовлення. Ваші дослідження також підсилять ваше Зосередження!" },
    { en = "Specialize in shattering the magical essences of Midnight, gleaning fleeting but increasingly potent crafting bonuses from the magic within. Your studies will also benefit your Concentration!", ua = "Спеціалізуйтеся на розбиванні магічних есенцій Опівночі, здобуваючи з прихованої в них магії скороминущі, але дедалі потужніші бонуси виготовлення. Ваші дослідження також підсилять ваше Зосередження!" },
    { en = "Specialize in tailoring cloaks, gaining +$ev1 $en1 per point in this Specialization.", ua = "Спеціалізуйтеся на пошитті плащів, отримуючи +$ev1 $en1 за кожен бал у цій Спеціалізації." },
    { en = "Specialize in tailoring cloth Back armor, gaining +$ev1 $en1 per point in this Specialization.", ua = "Спеціалізуйтеся на пошитті тканинної броні на спину, отримуючи +$ev1 $en1 за кожен бал у цій Спеціалізації." },
