    { en = "Specialize in tailoring cloth waist armor, gaining +$ev1 $en1 per point in this Specialization.", ua = "Спеціалізуйтеся на пошитті тканинної броні на пояс, отримуючи +$ev1 $en1 за кожен бал у цій Спеціалізації." },
    { en = "Specialize in tailoring cloth waist armors, gaining +$ev1 $en1 per point in this Specialization.", ua = "Спеціалізуйтеся на пошитті тканинної броні на пояс, отримуючи +$ev1 $en1 за кожен бал у цій Спеціалізації." },
    { en = "Specialize in tailoring cloth wrist armor, gaining +$ev1 $en1 per point in this Specialization.", ua = "Спеціалізуйтеся на пошитті тканинної броні на зап'ястя, отримуючи +$ev1 $en1 за кожен бал у цій Спеціалізації." },
    { en = "Specialize in tailoring cloth wrist armors, gaining +$ev1 $en1 per point in this Specialization.", ua = "Спеціалізуйтеся на пошитті тканинної броні на зап'ястя, отримуючи +$ev1 $en1 за кожен бал у цій Спеціалізації." },
    { en = "Specialize in the acquisition of various ores scattered upon and beneath Khaz Algar.", ua = "Спеціалізуйтеся на здобуванні різноманітних руд, розкиданих на поверхні та в надрах Каз Алґару." },
    { en = "Specialize in the art of Earthen enchanting, drawing upon their magic and runes to empower weapons, tools, and chest armor. Gain +$ev1 $en1 per point in this Specialization while performing Earthen enchantments.", ua = "Спеціалізуйтеся на мистецтві накладання чарів земельників, черпаючи з їхньої магії та рун, щоб підсилювати зброю, інструменти та броню на груди. Отримуйте +$ev1 $en1 за кожен бал у цій Спеціалізації під час накладання чарів земельників." },
    { en = "Specialize in the art of crafting amulets and rings using various techniques found in Khaz Algar.", ua = "Спеціалізуйтеся на мистецтві виготовлення амулетів і перснів, застосовуючи різноманітні техніки, знайдені в Каз Алґарі." },
    { en = "Specialize in the art of cutting Extravagant Emeralds and Blasphemite, gaining +$ev1 $en1 to each.", ua = "Спеціалізуйтеся на мистецтві гранування Розкішних смарагдів і Блюзніриту, отримуючи +$ev1 $en1 до кожного." },
    { en = "Specialize in the art of cutting Ostentatious Onyxes and Blasphemite, gaining +$ev1 $en1 to each.", ua = "Спеціалізуйтеся на мистецтві гранування Пишних оніксів і Блюзніриту, отримуючи +$ev1 $en1 до кожного." },
    { en = "Specialize in the art of cutting Radiant Rubies and Blasphemite, gaining +$ev1 $en1 to each.", ua = "Спеціалізуйтеся на мистецтві гранування Сяйних рубінів і Блюзніриту, отримуючи +$ev1 $en1 до кожного." },
    { en = "Specialize in the art of cutting Stunning Sapphires and Blasphemite, gaining +$ev1 $en1 to each.", ua = "Спеціалізуйтеся на мистецтві гранування Приголомшливих сапфірів і Блюзніриту, отримуючи +$ev1 $en1 до кожного." },
    { en = "Specialize in the art of gemcutting, gaining +$ev1 $en1 to all gem cuts.", ua = "Спеціалізуйтеся на мистецтві гранування самоцвітів, отримуючи +$ev1 $en1 до всіх гранувань." },
    { en = "Specialize in the art of making accessories. Gain +$ev1 $en1 to all Jewelry designs per point in this specialization.", ua = "Спеціалізуйтеся на мистецтві виготовлення прикрас. Отримуйте +$ev1 $en1 до всіх ювелірних виробів за кожен вкладений у цю спеціалізацію бал." },
    { en = "Specialize in the art of synthesizing equipment, making the best enchanting rods and combat wands around with +$ev1 $en1 per point in this Specialization.", ua = "Спеціалізуйтеся на мистецтві синтезу спорядження, створюючи найкращі чарувальні палички та бойові жезли на світі з +$ev1 $en1 за кожен вкладений у цю спеціалізацію бал." },
    { en = "Specialize in the art of synthesizing usable equipment, making the best enchanting rods and combat wands around, gaining +$ev1 $en1 per point in this Specialization.", ua = "Спеціалізуйтеся на мистецтві синтезу придатного спорядження, створюючи найкращі чарувальні палички та бойові жезли на світі й отримуючи +$ev1 $en1 за кожен вкладений у цю спеціалізацію бал." },
    { en = "Specialize in the complexities of your own devices to use them with minimal risk to your own wellbeing, and maximum risk to the wellbeing of your foes.", ua = "Спеціалізуйтеся на тонкощах власних пристроїв, щоб застосовувати їх із мінімальним ризиком для власного добробуту й максимальним — для добробуту ворогів." },
    { en = "Specialize in the creation and usage of gadgets that offer convenience or entertainment, as well as Tinker modules to enhance your gear with new abilities.", ua = "Спеціалізуйтеся на створенні та використанні ґаджетів, що дарують зручність чи розвагу, а також модулів майстрування, які наділяють ваше спорядження новими здібностями." },
    { en = "Specialize in the creation and usage of intricate gizmos, gadgets, whirlygigs, and tinkers; but this knowledge is nonetheless invaluable to your growth as an Engineer. Gain +$ev1 $en1 to all Engineering crafts per point in this specialization.", ua = "Спеціалізуйтеся на створенні та використанні хитромудрих пристроїв, ґаджетів, вертушок і майструвань; це знання все ж безцінне для вашого зростання як інженера. Отримуйте +$ev1 $en1 до всіх виробів інженерії за кожен вкладений у цю спеціалізацію бал." },
    { en = "Specialize in the creation and use of bombs without safety fuses. Gain +$ev1 $en1 per point in this specialization for regular bomb crafts.", ua = "Спеціалізуйтеся на створенні та використанні бомб без запобіжних ґнотів. Отримуйте +$ev1 $en1 за кожен вкладений у цю спеціалізацію бал під час виготовлення звичайних бомб." },
    { en = "Specialize in the creation and use of explosives for yourself and safer ones to be used by others.", ua = "Спеціалізуйтеся на створенні та використанні вибухівки для себе й безпечніших її варіантів для інших." },
    { en = "Specialize in the creation of beautiful necklaces, gaining +$ev1 $en1 for necklace crafts per point in this specialization.", ua = "Спеціалізуйтеся на створенні прекрасних намист, отримуючи +$ev1 $en1 під час виготовлення намист за кожен вкладений у цю спеціалізацію бал." },
    { en = "Specialize in the creation of combat and profession equipment as well as items to customize them.", ua = "Спеціалізуйтеся на створенні бойового та професійного спорядження, а також предметів для його налаштування." },
    { en = "Specialize in the creation of devices of all sorts! Gain +$ev1 $en1 to gadgets, gizmos, devices, and other miscellaneous creations per point in this specialization.", ua = "Спеціалізуйтеся на створенні всіляких пристроїв! Отримуйте +$ev1 $en1 до ґаджетів, хитромудрих штук, пристроїв та інших різноманітних виробів за кожен вкладений у цю спеціалізацію бал." },
    { en = "Specialize in the creation of equipment used in all sorts of situations. Gain +$ev1 $en1 to your crafted equipment per point in this specialization.", ua = "Спеціалізуйтеся на створенні спорядження для всіляких ситуацій. Отримуйте +$ev1 $en1 до створеного вами спорядження за кожен вкладений у цю спеціалізацію бал." },
    { en = "Specialize in the creation of explosives! Gain +$ev1 $en1 to Explosives per point in this specialization.", ua = "Спеціалізуйтеся на створенні вибухівки! Отримуйте +$ev1 $en1 до вибухівки за кожен вкладений у цю спеціалізацію бал." },
    { en = "Specialize in the creation of luxurious rings, gaining +$ev1 $en1 for ring crafts per point in this specialization.", ua = "Спеціалізуйтеся на створенні розкішних перснів, отримуючи +$ev1 $en1 під час виготовлення перснів за кожен вкладений у цю спеціалізацію бал." },
    { en = "Specialize in the creation of practical items used by adventurers and craftsman in their everyday routines. Gain +$ev1 $en1 for all crafts related to equipment and their enhancements.", ua = "Спеціалізуйтеся на створенні практичних предметів, якими шукачі пригод і ремісники користуються щодня. Отримуйте +$ev1 $en1 до всіх виробів, пов'язаних зі спорядженням та його вдосконаленням." },
    { en = "Specialize in the creation of tinkers! Gain +$ev1 $en1 to Tinkers per point in this specialization.", ua = "Спеціалізуйтеся на створенні майструвань! Отримуйте +$ev1 $en1 до майструвань за кожен вкладений у цю спеціалізацію бал." },
    { en = "Specialize in the creation of trinkets, jewelry, and statues.", ua = "Спеціалізуйтеся на створенні дрібничок, прикрас і статуй." },
    { en = "Specialize in the cutting and polishing of specific Khaz Algar gemstones.", ua = "Спеціалізуйтеся на гранування та поліруванні певних самоцвітів Каз Алґара." },
    { en = "Specialize in the enchantments of the Arathi, drawing upon their reverence for the light and combat prowess. Gain +$ev1 $en1 per point in this Specialization while performing Arathi enchantments.", ua = "Спеціалізуйтеся на аратійських чарах, черпаючи з їхнього шанування Світла та бойової звитяги. Отримуйте +$ev1 $en1 за кожен вкладений у цю спеціалізацію бал під час накладання аратійських чарів." },
    { en = "Specialize in the energy imbued in threads around Khaz Algar to make powerful cloth gear and reagent items.", ua = "Спеціалізуйтеся на енергії, якою просякнуті нитки Каз Алґара, щоб виготовляти потужне тканинне спорядження та предмети-реагенти." },
    { en = "Specialize in the general precautions and techniques that are invaluable skills for all Engineers. Gain +$ev1 $en1 to all Engineering crafts per point in this specialization.", ua = "Спеціалізуйтеся на загальних застережних заходах і техніках, що є безцінними навичками для всіх інженерів. Отримуйте +$ev1 $en1 до всіх виробів інженерії за кожен вкладений у цю спеціалізацію бал." },
    { en = "Specialize in the generation of materials and gems, providing the reagents that you and other crafters need.", ua = "Спеціалізуйтеся на виробництві матеріалів і самоцвітів, постачаючи реагенти, потрібні вам та іншим ремісникам." },
    { en = "Specialize in the harvesting of deposits trapped in spindlespider webs found across Khaz Algar, gaining +$ev1 $en1 to these deposits per point in this specialization.", ua = "Спеціалізуйтеся на видобутку покладів, обплутаних павутинням веретенопавуків по всьому Каз Алґару, отримуючи +$ev1 $en1 до цих покладів за кожен вкладений у цю спеціалізацію бал." },
    { en = "Specialize in the peculiar Crystallized nodes found across Khaz Algar, gaining +$ev1 $en1 to these deposits per point in this specialization.", ua = "Спеціалізуйтеся на дивовижних кристалізованих покладах по всьому Каз Алґару, отримуючи +$ev1 $en1 до цих покладів за кожен вкладений у цю спеціалізацію бал." },
    { en = "Specialize in the peculiar EZ-Mine nodes found across Khaz Algar, gaining +$ev1 $en1 to these deposits per point in this specialization.", ua = "Спеціалізуйтеся на дивовижних покладах «Легкокоп» по всьому Каз Алґару, отримуючи +$ev1 $en1 до цих покладів за кожен вкладений у цю спеціалізацію бал." },
    { en = "Specialize in the peculiar Weeping nodes found across Khaz Algar, gaining +$ev1 $en1 to these deposits per point in this specialization.", ua = "Спеціалізуйтеся на дивовижних плакучих покладах по всьому Каз Алґару, отримуючи +$ev1 $en1 до цих покладів за кожен вкладений у цю спеціалізацію бал." },
    { en = "Specialize in the practice of cutting gems to improve the quality of your cuts and discover new designs.", ua = "Спеціалізуйтеся на гранування самоцвітів, щоб підвищити якість своїх гранувань і відкрити нові взірці." },
    { en = "Specialize in the production of EZ-Thro bombs which are expensive but far safer versions of your explosives for non-Engineers. Gain +$ev1 $en1 when crafting EZ-thro bombs per point in this specialization.", ua = "Спеціалізуйтеся на виготовленні бомб «З наведенням» — дорожчих, але значно безпечніших версій вашої вибухівки для не-інженерів. Отримуйте +$ev1 $en1 під час виготовлення бомб «З наведенням» за кожен вкладений у цю спеціалізацію бал." },
    { en = "Specialize in the sciences of destructive construction to improve your ability to invent new gadgets and your technique with Engineering generally.", ua = "Спеціалізуйтеся на науці руйнівного конструювання, щоб покращити свою здатність винаходити нові ґаджети та свою інженерну техніку загалом." },
    { en = "Specialize in the techniques necessary to become an expert at unraveling various pieces of cloth, weaving that cloth into bolts, and embroidering various items.", ua = "Спеціалізуйтеся на техніках, потрібних, щоб стати майстром розпускання різних клаптів тканини, ткання її в сувої та вишивання різних предметів." },
    { en = "Specialize in the techniques necessary to outfit adventurers in Silvermoon's latest fashion trends.", ua = "Спеціалізуйтеся на техніках, потрібних, щоб вбирати шукачів пригод за найновішою модою Сільвермуна." },
    { en = "Specialize in the understanding of Draconium to improve your ability to gather and refine this metal in various ways. Gain +$ev1 $en1 when mining all Draconium deposits per point in this specialization.", ua = "Спеціалізуйтеся на розумінні драконію, щоб покращити свою здатність збирати й переробляти цей метал у різний спосіб. Отримуйте +$ev1 $en1 під час видобутку всіх покладів драконію за кожен вкладений у цю спеціалізацію бал." },
    { en = "Specialize in the understanding of Serevite to improve your ability to gather and refine this metal in various ways. Gain +$ev1 $en1 when mining all Serevite deposits per point in this specialization.", ua = "Спеціалізуйтеся на розумінні серевіту, щоб покращити свою здатність збирати й переробляти цей метал у різний спосіб. Отримуйте +$ev1 $en1 під час видобутку всіх покладів серевіту за кожен вкладений у цю спеціалізацію бал." },
    { en = "Specialize in the writing of Missives, Contracts, and Treatises, as well as exploring the mysteries of Darkmoon Cards and Decks.", ua = "Спеціалізуйтеся на написанні Послань, Контрактів і Трактатів, а також на дослідженні таємниць Карт і Колод Темного Місяця." },
    { en = "Specialize in understanding the mysteries surrounding Darkmoon Cards and crafting Darkmoon Deck Boxes, gaining +$ev1 $en1 per point in this Specialization.", ua = "Спеціалізуйтеся на розумінні таємниць Карт Темного Місяця та виготовленні Скриньок колод Темного Місяця, отримуючи +$ev1 $en1 за кожен вкладений у цю спеціалізацію бал." },
    { en = "Specialize in unraveling cloth, weaving cloth into bolts, polishing cloths, banners, and bags.", ua = "Спеціалізуйтеся на розпусканні тканини, тканні її в сувої, а також на полірувальних ганчірках, стягах і сумках." },
    { en = "Specialize in working bolts and reagents with Arcanoweave. Gain +$ev1 $en1 while crafting bolts and reagents with Arcanoweave.", ua = "Спеціалізуйтеся на роботі із сувоями та реагентами з Арканного Плетива. Отримуйте +$ev1 $en1 під час виготовлення сувоїв і реагентів з Арканного Плетива." },
    { en = "Specialize in working bolts and reagents with Sunfire Silk.|n|nGain +$ev1 $en1 when crafting bolts and reagents with Sunfire Silk.", ua = "Спеціалізуйтеся на роботі із сувоями та реагентами з Шовку Сонячного Вогню.|n|nОтримуйте +$ev1 $en1 під час виготовлення сувоїв і реагентів з Шовку Сонячного Вогню." },
    { en = "Specialize into the art of crafting large chitin armor. You will become better at crafting chestguards, helms, shoulders, and bracers, gaining +$ev1 $en1 per point in this Specialization.", ua = "Спеціалізуйтеся на мистецтві виготовлення великої хітинової броні. Ви краще виготовлятимете нагрудники, шоломи, наплічники та наручі, отримуючи +$ev1 $en1 за кожен вкладений у цю спеціалізацію бал." },
    { en = "Specializing in Hardened deposits will allow you to acquire additional Rousing Earth and improve your efficiency in mining these deposits. Gain +$ev1 $en1 on Hardened deposits per point in this specialization.", ua = "Спеціалізація на затверділих покладах дасть вам змогу здобувати додаткову Бурхливу Землю та підвищить вашу ефективність у видобутку цих покладів. Отримуйте +$ev1 $en1 на затверділих покладах за кожен вкладений у цю спеціалізацію бал." },
    { en = "Specializing in Molten deposits will allow you to acquire additional Rousing Fire and improve your efficiency in mining these deposits. Gain +$ev1 $en1 on Molten deposits per point in this specialization.", ua = "Спеціалізація на розплавлених покладах дасть вам змогу здобувати додатковий Бурхливий Вогонь та підвищить вашу ефективність у видобутку цих покладів. Отримуйте +$ev1 $en1 на розплавлених покладах за кожен вкладений у цю спеціалізацію бал." },
    { en = "Specializing in Titan-Touched deposits allows you to discover gateways that allow you to traverse to nearby mining deposits quickly and gain additional essences when mining. Gain +$ev1 $en1 on Titan-Touched deposits per point in this specialization.", ua = "Спеціалізація на покладах, торкнутих титанами, дає вам змогу відкривати брами, крізь які можна швидко діставатися до сусідніх покладів руди, і здобувати додаткові есенції під час видобутку. Отримуйте +$ev1 $en1 на покладах, торкнутих титанами, за кожен вкладений у цю спеціалізацію бал." },
    { en = "Spend $ev1% less Concentration on Midnight Tailoring Recipes.", ua = "Витрачайте на $ev1% менше Зосередження на рецептах Кравецтва Опівночі." },
    { en = "Spend $ev1% less Concentration while crafting bolts and reagents with Arcanoweave.", ua = "Витрачайте на $ev1% менше Зосередження під час виготовлення сувоїв і реагентів з Арканного Плетива." },
    { en = "Spend $ev1% less Concentration while crafting bolts and reagents with Sunfire Silk.", ua = "Витрачайте на $ev1% менше Зосередження під час виготовлення сувоїв і реагентів з Шовку Сонячного Вогню." },
    { en = "Start down the road of Prospecting, learning a sub-specialization of your choice.", ua = "Ступіть на шлях розвідування руди, вивчивши підспеціалізацію на свій вибір." },
    { en = "Start the second half of your journey as a Lasting Leather armor crafter, learning the final sub-specialization.", ua = "Розпочніть другу половину свого шляху як майстер довговічної шкіряної броні, вивчивши останню підспеціалізацію." },
    { en = "Start the second half of your journey as a Safeguarding Scales armor crafter, learning the final sub-specialization.", ua = "Розпочніть другу половину свого шляху як майстер броні із захисної луски, вивчивши останню підспеціалізацію." },
    { en = "Start your journey in gemcutting by learning a sub-specialization of your choice.", ua = "Розпочніть свій шлях у гранування самоцвітів, вивчивши підспеціалізацію на свій вибір." },
    { en = "Start your studies of Amani Lapis by learning a sub-specialization of your choice. |n|nUnlock the ability to use Finishing Reagents when cutting Amani Lapises.", ua = "Розпочніть вивчення Лазуриту Амані, здобувши підспеціалізацію на свій вибір. |n|nВідкрийте змогу використовувати завершальні реагенти під час гранування Лазуриту Амані." },
    { en = "Start your studies of Harandar Peridot by learning a sub-specialization of your choice. |n|nUnlock the ability to use Finishing Reagents when cutting Harandar Peridots.", ua = "Розпочніть вивчення гарандарського перидоту, здобувши підспеціалізацію на свій вибір. |n|nВідкрийте змогу використовувати завершальні реагенти під час гранування гарандарського перидоту." },
    { en = "Start your studies of Sanguine Garnet by learning a sub-specialization of your choice. |n|nUnlock the ability to use Finishing Reagents when cutting Sanguine Garnets.", ua = "Розпочніть вивчення кривавого гранату, здобувши підспеціалізацію на свій вибір. |n|nВідкрийте змогу використовувати завершальні реагенти під час гранування кривавого гранату." },
    { en = "Start your studies of Tenebrous Amethyst by learning a sub-specialization of your choice. |n|nUnlock the ability to use Finishing Reagents when cutting Tenebrous Amethysts.", ua = "Розпочніть вивчення морочного аметисту, здобувши підспеціалізацію на свій вибір. |n|nВідкрийте змогу використовувати завершальні реагенти під час гранування морочного аметисту." },
    { en = "Steel your resolve at perfecting your Earthen Chest Armor enchantments, gaining +$ev1 $en1 per point in this Specialization.", ua = "Загартуйте свою рішучість в удосконаленні чарів для нагрудної броні земельників, отримуючи +$ev1 $en1 за кожен вкладений у цю спеціалізацію бал." },
    { en = "Strengthen your bond to the forge, improving your ability to craft multiple items. Gain +$ev1 $en1 while using Everburning Ignition per point in this sub-specialization.", ua = "Зміцніть свій зв'язок із кузнею, покращуючи здатність виготовляти кілька предметів одразу. Отримуйте +$ev1 $en1 під час використання «Вічнополум'яного Займання» за кожен вкладений у цю підспеціалізацію бал." },
    { en = "Strengthen your skills at handling spore-laden herbs on Khaz Algar, learning how to leverage their perception-altering properties more to your advantage. Gain +$ev1 $en1 per point in this specialization while gathering them.", ua = "Зміцніть свої навички поводження з насиченими спорами травами Каз Алґара, вчачись обертати їхні властивості, що змінюють сприйняття, більше собі на користь. Отримуйте +$ev1 $en1 за кожен вкладений у цю спеціалізацію бал під час їх збирання." },
    { en = "Study Arcanoweave even further. Gain +$ev1 $en1 while crafting Arcanoweave Bolts.", ua = "Вивчайте Арканне Плетиво ще глибше. Отримуйте +$ev1 $en1 під час виготовлення Сувоїв Арканного Плетива." },
    { en = "Study Sunfire Silk even further. Gain +$ev1 $en1 while crafting Sunfire Silk Bolts.", ua = "Вивчайте Шовк Сонячного Вогню ще глибше. Отримуйте +$ev1 $en1 під час виготовлення Сувоїв Шовку Сонячного Вогню." },
    { en = "Study a magical element in-depth, learning a sub-specialization of your choice.", ua = "Вивчіть магічний елемент досконало, здобувши підспеціалізацію на свій вибір." },
    { en = "Study effective gathering methods and techniques for the plants of the Dragon Isles, gaining +$ev1 $en1 per point in this specialization while gathering herbs.", ua = "Вивчайте ефективні методи й техніки збирання рослин Драконових Островів, отримуючи +$ev1 $en1 за кожен вкладений у цю спеціалізацію бал під час збирання трав." },
    { en = "Study how to handle the delicate Bubble Poppy, gaining +$ev1 $en1 per point in this specialization while gathering it.", ua = "Вивчіть, як поводитися з ніжним Бульбашковим Маком, отримуючи +$ev1 $en1 за кожен вкладений у цю спеціалізацію бал під час його збирання." },
    { en = "Study techniques to gather more materials from each creature, gaining +$ev1 $en1 while skinning per point in this Specialization.", ua = "Вивчайте техніки, щоб здобувати більше матеріалів з кожної істоти, отримуючи +$ev1 $en1 під час білування за кожен вкладений у цю спеціалізацію бал." },
    { en = "Study the anatomy of Saxifrage, gaining +$ev1 $en1 per point in this specialization while gathering it.", ua = "Вивчайте анатомію Ломикаменю, отримуючи +$ev1 $en1 за кожен вкладений у цю спеціалізацію бал під час його збирання." },
    { en = "Study the creatures of Khaz Algar and create new masterpieces based on what you see, gaining +$ev1 $en1 per point in this sub-specialization when crafting Beast items.", ua = "Вивчайте істот Каз Алґара й створюйте нові шедеври за побаченим, отримуючи +$ev1 $en1 за кожен вкладений у цю підспеціалізацію бал під час виготовлення предметів «Звір»." },
    { en = "Study the fundamentals of clothwork. Gain +$ev1 $en1 when crafting Midnight bolts.", ua = "Вивчайте основи роботи з тканиною. Отримуйте +$ev1 $en1 під час виготовлення Сувоїв Опівночі." },
    { en = "Study the intricacies of cultivating plantlife from the Midnight region, gaining +$ev1 $en1 per point in this specialization while gathering herbs.", ua = "Вивчайте тонкощі вирощування рослин регіону Опівночі, отримуючи +$ev1 $en1 за кожен бал у цій спеціалізації під час збору трав." },
    { en = "Study the intricacies of cultivating plantlife in Khaz Algar, gaining +$ev1 $en1 per point in this specialization while gathering herbs.", ua = "Вивчайте тонкощі вирощування рослин на Каз Алґарі, отримуючи +$ev1 $en1 за кожен бал у цій спеціалізації під час збору трав." },
    { en = "Study the intricacies of the awakening elements within the Dragon Isles and their effects on the plant life, gaining +$ev1 $en1 per point in this specialization while gathering elementally-charged herbs.", ua = "Вивчайте тонкощі пробудження стихій на Драконових Островах та їхній вплив на рослинність, отримуючи +$ev1 $en1 за кожен бал у цій спеціалізації під час збору насичених стихією трав." },
    { en = "Study the plantlife in the Midnight region, learning how to efficiently gather and grow them.", ua = "Вивчайте рослинність регіону Опівночі, дізнаючись, як ефективно збирати та вирощувати її." },
    { en = "Study the understanding of proper mining techniques to increase your efficiency in mining and allow for new mining opportunities. Gain +$ev1 $en1 per point in this specialization.", ua = "Опановуйте правильні техніки видобутку, щоб підвищити свою ефективність у видобуванні руди та відкрити нові можливості. Отримуйте +$ev1 $en1 за кожен бал у цій спеціалізації." },
    { en = "Study the various plantlife found on and around Khaz Algar and how to gather them.", ua = "Вивчайте розмаїту рослинність на Каз Алґарі та навколо нього, а також способи її збору." },
    { en = "Study the works of famed Sin'dorei alchemists, learning how to improve the potency of combat-enhancing flasks. Gain +$ev1 $en1 per point in this specialization while crafting Sin'dorei flasks.", ua = "Вивчайте праці уславлених алхіміків сін'дорей і дізнайтеся, як підвищити дієвість бойових фляг. Отримуйте +$ev1 $en1 за кожен бал у цій спеціалізації під час виготовлення фляг сін'дорей." },
    { en = "Stun the competition with your newfound skills working with Dazzling Diamonds, gaining +$ev1 $en1 when cutting them per point in this Specialization.", ua = "Вразіть конкурентів своїми новими навичками роботи зі Сліпучими Діамантами, отримуючи +$ev1 $en1 за їхнє огранювання за кожен бал у цій спеціалізації." },
    { en = "Successfully interrupting a manifestation cast grants you x min of their buff. A failed interrupt grants a buff at 33% effectiveness.", ua = "Успішне переривання закляття прояву дарує тобі x хв його підсилення. Невдале переривання дарує підсилення з 33% ефективністю." },
    { en = "Tailoring is $ev1% faster.|n|n+$ev2 $en2 and +$ev3 $en3 when making Tailoring goods.|n|nLearn the final sub-specialization.", ua = "Кравецтво на $ev1% швидше.|n|n+$ev2 $en2 і +$ev3 $en3 під час виготовлення кравецьких виробів.|n|nВивчіть останню підспеціалізацію." },
    { en = "Tailoring is $ev1% faster.|n|n+$ev2 $en2 and +$ev3 $en3 when making cloth armor.", ua = "Кравецтво на $ev1% швидше.|n|n+$ev2 $en2 і +$ev3 $en3 під час виготовлення тканинної броні." },
    { en = "Take inspiration from the mighty Keepers of the Grove to protect the balance and safeguard the Dream. Channel overwhelming natural power into your spells and summon enhanced treants to protect your allies and crush your enemies.", ua = "Надихайтеся могутніми Вартовими Гаю, щоб берегти рівновагу та захищати Сон. Спрямовуйте нездоланну силу природи у свої закляття й прикликайте посилених трієнтів, щоб захищати союзників і трощити ворогів." },
    { en = "Teaches you the recipe for the Elemental Focusing Lens optional reagent.", ua = "Навчає тебе рецепту необов'язкового реагенту «Стихійна фокусувальна лінза»." },
    { en = "Teaches you the recipe for the Prismatic Null Stone optional reagent.", ua = "Навчає тебе рецепту необов'язкового реагенту «Призматичний нуль-камінь»." },
    { en = "Templars are renowned Paladins of the Light's Hope Chapel. Their connection to the light through the chapel allows them to fully unleash their potential Holy powers by empowering their most powerful attacks to take them one step further.||n||nThey unleash devastating combinations of physical and holy attacks in quick succession that overwhelm their enemies. However, this is a controlled and metho", ua = "Темплари — прославлені паладини Каплиці Надії Світла. Зв'язок зі Світлом через каплицю дозволяє їм повністю розкрити потенціал Святої сили, посилюючи найпотужніші атаки й підносячи їх на новий рівень.||n||nВони обрушують нищівні поєднання фізичних і святих атак у швидкій послідовності, що приголомшують ворогів. Однак це контрольований і метод" },
    { en = "The Void whispers its secrets to you. Gain +$ev1 $en1 while crafting Void potions per point in this specialization.", ua = "Порожнеча нашіптує тобі свої таємниці. Отримуй +$ev1 $en1 під час виготовлення зіль Порожнечі за кожен бал у цій спеціалізації." },
    { en = "The amount of Overload cooldown refunded by gathering Altered herbs is increased by a large amount.", ua = "Обсяг перезарядження «Перевантаження», що повертається за збір змінених трав, значно збільшено." },
    { en = "The amount of Overload cooldown refunded by gathering Crystallized herbs is increased by a large amount.", ua = "Обсяг перезарядження «Перевантаження», що повертається за збір кристалізованих трав, значно збільшено." },
    { en = "The amount of Overload cooldown refunded by gathering Irradiated herbs is increased by a large amount.", ua = "Обсяг перезарядження «Перевантаження», що повертається за збір опромінених трав, значно збільшено." },
    { en = "The amount of Overload cooldown refunded by gathering Lightfused herbs is increased by a large amount.", ua = "Обсяг перезарядження «Перевантаження», що повертається за збір світлосплавлених трав, значно збільшено." },
    { en = "The amount of Overload cooldown refunded by gathering Primal herbs is increased by a large amount.", ua = "Обсяг перезарядження «Перевантаження», що повертається за збір первісних трав, значно збільшено." },
    { en = "The amount of Overload cooldown refunded by gathering Sporefused herbs is increased by a large amount.", ua = "Обсяг перезарядження «Перевантаження», що повертається за збір споросплавлених трав, значно збільшено." },
    { en = "The amount of Overload cooldown refunded by gathering Voidbound herbs is increased by a large amount.", ua = "Обсяг перезарядження «Перевантаження», що повертається за збір зв'язаних Порожнечею трав, значно збільшено." },
    { en = "The amount of Overload cooldown refunded by gathering Wild herbs is increased by a large amount.", ua = "Обсяг перезарядження «Перевантаження», що повертається за збір диких трав, значно збільшено." },
    { en = "The amount of Overload cooldown refunded by gathering herbs is increased by a small amount.", ua = "Обсяг перезарядження «Перевантаження», що повертається за збір трав, трохи збільшено." },
    { en = "The amount of cooldown refunded for your Elusive Creature Bait through skinning is doubled when skinning Elite and Rare creatures.", ua = "Обсяг перезарядження, що повертається за твою «Приманку для невловимих істот» через білування, подвоюється під час білування елітних і рідкісних істот." },
    { en = "The amount of cooldown refunded for your Elusive Creature Bait through skinning is increased by a moderate amount.", ua = "Обсяг перезарядження, що повертається за твою «Приманку для невловимих істот» через білування, помірно збільшено." },
    { en = "The amount of cooldown refunded for your Elusive Creature Bait through skinning is increased by a small amount.", ua = "Обсяг перезарядження, що повертається за твою «Приманку для невловимих істот» через білування, трохи збільшено." },
    { en = "The amount of cooldown refunded for your Elusive Creature Bait through skinning is increased.", ua = "Обсяг перезарядження, що повертається за твою «Приманку для невловимих істот» через білування, збільшено." },
    { en = "The cooldown of $@spellname423394 is reduced whenever you mine on Khaz Algar.|nTeaches you $@spellname423394 if you have not already learned it.", ua = "Час перезарядження $@spellname423394 зменшується щоразу, коли ти видобуваєш руду на Каз Алґарі.|nНавчає тебе $@spellname423394, якщо ти ще цього не вивчив." },
    { en = "The cooldown of $@spellname442615 recovers 15% faster.", ua = "Час перезарядження $@spellname442615 відновлюється на 15% швидше." },
    { en = "The cooldown of $@spellname442615 recovers 25% faster.", ua = "Час перезарядження $@spellname442615 відновлюється на 25% швидше." },
    { en = "The cooldown of your Wyrmhole Generator is reduced by 50%.", ua = "Час перезарядження твого Генератора вирмочервоточин зменшено на 50%." },
    { en = "The cooldown on creating gem hoards is reduced by 50%.", ua = "Час перезарядження створення запасів самоцвітів зменшено на 50%." },
    { en = "The cooldown reduction of $@spellname1225392 when mining is increased by 3%.", ua = "Зменшення часу перезарядження $@spellname1225392 під час видобутку збільшено на 3%." },
    { en = "The cooldown reduction of $@spellname1225392 when mining is increased by 3%. |n|nTeaches \"Overload Infused Deposit.\"", ua = "Зменшення часу перезарядження $@spellname1225392 під час видобутку збільшено на 3%. |n|nНавчає «Перевантаження насиченого покладу»." },
    { en = "The cooldown reduction of $@spellname423394 when mining is increased by 5%.", ua = "Зменшення часу перезарядження $@spellname423394 під час видобутку збільшено на 5%." },
    { en = "The duration of Wild Perception is doubled.", ua = "Тривалість «Дикого чуття» подвоєно." },
    { en = "The duration of flasks and phials is further increased.", ua = "Тривалість фляг і флаконів додатково збільшено." },
    { en = "The duration of flasks and phials is increased.", ua = "Тривалість фляг і флаконів збільшено." },
    { en = "The effectiveness of $@spellname433187 is increased by $ev1%.", ua = "Ефективність $@spellname433187 збільшено на $ev1%." },
    { en = "The effectiveness of $@spellname433188 is increased by $ev1%.", ua = "Ефективність $@spellname433188 збільшено на $ev1%." },
    { en = "The effectiveness of $@spellname433230 is increased by $ev1%.", ua = "Ефективність $@spellname433230 збільшено на $ev1%." },
    { en = "The first flask you craft per day has a chance to grant you a soulbound conjured version of it at maximum quality.", ua = "Перша фляга, яку ти виготовляєш за день, має шанс дарувати тобі прив'язану до душі прикликану її версію найвищої якості." },
    { en = "The first potion you craft per day will grant you $ev1 soulbound conjured copies at max quality.", ua = "Перше зілля, яке ти виготовляєш за день, дарує тобі $ev1 прив'язаних до душі прикликаних копій найвищої якості." },
    { en = "The heal granted by consuming Dragon Isles potions is increased.", ua = "Зцілення, яке дає вживання зіль Драконових Островів, збільшено." },
    { en = "The knockback explosion caused by gathering an Irradiated herb has less of an effect on you.", ua = "Вибух-відкидання, спричинений збором опроміненої трави, менше впливає на тебе." },
    { en = "The locals of Khaz Algar have caused herbs to evolve and change in unpredictable ways. Devoting yourself to the study of these unusual variants will allow you to get more from these special herbs while helping negate potential side effects, gaining +$ev1 $en1 when dealing with these specialized nodes.", ua = "Місцеві мешканці Каз Алґара спричинили те, що трави еволюціонують і змінюються непередбачувано. Присвятивши себе вивченню цих незвичних різновидів, ти зможеш отримувати більше з цих особливих трав, водночас послаблюючи можливі побічні ефекти, і отримаєш +$ev1 $en1 під час роботи з цими спеціалізованими вузлами." },
    { en = "The maximum amount of basic leather or scale you can gather from Renowned Beasts is increased.", ua = "Максимальна кількість базової шкіри чи луски, яку ти можеш зібрати з Уславлених звірів, збільшена." },
    { en = "The maximum amount of extra reagents you can yield from diffusers is increased.", ua = "Максимальна кількість додаткових реагентів, яку ти можеш отримати з дифузорів, збільшена." },
    { en = "The maximum amount of meat you can receive while using $@spellname1226037 is increased.", ua = "Максимальна кількість м'яса, яку ти можеш отримати під час використання $@spellname1226037, збільшена." },
    { en = "The maximum amount of species-specific materials you can gather from Renowned Beasts is increased.", ua = "Максимальна кількість матеріалів, характерних для виду, яку ти можеш зібрати з Уславлених звірів, збільшена." },
    { en = "The maximum amount of species-specific reagents you can receive from a single skinning attempt is increased.", ua = "Максимальна кількість реагентів, характерних для виду, яку ти можеш отримати за одну спробу білування, збільшена." },
    { en = "The maximum stacks of $@spellname433188 are doubled when crafting flasks.", ua = "Максимальна кількість зарядів $@spellname433188 подвоюється під час виготовлення фляг." },
    { en = "The maximum stacks of $@spellname433230 are doubled when crafting phials.", ua = "Максимальна кількість зарядів $@spellname433230 подвоюється під час виготовлення флаконів." },
    { en = "The minimum amount of basic leather or scale you can gather from Renowned Beasts is increased.", ua = "Мінімальна кількість базової шкіри чи луски, яку ти можеш зібрати з Уславлених звірів, збільшена." },
    { en = "The minimum amount of extra reagents you can yield from diffusers is increased.", ua = "Мінімальна кількість додаткових реагентів, яку ти можеш отримати з дифузорів, збільшена." },
    { en = "The minimum amount of meat you receive while using $@spellname1226037 is increased.", ua = "Мінімальна кількість м'яса, яку ти отримуєш під час використання $@spellname1226037, збільшена." },
    { en = "The minimum amount of species-specific reagents you can receive from a single skinning attempt is increased.", ua = "Мінімальна кількість реагентів, характерних для виду, яку ти можеш отримати за одну спробу білування, збільшена." },
    { en = "The movement speed granted by consuming Dragon Isles potions is increased.", ua = "Швидкість пересування, яку дає вживання зіль Драконових Островів, збільшено." },
    { en = "The number of Motes of Light you can catch after gathering a Lightfused herb is increased.", ua = "Кількість Частинок Світла, які ти можеш упіймати після збору світлосплавленої трави, збільшена." },
    { en = "The number of Motes of Light you can catch when gathering a Lightfused deposit is increased.", ua = "Кількість Частинок Світла, які ти можеш упіймати під час збору світлосплавленого покладу, збільшена." },
    { en = "The plant creatures of the Dragon Isles sometimes absorb the elements of the land. When gathering from these creatures, you have a chance to gather these elements from them.", ua = "Рослинні істоти Драконових Островів іноді вбирають стихії землі. Збираючи з цих істот, ти маєш шанс зібрати з них ці стихії." },
    { en = "Train deeply in a specific Bolstered Bulwarks armor piece, learning a sub-specialization of your choice.", ua = "Ретельно тренуйся з певним елементом обладунку «Зміцнені бастіони», вивчаючи підспеціалізацію на свій вибір." },
    { en = "Train in the art of armorsmithing. |n|nGain +$ev1 $en1 when crafting armor and shields for each Knowledge point in this specialization.", ua = "Тренуйся в мистецтві ковки обладунків. |n|nОтримуй +$ev1 $en1 під час виготовлення обладунків і щитів за кожен бал знань у цій спеціалізації." },
    { en = "Train in the art of crafting Articulating Armor. |n|nGain +$ev1 $en1 to crafting waist, wrist, and hand armor for each Knowledge point in this specialization.", ua = "Тренуйся в мистецтві виготовлення «Рухомих обладунків». |n|nОтримуй +$ev1 $en1 до виготовлення обладунків для пояса, зап'ясть і кистей за кожен бал знань у цій спеціалізації." },
    { en = "Train in the art of crafting Large Plate armor. |n|nGain +$ev1 $en1 when crafting chest armor, leg armor, and shields for each Knowledge point in this specialization.", ua = "Тренуйся в мистецтві виготовлення «Великих латних обладунків». |n|nОтримуй +$ev1 $en1 під час виготовлення нагрудних, ножних обладунків і щитів за кожен бал знань у цій спеціалізації." },
    { en = "Train in the art of crafting Sculpted armor.|n|nGain +$ev1 $en1 to crafting head, shoulder, and foot armor for each Knowledge point in this specialization.", ua = "Тренуйся в мистецтві виготовлення «Різьблених обладунків».|n|nОтримуй +$ev1 $en1 до виготовлення обладунків для голови, плечей і стоп за кожен бал знань у цій спеціалізації." },
    { en = "Train in the art of crafting edged weapons. |n|nGain +$ev1 $en1 when crafting edged weapons for each point of Knowledge spent in this specialization.", ua = "Тренуйся в мистецтві виготовлення клинкової зброї. |n|nОтримуй +$ev1 $en1 під час виготовлення клинкової зброї за кожен витрачений бал знань у цій спеціалізації." },
    { en = "Train in the art of crafting hafted weapons such as maces, axes, and polearms. |n|nGain +$ev1 $en1 to crafting hafted weapons for each point of Knowledge spent in this specialization.", ua = "Тренуйся в мистецтві виготовлення держакової зброї, як-от булав, сокир і древкової зброї. |n|nОтримуй +$ev1 $en1 до виготовлення держакової зброї за кожен витрачений бал знань у цій спеціалізації." },
    { en = "Train in the art of weaponsmithing. |n|nGain +$ev1 $en1 when crafting weapons, whetstones, and weightstones for each point of Knowledge put into this specialization.", ua = "Тренуйся в мистецтві ковки зброї. |n|nОтримуй +$ev1 $en1 під час виготовлення зброї, точильних каменів і каменів-тягарців за кожен вкладений бал знань у цій спеціалізації." },
    { en = "Train your skills in Harvesting, gaining +$ev1 $en1 while skinning in Khaz Algar per point in this Specialization.", ua = "Тренуй свої навички Збирання, отримуючи +$ev1 $en1 під час білування на Каз Алґарі за кожен бал у цій спеціалізації." },
    { en = "Train yourself in the science of magical matrices that help permanently improve various pieces of equipment, gaining +$ev1 $en1 per point in this Specialization.", ua = "Опануй науку магічних матриць, що допомагають назавжди покращувати різні предмети спорядження, отримуючи +$ev1 $en1 за кожен бал у цій спеціалізації." },
    { en = "Transmutations now also grant Gleaming Transmutagen.", ua = "Трансмутації тепер також дають Мерехтливий трансмутаген." },
    { en = "Transmute your experience into a higher chance to have an Ingenious Breakthrough! Gain +$ev1 $en1 while Transmuting Midnight reagents per point in this specialization.", ua = "Перетвори свій досвід на вищий шанс здійснити Геніальний прорив! Отримуй +$ev1 $en1 під час трансмутації реагентів Опівночі за кожен бал у цій спеціалізації." },
    { en = "Treatises craft $ev1% faster.|n|n+$ev2 $en2 when making Treatises.", ua = "Трактати виготовляються на $ev1% швидше.|n|n+$ev2 $en2 під час виготовлення трактатів." },
    { en = "Turn one reagent into another!", ua = "Перетвори один реагент на інший!" },
    { en = "Understand the patterns and intricacies of Refulgent Copper, learning how to spot Eversong Diamonds hiding within while prospecting it.", ua = "Осягни закономірності й тонкощі Сяйливої міді, навчаючись помічати приховані всередині Діаманти Вічної Пісні під час її розвідування." },
    { en = "Unlock Finishing Reagents when crafting hafted weapons.", ua = "Розблокуй завершальні реагенти при виготовленні держакової зброї." },
    { en = "Unlock a sub-specialization and gain +$ev1 $en1 when milling or crafting reagents.", ua = "Розблокуй підспеціалізацію та отримай +$ev1 $en1 під час подрібнення чи виготовлення реагентів." },
    { en = "Unlock a sub-specialization of your choice.", ua = "Розблокуй підспеціалізацію на твій вибір." },
    { en = "Unlock a sub-specialization.", ua = "Розблокуй підспеціалізацію." },
    { en = "Unlock the Finishing Reagent slot for transmutations.", ua = "Розблокуй комірку завершального реагенту для трансмутацій." },
    { en = "Unlock the Finishing Reagent slot for your bits and bots.", ua = "Розблокуй комірку завершального реагенту для твоїх деталей і ботів." },
    { en = "Unlock the Finishing Reagent slot when crafting Armor Kits and Reagents.", ua = "Розблокуй комірку завершального реагенту при виготовленні наборів для броні та реагентів." },
    { en = "Unlock the Finishing Reagent slot when crafting alchemy equipment.|n|n+$ev1 $en1 when crafting alchemy equipment.", ua = "Розблокуй комірку завершального реагенту при виготовленні алхімічного спорядження.|n|n+$ev1 $en1 при виготовленні алхімічного спорядження." },
    { en = "Unlock the Finishing Reagent slot when crafting bows. |n|n+$ev1 $en1 when crafting bows.", ua = "Розблокуй комірку завершального реагенту при виготовленні луків. |n|n+$ev1 $en1 при виготовленні луків." },
    { en = "Unlock the Finishing Reagent slot when crafting codexes. |n|nGain +$ev1 $en1 when crafting codexes.", ua = "Розблокуй комірку завершального реагенту при виготовленні кодексів. |n|nОтримай +$ev1 $en1 при виготовленні кодексів." },
    { en = "Unlock the Finishing Reagent slot when crafting cooking equipment.|n|n+$ev1 $en1 when crafting cooking equipment.", ua = "Розблокуй комірку завершального реагенту при виготовленні кулінарного спорядження.|n|n+$ev1 $en1 при виготовленні кулінарного спорядження." },
    { en = "Unlock the Finishing Reagent slot when crafting inscription equipment.|n|n+$ev1 $en1 when crafting inscription equipment.", ua = "Розблокуй комірку завершального реагенту при виготовленні спорядження накреслення.|n|n+$ev1 $en1 при виготовленні спорядження накреслення." },
    { en = "Unlock the Finishing Reagent slot when crafting staves. |n|n+$ev1 $en1 when crafting staves.", ua = "Розблокуй комірку завершального реагенту при виготовленні посохів. |n|n+$ev1 $en1 при виготовленні посохів." },
    { en = "Unlock the Infuse with Power and Embellishment slot when crafting weapons. |n|nUnlock a sub-specialization of your choice.", ua = "Розблокуй комірки «Наповнення силою» та «Оздоблення» при виготовленні зброї. |n|nРозблокуй підспеціалізацію на твій вибір." },
    { en = "Unlock the Missive slot when crafting carvable equipment. |n|nUnlock a sub-specialization of your choice.", ua = "Розблокуй комірку послання при виготовленні різьблюваного спорядження. |n|nРозблокуй підспеціалізацію на твій вибір." },
    { en = "Unlock the ability to add Finishing Reagents when crafting Darkmoon Sigils and learn a sub-specialization of your choice.", ua = "Розблокуй можливість додавати завершальні реагенти при виготовленні Печаток Темного Місяця та вивчи підспеціалізацію на твій вибір." },
    { en = "Unlock the ability to use Finishing Reagents when crafting whetstones and weightstones.", ua = "Розблокуй можливість використовувати завершальні реагенти при виготовленні точильних та обважнювальних каменів." },
    { en = "Unlock the ability to use Spare Parts on equipment.", ua = "Розблокуй можливість використовувати запчастини на спорядженні." },
    { en = "Unlock the final sub-specialization and gain +$ev1 $en1 when milling or crafting reagents.", ua = "Розблокуй фінальну підспеціалізацію та отримай +$ev1 $en1 під час подрібнення чи виготовлення реагентів." },
    { en = "Unlock the final sub-specialization.", ua = "Розблокуй фінальну підспеціалізацію." },
    { en = "Unlock the final sub-specialization.|n|n+$ev2 $en2 and +$ev3 $en3 when making Inscription goods.|n|nLearn to use special Finishing Reagents to improve the crafting quality of your Inks and Runes.", ua = "Розблокуй фінальну підспеціалізацію.|n|n+$ev2 $en2 та +$ev3 $en3 при виготовленні виробів накреслення.|n|nНавчись використовувати особливі завершальні реагенти, щоб покращувати якість виготовлення твоїх чорнил і рун." },
    { en = "Unlock the secrets of the Everburning Forge, significantly improving your Blacksmithing capabilities while active.", ua = "Розкрий таємниці Вічнопломінної Кузні, що значно покращує твої ковальські вміння, поки активна." },
    { en = "Unlock the use of Optional Reagents for customizing secondary stats and adding embellishments to Articulating Armor.|n|nUnlock a sub-specialization of your choice.", ua = "Розблокуй використання необов'язкових реагентів для налаштування вторинних характеристик і додавання оздоблень до Зчленованої броні.|n|nРозблокуй підспеціалізацію на твій вибір." },
    { en = "Unlock the use of Optional Reagents for customizing secondary stats and adding embellishments to Large Plate Armor. |n|nUnlock a sub-specialization of your choice.", ua = "Розблокуй використання необов'язкових реагентів для налаштування вторинних характеристик і додавання оздоблень до Великої латної броні. |n|nРозблокуй підспеціалізацію на твій вибір." },
    { en = "Unlock the use of Optional Reagents for customizing secondary stats and adding embellishments to Sculpted Armor.|n|nUnlock a sub-specialization of your choice.", ua = "Розблокуй використання необов'язкових реагентів для налаштування вторинних характеристик і додавання оздоблень до Формованої броні.|n|nРозблокуй підспеціалізацію на твій вибір." },
    { en = "Unlock the use of optional reagents for crafting plate armor with superior item levels.|n|nUnlock a sub-specialization of your choice.", ua = "Розблокуй використання необов'язкових реагентів для виготовлення латної броні з вищими рівнями предметів.|n|nРозблокуй підспеціалізацію на твій вибір." },
    { en = "Unlock the use of optional reagents for customizing secondary stats and adding embellishments to Blades.|n|nLearn the recipe for $@spellname1229657.", ua = "Розблокуй використання необов'язкових реагентів для налаштування вторинних характеристик і додавання оздоблень до клинків.|n|nВивчи рецепт $@spellname1229657." },
    { en = "Unlock the use of optional reagents for customizing secondary stats and adding embellishments to Hafted Weapons.", ua = "Розблокуй використання необов'язкових реагентів для налаштування вторинних характеристик і додавання оздоблень до держакової зброї." },
    { en = "Unlock use of Finishing Reagents that add additional effects when crafting chest armor, leg armor, and shields.", ua = "Розблокуй використання завершальних реагентів, що додають додаткові ефекти при виготовленні нагрудної броні, броні для ніг і щитів." },
    { en = "Unlock use of Finishing Reagents that add additional effects when crafting head, shoulder, and foot armor.", ua = "Розблокуй використання завершальних реагентів, що додають додаткові ефекти при виготовленні броні для голови, плечей і стоп." },
    { en = "Unlock use of Finishing Reagents that add additional effects when crafting waist, wrist, and hand armor.", ua = "Розблокуй використання завершальних реагентів, що додають додаткові ефекти при виготовленні броні для пояса, зап'ясть і кистей." },
    { en = "Unlocks the ability to use Optional Reagents when crafting Profession Accessories.|n|nUnlocks the ability to use Finishing Reagents when crafting Profession Accessories.", ua = "Розблокує можливість використовувати необов'язкові реагенти при виготовленні професійних аксесуарів.|n|nРозблокує можливість використовувати завершальні реагенти при виготовленні професійних аксесуарів." },
    { en = "Unravel thread imbued with Dawn's light in your tailoring, gaining +$ev1 $en1 per point in this specialization when making and using Dawnweave.", ua = "Розплітай нитку, просякнуту світлом Світанку, у своєму кравецтві, отримуючи +$ev1 $en1 за кожен бал у цій спеціалізації при виготовленні й використанні Світанкоплетива." },
    { en = "Unravel thread imbued with Dawn's light in your tailoring, gaining +$ev1 $en1 per point in this specialization when making and using Duskweave.", ua = "Розплітай нитку, просякнуту світлом Світанку, у своєму кравецтві, отримуючи +$ev1 $en1 за кожен бал у цій спеціалізації при виготовленні й використанні Сутінкоплетива." },
    { en = "Unravel thread imbued with Dawn's light in your tailoring, gaining +$ev1 +$en1 Crafting Skill per point in this specialization when making and using Dawnweave.", ua = "Розплітай нитку, просякнуту світлом Світанку, у своєму кравецтві, отримуючи +$ev1 +$en1 Навику виготовлення за кожен бал у цій спеціалізації при виготовленні й використанні Світанкоплетива." },
    { en = "Unravel thread imbued with Dawn's light in your tailoring, gaining +$ev1 +$en1 Crafting Skill per point in this specialization when making and using Duskweave.", ua = "Розплітай нитку, просякнуту світлом Світанку, у своєму кравецтві, отримуючи +$ev1 +$en1 Навику виготовлення за кожен бал у цій спеціалізації при виготовленні й використанні Сутінкоплетива." },
    { en = "Use $ev1% less Concentration when Concentrating on Khaz Algar Enchanting recipes.", ua = "Використовуй на $ev1% менше Зосередження, зосереджуючись на рецептах Накладання чарів Каз Алґару." },
    { en = "Use reagents more economically, gaining +$ev1 $en1 per point in this Specialization.", ua = "Використовуй реагенти економніше, отримуючи +$ev1 $en1 за кожен бал у цій спеціалізації." },
    { en = "Use your materials sparingly, gaining +$ev1 $en1 per point in this Specialization.", ua = "Ощадливо витрачай матеріали, отримуючи +$ev1 $en1 за кожен бал у цій спеціалізації." },
    { en = "Using Explosives has a chance to grant scrap.", ua = "Використання вибухівки має шанс дати брухт." },
    { en = "Using Tinkers has a chance to grant scrap.", ua = "Використання винаходів має шанс дати брухт." },
    { en = "Using a suspicious technique, you have a chance to not consume a potion bomb when throwing them.", ua = "Завдяки підозрілій техніці ти маєш шанс не витратити бомбу-зілля, коли її кидаєш." },
    { en = "Using tinkers or throwing bombs has a small chance to recover additional scrap.", ua = "Використання винаходів чи кидання бомб має невеликий шанс повернути додатковий брухт." },
    { en = "Vantus runes craft $ev1% faster.|n|n+$ev2 $en2 when making Vantus Runes.", ua = "Руни Вантуса виготовляються на $ev1% швидше.|n|n+$ev2 $en2 при виготовленні рун Вантуса." },
    { en = "Vantus runes craft $ev1% faster.|n|nLearn to craft and use the $@spellname391781 Finishing Reagent to improve Skill when crafting Vantus Runes.", ua = "Руни Вантуса виготовляються на $ev1% швидше.|n|nНавчись виготовляти й використовувати завершальний реагент $@spellname391781, щоб покращити навик при виготовленні рун Вантуса." },
    { en = "Verse yourself in the values of Versatile Amethysts, gaining +$ev1 $en1 when cutting them per point in this Specialization.", ua = "Осягни властивості Універсальних аметистів, отримуючи +$ev1 $en1 при їх огранюванні за кожен бал у цій спеціалізації." },
    { en = "Verse yourself in the values of Versatile Garnets, gaining +$ev1 $en1 when cutting them per point in this Specialization.", ua = "Осягни властивості Універсальних гранатів, отримуючи +$ev1 $en1 при їх огранюванні за кожен бал у цій спеціалізації." },
    { en = "Verse yourself in the values of Versatile Peridots, gaining +$ev1 $en1 when cutting them per point in this Specialization.", ua = "Осягни властивості Універсальних перидотів, отримуючи +$ev1 $en1 при їх огранюванні за кожен бал у цій спеціалізації." },
    { en = "Walk the path of Light, learning how to craft stable and reliable potions to heighten your potential. Gain +$ev1 $en1 while crafting Light Potions per point in this specialization.", ua = "Іди шляхом Світла, навчаючись виготовляти стабільні й надійні зілля, щоб розкрити свій потенціал. Отримуй +$ev1 $en1 під час виготовлення зілля Світла за кожен бал у цій спеціалізації." },
    { en = "Walk the path of Void, learning how to craft stable and reliable potions to heighten your potential. Gain +$ev1 $en1 while crafting Void Potions per point in this specialization.", ua = "Іди шляхом Порожнечі, навчаючись виготовляти стабільні й надійні зілля, щоб розкрити свій потенціал. Отримуй +$ev1 $en1 під час виготовлення зілля Порожнечі за кожен бал у цій спеціалізації." },
    { en = "Weapon Crafting is $ev1% faster.|n|n+$ev2 $en2 and +$ev3 $en3 when making weapons and large tools.", ua = "Виготовлення зброї на $ev1% швидше.|n|n+$ev2 $en2 та +$ev3 $en3 при виготовленні зброї та великих інструментів." },
    { en = "When Hammer of Wrath critically strikes, it calls down an Empyrean Hammer on the target and bounces to a nearby enemy up to 3 times.", ua = "Коли Молот гніву завдає критичного удару, він накликає Небесний молот на ціль і відскакує до найближчого ворога до 3 разів." },
    { en = "When Rexxar leaves, Misha will appear to aid you for a little longer.", ua = "Коли Рекссар піде, Міша з'явиться, щоб допомагати тобі ще трохи довше." },
    { en = "When affected by Decay, dealing damage has a chance to apply a damaging affliction to your target that also slows their casting, attack, and movement speed for a short time.", ua = "Коли ти під дією Гнилі, завдання шкоди має шанс накласти на ціль шкідливу недугу, що також ненадовго сповільнює її швидкість творення заклять, атаки та пересування." },
    { en = "When you $@spellname447311, you now have a chance to recover components used to craft the Crowd Pummeler 2-30.", ua = "Коли ти $@spellname447311, ти тепер маєш шанс повернути компоненти, використані для виготовлення Товкача Натовпу 2-30." },
    { en = "When you Overload a Lightfuseded herb, more Motes of Light will be released for you to catch.", ua = "Коли ти застосовуєш Перевантаження до світлозлитої трави, вивільняється більше Частинок Світла, які ти можеш зловити." },
    { en = "Whenever you $@spellname447312, gain $@spellname452519 which increases Multicraft, Resourcefulness, and Ingenuity by $ev1 for $ev2 hours.", ua = "Щоразу, коли ви $@spellname447312, отримуєте $@spellname452519, що збільшує Багатовиробництво, Винахідливість і Кмітливість на $ev1 протягом $ev2 годин." },
    { en = "Whenever you $@spellname447312, you may acquire Hastily Scribbled Notes, Piles of Rusted Scrap, and spare parts to put towards other inventions.", ua = "Щоразу, коли ви $@spellname447312, ви можете здобути Похапцем Нашкрябані Нотатки, Купи Іржавого Брухту та запчастини для інших винаходів." },
    { en = "Whenever you Overload, you also gain a random rousing essence.", ua = "Щоразу, коли ти застосовуєш Перевантаження, ти також отримуєш випадкову бентежну есенцію." },
    { en = "Whenever you achieve a major breakthrough in Phial Experimentation, gain +20 Ingenuity for 4 hours for all Alchemy crafts.", ua = "Щоразу, коли ти досягаєш великого прориву в Експериментуванні з флаконами, отримуй +20 Кмітливості на 4 години для всіх виробів Алхімії." },
    { en = "Whenever you achieve a major breakthrough in Potion Experimentation, gain +20 Ingenuity for 4 hours for all Alchemy crafts.", ua = "Щоразу, коли ти досягаєш великого прориву в Експериментуванні із зіллям, отримуй +20 Кмітливості на 4 години для всіх виробів Алхімії." },
    { en = "Whenever you consume a flask or phial, you have a chance to retain the empty vial.", ua = "Щоразу, коли ти вживаєш флягу чи флакон, ти маєш шанс зберегти порожню пляшечку." },
    { en = "Whenever you consume a potion, you have a chance to retain the empty vial.", ua = "Щоразу, коли ти вживаєш зілля, ти маєш шанс зберегти порожню пляшечку." },
    { en = "Whenever you craft $@spellname382378, you have a chance to devise schematics for cogwheels. These can be used when crafting epic goggles to allocate its secondary stat to one of your choosing.", ua = "Щоразу, коли ви виготовляєте $@spellname382378, є шанс розробити схеми для шестерень. Їх можна використати під час виготовлення епічних окулярів, щоб призначити їхню вторинну характеристику на власний вибір." },
    { en = "Whenever you craft Fireflights, you also immediately set one off for free.", ua = "Щоразу, коли ти виготовляєш Вогнельоти, ти також одразу безкоштовно запускаєш один із них." },
    { en = "Whenever you craft a regular bomb, you have a small chance to also create an EZ-Thro variant of the same bomb at Quality 1 if you know its schematic.", ua = "Щоразу, коли ти виготовляєш звичайну бомбу, ти маєш невеликий шанс також створити EZ-Thro-варіант тієї ж бомби якості 1, якщо знаєш її схему." },
    { en = "Whenever you craft bombs, you have a chance to devise a schematic for an EZ-Thro variant of that bomb, if such a device is possible.|n|nYou may now create $@spellname382345 which is a crucial component for these EZ-Thro bombs.", ua = "Щоразу, коли ти виготовляєш бомби, ти маєш шанс розробити схему EZ-Thro-варіанта тієї бомби, якщо такий пристрій можливий.|n|nТепер ти можеш створювати $@spellname382345, що є важливим компонентом для цих EZ-Thro-бомб." },
    { en = "Whenever you craft combat equipment, you have a chance to devise schematics for epic bracers usable by anyone. These bracers come equipped with a Tinker socket.", ua = "Щоразу, коли ви виготовляєте бойове спорядження, є шанс розробити схеми епічних наручів, придатних для будь-кого. Ці наручі оснащені гніздом для тінкера." },
    { en = "Whenever you craft flasks, gain $@spellname433188. $@spellname433188 grants +$ev3 Resourcefulness, Multicraft, and Ingenuity for subsequent crafts within $ev1 min, stacking up to $ev2 times.", ua = "Щоразу, коли ви виготовляєте флакони, отримуєте $@spellname433188. $@spellname433188 надає +$ev3 до Винахідливості, Багатовиробництва та Кмітливості для наступних виготовлень протягом $ev1 хв, накопичуючись до $ev2 разів." },
    { en = "Whenever you craft phials, gain $@spellname433230. $@spellname433230 grants +$ev3 Resourcefulness, Multicraft, and Ingenuity for subsequent crafts within $ev1 min, stacking up to $ev2 times.", ua = "Щоразу, коли ви виготовляєте фіали, отримуєте $@spellname433230. $@spellname433230 надає +$ev3 до Винахідливості, Багатовиробництва та Кмітливості для наступних виготовлень протягом $ev1 хв, накопичуючись до $ev2 разів." },
    { en = "Whenever you craft potions, gain $@spellname433187 which grants +$ev3 Resourcefulness, Multicraft, and Ingenuity for subsequent potion crafts within $ev1 minutes, stacking up to $ev2 times.", ua = "Щоразу, коли ви виготовляєте зілля, отримуєте $@spellname433187, що надає +$ev3 до Винахідливості, Багатовиробництва та Кмітливості для наступних виготовлень зілля протягом $ev1 хвилин, накопичуючись до $ev2 разів." },
    { en = "Whenever you craft profession equipment for other professions, you may impulsively remove a few \"unnecessary\" parts in the form of scrap. None will be the wiser.", ua = "Щоразу, коли ви виготовляєте професійне спорядження для інших професій, ви можете імпульсивно вилучити кілька «непотрібних» деталей у вигляді брухту. Ніхто й не здогадається." },
    { en = "Whenever you create a basic Engineering part, you have a small chance to receive a random Rousing Element.", ua = "Щоразу, коли ви створюєте базову деталь Інженерії, є невеликий шанс отримати випадковий Пробудний Елемент." },
    { en = "Whenever you cut Extravagant Emeralds, you may retain some of the spent shards as a Finishing Reagent to increase Skill on a future gem cut.", ua = "Щоразу, коли ви огранюєте Екстравагантні Смарагди, ви можете зберегти частину витрачених уламків як завершальний реагент, щоб підвищити Уміння під час майбутнього огранювання самоцвіту." },
    { en = "Whenever you cut Ostentatious Onyxes, you may retain some of the spent shards as a Finishing Reagent to increase Skill on a future gem cut.", ua = "Щоразу, коли ви огранюєте Показні Онікси, ви можете зберегти частину витрачених уламків як завершальний реагент, щоб підвищити Уміння під час майбутнього огранювання самоцвіту." },
    { en = "Whenever you cut Radiant Rubies, you may retain some of the spent shards as a Finishing Reagent to increase Skill on a future gem cut.", ua = "Щоразу, коли ви огранюєте Промінисті Рубіни, ви можете зберегти частину витрачених уламків як завершальний реагент, щоб підвищити Уміння під час майбутнього огранювання самоцвіту." },
    { en = "Whenever you cut Stunning Sapphires, you may retain some of the spent shards as a Finishing Reagent to increase Skill on a future gem cut.", ua = "Щоразу, коли ви огранюєте Приголомшливі Сапфіри, ви можете зберегти частину витрачених уламків як завершальний реагент, щоб підвищити Уміння під час майбутнього огранювання самоцвіту." },
    { en = "Whenever you gather herbs native to the Dragon Isles, the cooldown of your $@spellname390392 ability is significantly reduced.|n|nLearn the $@spellname390392 ability if it is not known already.", ua = "Щоразу, коли ви збираєте трави, рідні для Драконових Островів, перезарядження вашої здібності $@spellname390392 значно скорочується.|n|nВивчіть здібність $@spellname390392, якщо вона ще не відома." },
    { en = "Whenever you mine a Rich deposit, there is a chance to dislodge a chunk of rock that can be mined for additional ore.", ua = "Щоразу, коли ви розробляєте Багате родовище, є шанс відколоти брилу породи, яку можна розробити задля додаткової руди." },
    { en = "Whenever you mine a Seam, there is a chance to dislodge a chunk of rock that can be mined for additional ore.", ua = "Щоразу, коли ви розробляєте Жилу, є шанс відколоти брилу породи, яку можна розробити задля додаткової руди." },
    { en = "Whenever you mine in Khaz Algar, you restore 1 Vigor.", ua = "Щоразу, коли ви видобуваєте руду в Каз Алґарі, ви відновлюєте 1 Снагу." },
    { en = "Whenever you mine ore native to the Dragon Isles, the cooldown of your $@spellname388213 ability is significantly reduced.|n|nLearn the $@spellname388213 ability if it is not known already.", ua = "Щоразу, коли ви видобуваєте руду, рідну для Драконових Островів, перезарядження вашої здібності $@spellname388213 значно скорочується.|n|nВивчіть здібність $@spellname388213, якщо вона ще не відома." },
    { en = "Whenever you use your tinkers or throw bombs, you have a chance of recovering a Piece of Scrap. You can $@spellname382374 to uncover junk components that can be peddled off to uninformed buyers.", ua = "Щоразу, коли ви застосовуєте свої тінкери або кидаєте бомби, є шанс отримати Шматок Брухту. Ви можете $@spellname382374, щоб виявити непотрібні компоненти, які можна збути необізнаним покупцям." },
    { en = "Whether you need a pick-me-up, or to put your enemies down, Bits and Bots is here to help. Create and improve upon interesting gadgets, gizmos, and all the bits in between through the power of science!", ua = "Байдуже, чи потрібне вам підбадьорення, чи здолати ворогів, — «Деталі та Боти» допоможе. Створюйте й вдосконалюйте цікаві гаджети, пристрої та всі дрібнички поміж ними завдяки силі науки!" },
    { en = "Will the Light to coalesce and become manifest as a Holy Armament, wielded by your friendly target.|n|n$@spellicon432496 $@spellname432496: $@spelldesc432496|n|n$@spellicon432502 $@spellname432502: $@spelldesc432502", ua = "Змусьте Світло згуртуватися й проявитися як Свята Зброя, якою володітиме ваша дружня ціль.|n|n$@spellicon432496 $@spellname432496: $@spelldesc432496|n|n$@spellicon432502 $@spellname432502: $@spelldesc432502" },
    { en = "Windswept herbs grant you slowfall the next time you fall further than 40 yds.", ua = "Обвіяні вітром трави надають вам сповільнене падіння наступного разу, коли ви падатимете далі ніж на 40 ярдів." },
    { en = "Woodcarving goods craft $ev1% faster.|n|n+$ev2 $en2 when making Woodcarving goods.", ua = "Вироби Різьблення по дереву виготовляються на $ev1% швидше.|n|n+$ev2 $en2 під час виготовлення виробів Різьблення по дереву." },
    { en = "Work under the Haranir to learn how to create Professions-enhancing phials. Gain +$ev1 $en1 while crafting Haranir phials and Cauldron of Sin'dorei Flasks per point in this specialization.", ua = "Працюйте під керівництвом гаранірів, щоб навчитися створювати фіали, що покращують професії. Отримуйте +$ev1 $en1 під час виготовлення фіалів гаранірів і Казана Флаконів Сін'дорей за кожне очко в цій спеціалізації." },
    { en = "Yield more Light potions when Multicrafting.", ua = "Отримуйте більше зілля Світла під час Багатовиробництва." },
    { en = "Yield more Void potions when Multicrafting.", ua = "Отримуйте більше зілля Порожнечі під час Багатовиробництва." },
    { en = "You are able to control the cosmic energies to a certain extent, causing more herb chunks to come into being upon Overloading a Voidbound herb.", ua = "Ви певною мірою здатні керувати космічними енергіями, завдяки чому під час Перевантаження трави, зв'язаної з Порожнечею, утворюється більше фрагментів трав." },
    { en = "You are able to gather more elemental essence from elementally-charged herbs.", ua = "Ви можете зібрати більше стихійної есенції з трав, заряджених стихіями." },
    { en = "You are now able to collect Crystalline Verdant Seeds while gathering Crystallized herbs.", ua = "Тепер ви можете збирати Кристалічне Зелене Насіння під час збору кристалізованих трав." },
    { en = "You are now able to collect Glowing Seeds while gathering Lightbloomed herbs.", ua = "Тепер ви можете збирати Сяйливе Насіння під час збору світлоцвітних трав." },
    { en = "You are now able to collect Irradiated Verdant Seeds while gathering Irradiated herbs.", ua = "Тепер ви можете збирати Опромінене Зелене Насіння під час збору опромінених трав." },
    { en = "You are now able to collect Primal Seeds while gathering Primal herbs.", ua = "Тепер ви можете збирати Первісне Насіння під час збору первісних трав." },
    { en = "You are now able to collect Sporefused Verdant Seeds while gathering Sporefused herbs.", ua = "Тепер ви можете збирати Спорозлите Зелене Насіння під час збору спорозлитих трав." },
    { en = "You are now able to collect Wild Seeds while gathering Wild herbs.", ua = "Тепер ви можете збирати Дике Насіння під час збору диких трав." },
    { en = "You are now able to retrieve Agitated Seeds sometimes while gathering herbs.", ua = "Тепер ви іноді можете здобувати Збурене Насіння під час збору трав." },
    { en = "You are now able to retrieve Decayed Seeds sometimes while gathering herbs.", ua = "Тепер ви іноді можете здобувати Зогниле Насіння під час збору трав." },
    { en = "You are now able to retrieve Propagating Seeds sometimes while gathering herbs.", ua = "Тепер ви іноді можете здобувати Насіння Розростання під час збору трав." },
    { en = "You can attune with Primal herbs on a deeper level, allowing you to transfer an additional 20% of your Health to them.", ua = "Ви можете глибше поєднатися з первісними травами, що дозволяє передати їм додаткові 20% вашого Здоров'я." },
    { en = "You can channel an additional 20% health into a Primal deposit to gain additional resources.", ua = "Ви можете спрямувати додаткові 20% здоров'я в первісне родовище, щоб отримати додаткові ресурси." },
    { en = "You can now apply Embellishments to your crafted guns to give them powerful effects.", ua = "Тепер ви можете застосовувати Оздоблення до виготовлених вами рушниць, щоб надати їм потужних ефектів." },
    { en = "You can now create $@spellname435338 once a day which contain a small hoard of Extravagant Emeralds.", ua = "Тепер ви можете створювати $@spellname435338 раз на день, що містить невеликий скарб Екстравагантних Смарагдів." },
    { en = "You can now create $@spellname435339 once a day which contain a small hoard of Radiant Rubies.", ua = "Тепер ви можете створювати $@spellname435339 раз на день, що містить невеликий скарб Промінистих Рубінів." },
    { en = "You can now create $@spellname435369 once a day which contain a small hoard of Ostentatious Onyxes.", ua = "Тепер ви можете створювати $@spellname435369 раз на день, що містить невеликий скарб Показних Оніксів." },
    { en = "You can now create $@spellname435370 once a day which contain a small hoard of Stunning Sapphires.", ua = "Тепер ви можете створювати $@spellname435370 раз на день, що містить невеликий скарб Приголомшливих Сапфірів." },
    { en = "You can now discover Prismatic Ore when prospecting, which itself can be prospected for higher gem yield.", ua = "Тепер під час просіювання ви можете виявити Призматичну Руду, яку теж можна просіяти задля більшого виходу самоцвітів." },
    { en = "You can now discover recipes that use Decay as a reagent from Potion and Phial Experimentation.", ua = "Тепер ви можете відкривати рецепти, що використовують Гниль як реагент, під час Експериментування зі Зіллям і Фіалами." },
    { en = "You can now learn advanced profession equipment recipes from studying scribbled notes.", ua = "Тепер ви можете вивчати рецепти вдосконаленого професійного спорядження, вивчаючи нашкрябані нотатки." },
    { en = "You can now mine while mounted at Midnight deposits.", ua = "Тепер ви можете видобувати руду верхи біля родовищ Опівночі." },
    { en = "You can now mine while mounted in Khaz Algar.", ua = "Тепер ви можете видобувати руду верхи в Каз Алґарі." },
    { en = "You can now use Missives when crafting guns to determine their secondary stats.", ua = "Тепер ви можете використовувати Послання під час виготовлення рушниць, щоб визначати їхні вторинні характеристики." },
    { en = "You can now use Missives when crafting profession tools to determine their crafting stats.", ua = "Тепер ви можете використовувати Послання під час виготовлення професійних інструментів, щоб визначати їхні характеристики виготовлення." },
    { en = "You can receive additional Writhing Samples when harvesting creatures summoned when overloading Weeping deposits.", ua = "Ви можете отримати додаткові Звивисті Зразки під час обробки істот, викликаних при перевантаженні Плакучих родовищ." },
    { en = "You can receive more Writhing Samples from the creature summoned by Overloading an Altered herb.", ua = "Ви можете отримати більше Звивистих Зразків від істоти, викликаної Перевантаженням Зміненої трави." },
    { en = "You consume +$ev1 $en1 when crafting carveable equipment.", ua = "Ви споживаєте +$ev1 $en1 під час виготовлення різьблюваного спорядження." },
    { en = "You gain an additional charge of $@spellname1223014.", ua = "Ви отримуєте додатковий заряд $@spellname1223014." },
    { en = "You gain an additional charge of $@spellname423395.", ua = "Ви отримуєте додатковий заряд $@spellname423395." },
    { en = "You have a chance of recovering salvageable parts when digging through meat piles caused by bombs.", ua = "Є шанс здобути придатні деталі, коли ви риєтеся в купах м'яса, залишених бомбами." },
    { en = "You have a chance to create more Eversinging Dust when disenchanting Uncommon Midnight equipment.", ua = "Є шанс створити більше Вічноспівного Пилу під час розчаклування Незвичайного спорядження Опівночі." },
    { en = "You have a chance to create more Gleaming Shards when disenchanting Rare equipment.", ua = "Є шанс створити більше Мерехтливих Уламків під час розчаклування Рідкісного спорядження." },
    { en = "You have a chance to create more Radiant Shards when disenchanting Rare Midnight equipment.", ua = "Є шанс створити більше Промінистих Уламків під час розчаклування Рідкісного спорядження Опівночі." },
    { en = "You have a chance to create more Storm Dust when disenchanting Uncommon equipment.", ua = "Є шанс створити більше Штормового Пилу під час розчаклування Незвичайного спорядження." },
    { en = "You have a chance to extract some of Khaz Algar's native magical essences when disenchanting Epic equipment.", ua = "Є шанс видобути частину рідних магічних есенцій Каз Алґара під час розчаклування Епічного спорядження." },
    { en = "You have a chance to extract some of Midnight's native magical essences when disenchanting Epic Midnight equipment.", ua = "Є шанс видобути частину рідних магічних есенцій Опівночі під час розчаклування Епічного спорядження Опівночі." },
    { en = "You have a chance to find Majestic Materials that are unique to Renowned Beasts when skinning them.", ua = "Є шанс знайти Величні Матеріали, унікальні для Прославлених Звірів, коли ви їх білуєте." },
    { en = "You have a chance to find gems whenever you mine.", ua = "Є шанс знайти самоцвіти щоразу, коли ви видобуваєте руду." },
