    { en = "You have a chance to gather additional Bubble Poppy.", ua = "Є шанс зібрати додатковий Бульбашковий Мак." },
    { en = "You have a chance to gather additional Hochenblume.", ua = "Є шанс зібрати додатковий Гохенблюм." },
    { en = "You have a chance to gather additional Saxifrage.", ua = "Є шанс зібрати додатковий Ломикамінь." },
    { en = "You have a chance to gather additional Writhebark.", ua = "Є шанс зібрати додаткову Звивокору." },
    { en = "You have a chance to gather meat while skinning certain creatures of the Dragon Isles.", ua = "Є шанс зібрати м'ясо під час білування певних істот Драконових Островів." },
    { en = "You have a chance to receive additional Gleaming Transmutagen when performing acts of $@spellname430315 or Transmutation.", ua = "Ви маєте шанс отримати додатковий Мерехтливий трансмутаген, застосовуючи $@spellname430315 або Трансмутацію." },
    { en = "You have a chance to receive additional Mercurial Transmutagen when performing acts of $@spellname430315 or Transmutation.", ua = "Ви маєте шанс отримати додатковий Ртутний трансмутаген, застосовуючи $@spellname430315 або Трансмутацію." },
    { en = "You have a chance to receive additional Ominous Transmutagen when performing acts of $@spellname430315 or Transmutation.", ua = "Ви маєте шанс отримати додатковий Зловісний трансмутаген, застосовуючи $@spellname430315 або Трансмутацію." },
    { en = "You have a chance to receive additional Volatile Transmutagen when performing acts of $@spellname430315 or Transmutation.", ua = "Ви маєте шанс отримати додатковий Нестабільний трансмутаген, застосовуючи $@spellname430315 або Трансмутацію." },
    { en = "You have a chance to receive additional transmutagen when performing acts of $@spellname430315.", ua = "Ви маєте шанс отримати додатковий трансмутаген, застосовуючи $@spellname430315." },
    { en = "You have a chance to retrieve double the Majestic Materials when skinning Renowned Beasts.", ua = "Ви маєте шанс здобути вдвічі більше Величних матеріалів, білуючи Уславлених звірів." },
    { en = "You have a chance to uncover an Illimited Diamond when mining rich ore deposits.", ua = "Ви маєте шанс знайти Безмежний діамант, видобуваючи багаті поклади руди." },
    { en = "You have a chance while skinning to find Bizarrely-Shaped Stomachs. What could possibly be inside them?", ua = "Ви маєте шанс під час білування знайти Шлунки химерної форми. Що ж може бути всередині них?" },
    { en = "You have a chance while skinning to find Curiously-Shaped Stomachs. Who knows what might be inside?", ua = "Ви маєте шанс під час білування знайти Шлунки чудернацької форми. Хтозна, що всередині?" },
    { en = "You have a small chance to also gather some meat for cooking when skinning the creatures of this region.|n|nLearn a sub-specialization of your choice.", ua = "Ви маєте невеликий шанс також зібрати трохи м'яса для кулінарії, білуючи істот цього регіону.|n|nВивчіть підспеціалізацію на свій вибір." },
    { en = "You have a small chance to find a Radiant Stomach when skinning the creatures of this region. Who knows what may be inside?... And why is it glowing?", ua = "Ви маєте невеликий шанс знайти Осяйний шлунок, білуючи істот цього регіону. Хтозна, що всередині?... І чому він світиться?" },
    { en = "You have a small chance to find species-specific reagents when skinning the creatures of the Midnight region.", ua = "Ви маєте невеликий шанс знайти реагенти для певних видів, білуючи істот регіону Опівночі." },
    { en = "You have a small chance to receive additional reagents when prospecting.", ua = "Ви маєте невеликий шанс отримати додаткові реагенти під час розвідки руди." },
    { en = "You have a small increased chance to gather hides while skinning creatures in the Dragon Isles.", ua = "Ви маєте трохи підвищений шанс зібрати шкури, білуючи істот на Драконових Островах." },
    { en = "You have a very rare chance of finding Eversong Diamond while Prospecting Brilliant Silver.", ua = "Ви маєте дуже рідкісний шанс знайти Діамант Вічної Пісні під час розвідки Блискучого срібла." },
    { en = "You have a very rare chance of finding Eversong Diamond while Prospecting Umbral Tin.", ua = "Ви маєте дуже рідкісний шанс знайти Діамант Вічної Пісні під час розвідки Умбрального олова." },
    { en = "You have an extremely rare chance of finding Eversong Diamond while Prospecting Refulgent Copper.", ua = "Ви маєте надзвичайно рідкісний шанс знайти Діамант Вічної Пісні під час розвідки Променистої міді." },
    { en = "You have attuned yourself to the magical spores, and can see camoflauged herbs while affected by them.", ua = "Ви налаштувалися на магічні спори й можете бачити замасковані трави, поки перебуваєте під їхнім впливом." },
    { en = "You have honed your abilities, and your carving mastery increases the chances of yielding additional meat while skinning certain creatures of the Dragon Isles.", ua = "Ви відточили свої вміння, і ваша майстерність оброблення туш підвищує шанс отримати додаткове м'ясо, білуючи певних істот на Драконових Островах." },
    { en = "You have learned all there is to know about luring the elusive creatures of Khaz Algar. You can now make the $@spellname442655 for summoning a powerful creature in a specific location. In addition, you can summon rare creatures hiding in specific places.", ua = "Ви дізналися все про приманювання невловних істот Каз Алґару. Тепер ви можете виготовити $@spellname442655, щоб прикликати могутню істоту в певному місці. Крім того, ви можете прикликати рідкісних істот, що ховаються в певних місцях." },
    { en = "You have learned how to avoid getting caught in the sticky clutches of Webbed Ore Deposits.", ua = "Ви навчилися уникати липких обіймів Павутинних покладів руди." },
    { en = "You have seen the Light! Gain +$ev1 $en1 while crafting Light potions per point in this specialization.", ua = "Ви побачили Світло! Отримуйте +$ev1 $en1, виготовляючи зілля Світла, за кожне очко в цій спеціалізації." },
    { en = "You may now apply Safety Components when crafting bracers to enhance tinker functionality.", ua = "Тепер ви можете застосовувати Запобіжні компоненти, виготовляючи наручі, щоб покращити функціональність пристроїв." },
    { en = "You may now apply Safety Components when crafting goggles to enhance tinker functionality.", ua = "Тепер ви можете застосовувати Запобіжні компоненти, виготовляючи окуляри, щоб покращити функціональність пристроїв." },
    { en = "You may now apply enchanted crests to increase the power of your crafted bracers.", ua = "Тепер ви можете застосовувати зачаровані герби, щоб збільшити потужність виготовлених вами наручів." },
    { en = "You may now apply enchanted crests to increase the power of your crafted goggles.", ua = "Тепер ви можете застосовувати зачаровані герби, щоб збільшити потужність виготовлених вами окулярів." },
    { en = "You may now apply enchanted crests to increase the power of your crafted guns.", ua = "Тепер ви можете застосовувати зачаровані герби, щоб збільшити потужність виготовлених вами рушниць." },
    { en = "You may now discover Mercurial Transmutations by performing Thaumaturgy on Mercurial Transmutagen.", ua = "Тепер ви можете відкривати Ртутні трансмутації, застосовуючи Тавматургію до Ртутного трансмутагену." },
    { en = "You may now discover Ominous Transmutations by performing Thaumaturgy on Ominous Transmutagen.", ua = "Тепер ви можете відкривати Зловісні трансмутації, застосовуючи Тавматургію до Зловісного трансмутагену." },
    { en = "You may now discover Volatile Transmutations by performing Thaumaturgy on Volatile Transmutagen.", ua = "Тепер ви можете відкривати Нестабільні трансмутації, застосовуючи Тавматургію до Нестабільного трансмутагену." },
    { en = "You may now discover engineering bracer recipes from Comprehensibly Organized Ideas.|n|nVisit your local Engineering trainer to learn the schematic for bracers of your armor type.", ua = "Тепер ви можете відкривати інженерні рецепти наручів зі «Зрозуміло впорядкованих ідей».|n|nВідвідайте місцевого наставника Інженерії, щоб вивчити схему наручів для вашого типу броні." },
    { en = "You may now discover engineering goggle recipes from Comprehensibly Organized Ideas.|n|nVisit your local Engineering trainer to learn the schematic for goggles of your armor type.", ua = "Тепер ви можете відкривати інженерні рецепти окулярів зі «Зрозуміло впорядкованих ідей».|n|nВідвідайте місцевого наставника Інженерії, щоб вивчити схему окулярів для вашого типу броні." },
    { en = "You may now sometimes find certain refurbished tinkers from the Dragon Isles when you $@spellname447310. These tinkers have been reconfigured with Algari circuitry to be compatible with modern equipment.", ua = "Тепер ви іноді можете знаходити певні відновлені пристрої з Драконових Островів, використовуючи $@spellname447310. Ці пристрої переналаштовано за допомогою алґарських схем, щоб зробити їх сумісними із сучасним спорядженням." },
    { en = "You may now sometimes find lost engineering toys from the Dragon Isles when you $@spellname447310.", ua = "Тепер ви іноді можете знаходити загублені інженерні іграшки з Драконових Островів, використовуючи $@spellname447310." },
    { en = "You may now sometimes recover Flasks as a result from experimenting with Arathor's Spears.", ua = "Тепер ви іноді можете відновлювати Флакони внаслідок експериментів зі Списами Аратора." },
    { en = "You may now sometimes recover Flasks as a result from experimenting with Blessing Blossoms.", ua = "Тепер ви іноді можете відновлювати Флакони внаслідок експериментів із Благословенними квітами." },
    { en = "You may now sometimes recover Flasks as a result from experimenting with Luredrops.", ua = "Тепер ви іноді можете відновлювати Флакони внаслідок експериментів із Краплями-приманками." },
    { en = "You may now sometimes recover Flasks as a result from experimenting with Mycobloom.", ua = "Тепер ви іноді можете відновлювати Флакони внаслідок експериментів із Грибоцвітом." },
    { en = "You may now sometimes recover Flasks as a result from experimenting with Orbinids.", ua = "Тепер ви іноді можете відновлювати Флакони внаслідок експериментів з Орбінідами." },
    { en = "You may now use Cogwheels when crafting bracers to determine their secondary stat.", ua = "Тепер ви можете використовувати Шестерні, виготовляючи наручі, щоб визначити їхню вторинну характеристику." },
    { en = "You may now use Cogwheels when crafting goggles to determine their secondary stat.", ua = "Тепер ви можете використовувати Шестерні, виготовляючи окуляри, щоб визначити їхню вторинну характеристику." },
    { en = "You no longer damage uncovered Null Stones when gathering Aqirite.", ua = "Ви більше не пошкоджуєте виявлені Нуль-камені, коли видобуваєте акірит." },
    { en = "You no longer damage uncovered Null Stones when gathering Bismuth.", ua = "Ви більше не пошкоджуєте виявлені Нуль-камені, коли видобуваєте бісмут." },
    { en = "You no longer damage uncovered Null Stones when gathering Ironclaw.", ua = "Ви більше не пошкоджуєте виявлені Нуль-камені, коли видобуваєте залізокіготь." },
    { en = "You now gather from armed mining deposits much quicker, resulting in a much lower chance of a pickaxe related accident.", ua = "Тепер ви видобуваєте із замінованих рудних покладів значно швидше, що суттєво знижує ймовірність нещасного випадку з кайлом." },
    { en = "You now glance at your tinker control panels instead of pressing random buttons, increasing their success chance by 5%.", ua = "Тепер ви поглядаєте на панелі керування своїх пристроїв, замість того щоб натискати випадкові кнопки, що підвищує їхній шанс успіху на 5%." },
    { en = "You now have a chance to acquire a Radiant Ruby when prospecting Aqirite.", ua = "Тепер ви маєте шанс здобути Осяйний рубін під час розвідки акіриту." },
    { en = "You now have a chance to acquire a Stunning Sapphire when prospecting Ironclaw Ore.", ua = "Тепер ви маєте шанс здобути Приголомшливий сапфір під час розвідки залізокігтю." },
    { en = "You now have a chance to acquire an Extravagant Emerald when prospecting Ironclaw Ore.", ua = "Тепер ви маєте шанс здобути Розкішний смарагд під час розвідки залізокігтю." },
    { en = "You now have a chance to acquire an Ostentatious Onyx when prospecting Aqirite.", ua = "Тепер ви маєте шанс здобути Показний онікс під час розвідки акіриту." },
    { en = "You now have a chance to discover a Radiant Ruby when Prospecting Null Stone as an extra by-product.", ua = "Тепер ви маєте шанс знайти Осяйний рубін як додатковий побічний продукт під час розвідки Нуль-каменю." },
    { en = "You now have a chance to discover a Stunning Sapphire when Prospecting Null Stone as an extra by-product.", ua = "Тепер ви маєте шанс знайти Приголомшливий сапфір як додатковий побічний продукт під час розвідки Нуль-каменю." },
    { en = "You now have a chance to discover an Extravagant Emerald when Prospecting Null Stone as an extra by-product.", ua = "Тепер ви маєте шанс знайти Розкішний смарагд як додатковий побічний продукт під час розвідки Нуль-каменю." },
    { en = "You now have a chance to discover an Ostentatious Onyx when Prospecting Null Stone as an extra by-product.", ua = "Тепер ви маєте шанс знайти Показний онікс як додатковий побічний продукт під час розвідки Нуль-каменю." },
    { en = "You now have a chance to uncover Crushed Gemstones of an equivalent quality to the ore you Prospect.", ua = "Тепер ви маєте шанс знайти Подрібнені самоцвіти якості, що відповідає руді, яку ви розвідуєте." },
    { en = "You now have a chance to uncover an Ambivalent Amber as an additional byproduct when Prospecting.", ua = "Тепер ви маєте шанс знайти Амбівалентний бурштин як додатковий побічний продукт під час розвідки." },
    { en = "You now have a small chance of finding a second Extravagant Emerald when you uncover one from prospecting.", ua = "Тепер ви маєте невеликий шанс знайти другий Розкішний смарагд, коли знаходите один під час розвідки." },
    { en = "You now have a small chance of finding a second Ostentatious Onyx when you uncover one from prospecting.", ua = "Тепер ви маєте невеликий шанс знайти другий Показний онікс, коли знаходите один під час розвідки." },
    { en = "You now have a small chance of finding a second Radiant Ruby when you uncover one from prospecting.", ua = "Тепер ви маєте невеликий шанс знайти другий Осяйний рубін, коли знаходите один під час розвідки." },
    { en = "You now have a small chance of finding a second Stunning Sapphire when you uncover one from prospecting.", ua = "Тепер ви маєте невеликий шанс знайти другий Приголомшливий сапфір, коли знаходите один під час розвідки." },
    { en = "You now listen for the whirring of tinker cooling units instead of melting their circuits, increasing their success chance by 7%.|n|nYour level of caution is now equivalent to the benefits provided by the Recalibrated Safety Switch component and no longer need to depend on it for optimal success chance.", ua = "Тепер ви прислухаєтеся до дзижчання охолоджувальних блоків своїх пристроїв, замість того щоб плавити їхні схеми, що підвищує їхній шанс успіху на 7%.|n|nВаш рівень обережності тепер рівноцінний перевагам, які надає компонент «Перекалібрований запобіжний вимикач», тож вам більше не потрібно покладатися на нього для оптимального шансу успіху." },
    { en = "You now often recover scrap when using your devices.", ua = "Тепер ви часто відновлюєте брухт, використовуючи свої пристрої." },
    { en = "You now think twice before using your tinkers, increasing their success chance by 3%.", ua = "Тепер ви двічі подумаєте, перш ніж використати свої пристрої, що підвищує їхній шанс успіху на 3%." },
    { en = "You recieve additional rare meat when using $@spellname442615.", ua = "Ви отримуєте додаткове рідкісне м'ясо, використовуючи $@spellname442615." },
    { en = "You see less dangerous hallucinations while affected by the magical spores.", ua = "Ви бачите менш небезпечні галюцинації, поки перебуваєте під впливом магічних спор." },
    { en = "You take 3% reduced damage from enemies struck by Empyrean Hammer for 8 sec, stacking up to 3 times.", ua = "Ви отримуєте на 3% менше шкоди від ворогів, уражених Емпірейним молотом, протягом 8 сек; ефект складається до 3 разів." },
    { en = "Your Earthen Master's Hammer now freely repairs this slot.", ua = "Ваш Молот Майстра-земельника тепер безкоштовно ремонтує цю комірку." },
    { en = "Your Earthen Master's Hammer now freely repairs your axes and polearms.", ua = "Ваш Молот Майстра-земельника тепер безкоштовно ремонтує ваші сокири та древкову зброю." },
    { en = "Your Earthen Master's Hammer now freely repairs your long bladed weapons.", ua = "Ваш Молот Майстра-земельника тепер безкоштовно ремонтує вашу довгу клинкову зброю." },
    { en = "Your Earthen Master's Hammer now freely repairs your maces.", ua = "Ваш Молот Майстра-земельника тепер безкоштовно ремонтує ваші булави." },
