    { en = "Your Finesse has a chance to yield additional Orbinid.", ua = "Ваша Вправність має шанс дати додатковий Орбінід." },
    { en = "Your Finesse has a chance to yield additional Sanguithorn.", ua = "Ваша Вправність має шанс дати додатковий Кривавотерн." },
    { en = "Your Finesse has a chance to yield additional Saxifrage.", ua = "Ваша Вправність має шанс дати додатковий Ломикамінь." },
    { en = "Your Finesse has a chance to yield additional Tranquility Bloom.", ua = "Ваша Вправність має шанс дати додатковий Цвіт Спокою." },
    { en = "Your Finesse has a chance to yield additional Writhebark.", ua = "Ваша Вправність має шанс дати додаткову Звивокору." },
    { en = "Your advanced knowledge of cultivation has honed you, allowing you to find seeds more often than before while gathering herbs.", ua = "Ваші поглиблені знання про вирощування відточили вашу майстерність, дозволяючи знаходити насіння частіше, ніж раніше, під час збирання трав." },
    { en = "Your adventures have brought you to lands both familiar and new. The familiar has changed, and the new brings mysteries to explore. How have the lands affected some of the herbs here, and how can you better gather them?", ua = "Ваші пригоди привели вас до земель — як знайомих, так і нових. Знайоме змінилося, а нове приховує таємниці, які варто розкрити. Як ці землі вплинули на деякі тутешні трави і як їх краще збирати?" },
    { en = "Your armor is increased by an amount within a delve.", ua = "Ваша броня збільшена на певну величину в межах Глибини." },
    { en = "Your attunement to the chaotic powers of the Void allow you to teleport back to your original location for a limited time after stepping through a Reality Tear.", ua = "Ваше суголосся з хаотичними силами Порожнечі дозволяє вам протягом обмеженого часу телепортуватися назад до початкового місця після проходу крізь Розрив Реальності." },
    { en = "Your attunement to the chaotic powers of the Void allows you to teleport back to your original location for a limited time after stepping through a Reality Tear.", ua = "Ваше суголосся з хаотичними силами Порожнечі дозволяє вам протягом обмеженого часу телепортуватися назад до початкового місця після проходу крізь Розрив Реальності." },
    { en = "Your auto attacks grant a charge, at 50 stacks override pulverize and supercharge it!", ua = "Ваші автоатаки дають заряд; при 50 накопиченнях замінюють «Подрібнення» і суперзаряджають його!" },
    { en = "Your botanical knowledge allows you to activate your $@spellname439871, getting double the herbs from your next gather.", ua = "Ваші ботанічні знання дозволяють активувати $@spellname439871, завдяки чому наступний збір дасть удвічі більше трав." },
    { en = "Your chance of finding Eversong Diamond while Prospecting Dazzling Thorium is increased.", ua = "Ваш шанс знайти Діамант Вічної Пісні під час сондування Осяйного торію збільшено." },
    { en = "Your chance to find cloth from humanoids in Khaz Algar increases by 10%.", ua = "Ваш шанс знайти тканину з гуманоїдів у Каз Алґарі збільшується на 10%." },
    { en = "Your chance to find cloth from humanoids in Khaz Algar increases by 5%.", ua = "Ваш шанс знайти тканину з гуманоїдів у Каз Алґарі збільшується на 5%." },
    { en = "Your chance to gather Majestic Materials from Renowned Beasts is increased.", ua = "Ваш шанс зібрати Величні матеріали зі Славетних звірів збільшено." },
    { en = "Your chances of gathering species-specific reagents from creatures in the Midnight region are increased.", ua = "Ваші шанси зібрати видоспецифічні реагенти з істот у регіоні Опівночі збільшено." },
    { en = "Your cultivation experience has taught you potent techniques, allowing you to find all varieties of Verdant Seeds more often while gathering.", ua = "Ваш досвід вирощування навчив вас дієвих прийомів, дозволяючи частіше знаходити всі різновиди Буйного насіння під час збирання." },
    { en = "Your domain knowledge reaches new heights, and you gain +$ev1 $en1 while gathering Lush herbs.", ua = "Ваші фахові знання сягають нових вершин, і ви отримуєте +$ev1 $en1 під час збирання Пишних трав." },
    { en = "Your first act of $@spellname430315 each day yields a significant amount of extra transmutagen.", ua = "Перше застосування $@spellname430315 щодня дає значну кількість додаткового трансмутагену." },
    { en = "Your knowledge grows, and you learn a new technique to sometimes yield additional meat while skinning certain creatures of the Dragon Isles.", ua = "Ваші знання зростають, і ви опановуєте новий прийом, що інколи дає додаткове м'ясо під час білування певних істот Драконових Островів." },
    { en = "Your knowledge of Altered herbs and their dangerous side effects prepares you, reducing the damage you take from them.", ua = "Ваші знання про Змінені трави та їхні небезпечні побічні ефекти готують вас, зменшуючи шкоду, яку ви від них отримуєте." },
    { en = "Your knowledge of Decayed herbs allows you to properly prepare, reducing the negative effects you suffer while afflicted with Decay.", ua = "Ваші знання про Гнилі трави дозволяють належно підготуватися, зменшуючи негативні ефекти, від яких ви потерпаєте під впливом Гниття." },
    { en = "Your knowledge of Frigid herbs allows you to properly prepare, causing you to no longer slip and fall while walking near them.", ua = "Ваші знання про Крижані трави дозволяють належно підготуватися, тож ви більше не послизаєтесь і не падаєте, проходячи повз них." },
    { en = "Your knowledge of Windswept herbs allows you to properly prepare, reducing the amount they push you back by 50%.", ua = "Ваші знання про Обвітрені трави дозволяють належно підготуватися, зменшуючи силу, з якою вони вас відкидають, на 50%." },
    { en = "Your knowledge of anatomy gives you an upper hand, increasing your damage against beasts and dragonkin while outdoors in the Dragon Isles.", ua = "Ваші знання анатомії дають вам перевагу, збільшуючи вашу шкоду по звірах і драконідах просто неба на Драконових Островах." },
    { en = "Your knowledge of cultivation allows you to activate your $@spellname1221172, getting double the herbs from your next gathering attempt.", ua = "Ваші знання про вирощування дозволяють активувати $@spellname1221172, завдяки чому наступна спроба збору дасть удвічі більше трав." },
    { en = "Your mastery of botany is such that you can gather herbs while mounted in the Dragon Isles.|n|nYour botanical mastery also helps you locate hidden rarities, gaining +$ev1 $en1 while gathering herbs.", ua = "Ваша майстерність ботаніки така, що ви можете збирати трави верхи на Драконових Островах.|n|nВаша ботанічна майстерність також допомагає знаходити приховані рідкості, даючи +$ev1 $en1 під час збирання трав." },
    { en = "Your maximum possible yield when gathering Midnight herbs is increased by $ev1.", ua = "Ваш максимально можливий врожай під час збирання трав Опівночі збільшено на $ev1." },
    { en = "Your maximum stacks of $@spellname433187 are doubled when crafting potions.", ua = "Ваша максимальна кількість накопичень $@spellname433187 подвоюється під час виготовлення зілля." },
    { en = "Your minimum yield when gathering Midnight herbs is increased by $ev1.|n|nMaster the basics of Midnight Herbalism harvesting, unlocking the final sub-specialization.", ua = "Ваш мінімальний врожай під час збирання трав Опівночі збільшено на $ev1.|n|nОпануйте основи збору в травництві Опівночі, відкриваючи останню підспеціалізацію." },
    { en = "Your new knowledge of cultivation techniques allows you to gather seeds more often than before while gathering herbs.", ua = "Ваші нові знання про прийоми вирощування дозволяють збирати насіння частіше, ніж раніше, під час збирання трав." },
    { en = "Your phase dives in K'aresh now last x min longer.", ua = "Ваші фазові занурення в Кареші тепер тривають на x хв довше." },
    { en = "Your senses are now keen enough to notice Nocturnal Lotus where you may not have otherwise, allowing you to find it more often alongside Argentleaf.", ua = "Ваші чуття тепер достатньо гострі, щоб помічати Нічний лотос там, де інакше ви могли б його не побачити, дозволяючи знаходити його частіше поряд зі Срібнолистом." },
    { en = "Your senses are now keen enough to notice Nocturnal Lotus where you may not have otherwise, allowing you to find it more often alongside Azeroot.", ua = "Ваші чуття тепер достатньо гострі, щоб помічати Нічний лотос там, де інакше ви могли б його не побачити, дозволяючи знаходити його частіше поряд з Азерокоренем." },
    { en = "Your senses are now keen enough to notice Nocturnal Lotus where you may not have otherwise, allowing you to find it more often alongside Mana Lily.", ua = "Ваші чуття тепер достатньо гострі, щоб помічати Нічний лотос там, де інакше ви могли б його не побачити, дозволяючи знаходити його частіше поряд з Мановою лілією." },
    { en = "Your senses are now keen enough to notice Nocturnal Lotus where you may not have otherwise, allowing you to find it more often alongside Sanguithorn.", ua = "Ваші чуття тепер достатньо гострі, щоб помічати Нічний лотос там, де інакше ви могли б його не побачити, дозволяючи знаходити його частіше поряд з Кривавотерном." },
    { en = "Your senses are now keen enough to notice Nocturnal Lotus where you may not have otherwise, allowing you to find it more often alongside Tranquility Bloom.", ua = "Ваші чуття тепер достатньо гострі, щоб помічати Нічний лотос там, де інакше ви могли б його не побачити, дозволяючи знаходити його частіше поряд із Цвітом Спокою." },
    { en = "Your senses sharpen, allowing you to find Null Lotus more often when gathering Arathor's Spear.", ua = "Ваші чуття загострюються, дозволяючи частіше знаходити Нуль-лотос під час збирання Списа Аратора." },
    { en = "Your senses sharpen, allowing you to find Null Lotus more often when gathering Blessing Blossom.", ua = "Ваші чуття загострюються, дозволяючи частіше знаходити Нуль-лотос під час збирання Цвіту Благословення." },
    { en = "Your senses sharpen, allowing you to find Null Lotus more often when gathering Luredrop.", ua = "Ваші чуття загострюються, дозволяючи частіше знаходити Нуль-лотос під час збирання Принадокраплі." },
    { en = "Your senses sharpen, allowing you to find Null Lotus more often when gathering Mycobloom.", ua = "Ваші чуття загострюються, дозволяючи частіше знаходити Нуль-лотос під час збирання Грибоцвіту." },
    { en = "Your senses sharpen, allowing you to find Null Lotus more often when gathering Orbinid.", ua = "Ваші чуття загострюються, дозволяючи частіше знаходити Нуль-лотос під час збирання Орбініду." },
    { en = "Your skill at using Bait has reached its peak. Your Elusive Creature Bait can now draw in rare creatures at specific locations, who can be skinned for a chance at the best rewards.", ua = "Ваша майстерність користування Приманкою сягнула вершини. Ваша Приманка для невловних істот тепер може приваблювати рідкісних істот у певних місцях, яких можна білувати заради шансу на найкращі нагороди." },
    { en = "Your skills grow. You can now lure the elite elusive creatures of Khaz Algar.", ua = "Ваша майстерність зростає. Тепер ви можете приманювати елітних невловних істот Каз Алґару." },
    { en = "Your tinkers can no longer catastrophically malfunction.", ua = "Ваші винаходи більше не можуть катастрофічно виходити з ладу." },
    { en = "[NYI] Further improve your connection with Dawnweave, decreasing how quickly you exhaust the magic used to craft Dawnweave Bolts.", ua = "[NYI] Ще більше зміцніть свій зв'язок зі Світанковим плетивом, зменшивши, як швидко ви виснажуєте магію, потрібну для виготовлення сувоїв Світанкового плетива." },
    { en = "[NYI] Further improve your connection with Duskweave, decreasing how quickly you exhaust the magic used to craft Duskweave Bolts.", ua = "[NYI] Ще більше зміцніть свій зв'язок із Присмерковим плетивом, зменшивши, як швидко ви виснажуєте магію, потрібну для виготовлення сувоїв Присмеркового плетива." },
